INSERT INTO "signal_category" ("code", "pack_code", "block_code", "family", "label_ru", "definition_ru", "boundary_ru", "cues_prompt_ru", "synonyms_ru", "anti_cues_ru", "example_ru", "counter_example_ru", "card_note_ru", "weight", "score_rule", "class", "class_by_relation", "kind", "effort", "carries_amount", "asks_us", "inbound_only", "emitted_by", "stage", "display_profile", "recipient_role", "closes_codes", "date_gate", "relevance_days", "trigger_rule", "note_ru", "retired_at", "successor_code") VALUES
  ('SALES_TENDER_INVITATION', 'base', 'A', 'offer', 'Приглашение к участию в тендере / закупке', 'Клиент или заказчик приглашает нас участвовать в тендере, конкурсе, запросе котировок или запросе предложений с процедурой выбора и сроком подачи; либо становится известна публичная закупка, прямо подходящая под наши товары или услуги. Обычно есть срок подачи заявок, документация и порядок определения победителя.', 'Просьба прислать КП без процедуры отбора и без срока подачи — SALES_OFFER_REQUESTED. Просьба прислать прайс для сравнения — SALES_PRICE_REQUEST. Рассылка торговой площадки или агрегатора тендеров «вам может быть интересно» без связи с нашим профилем — нет сигнала. Итоги тендера (победа, проигрыш) — не этот код. Наш собственный поиск закупок — не сигнал клиента.', ARRAY['тендер', 'закупка', '44-ФЗ', '223-ФЗ', 'котировка', 'НМЦК', 'срок подачи заявок', 'приглашаем принять участие']::text[], '{"business":["приглашаем принять участие в закупке","приглашаем к участию в конкурсе","просим направить коммерческое предложение в рамках запроса котировок","объявлен тендер на поставку","конкурсная документация во вложении","закупочная процедура","отбор поставщиков","прошу подать заявку до","проводим конкурентный отбор"],"chat":["у нас тендер на вино, будете участвовать?","скинула ссылку на закупку","запускаем отбор поставщиков, хотите поучаствовать?","закупка висит на площадке до пятницы"],"terms":["44-ФЗ","223-ФЗ","НМЦК","НМЦД","ЕИС","zakupki.gov.ru","ЭТП","РТС-тендер","Сбербанк-АСТ","B2B-Center","запрос котировок","запрос предложений","аукцион в электронной форме","RFP","RFQ","RFI","ТЗ","обеспечение заявки"],"patterns":["«приглашаем к участию в» + «тендере / конкурсе / закупке»","«срок подачи заявок до» + дата","просим направить заявку","«тендер на поставку» + товар","«включены в список участников» (дистрибуция: тендер сети, отельной группы, госзаказчика)"]}'::jsonb, '[{"text":"«пришлите КП на 200 бутылок к празднику»","code":"SALES_OFFER_REQUESTED"},{"text":"«скиньте прайс, сравниваем поставщиков»","code":"SALES_PRICE_REQUEST"},{"text":"«по итогам закупки победителем признан»","code":null},{"text":"рассылка «Подборка тендеров за неделю» от сервиса","code":null}]'::jsonb, '«Приглашаем вашу компанию принять участие в запросе котировок на поставку вин для ресторанов сети, срок подачи заявок — до 25.11 включительно, НМЦК 4,8 млн руб.»', '«Подготовьте, пожалуйста, коммерческое предложение на винную карту нового ресторана» → это SALES_OFFER_REQUESTED: нет процедуры отбора и срока подачи заявок.', 'Напиши, кто проводит закупку, предмет, срок подачи и НМЦК (если есть); шаги — изучить документацию, решить по участию, подготовить заявку к сроку.', 9, 'fixed', 'chance', false, 'event', 'complex', true, true, true, 'both', 'active', NULL, 'opportunity', '{}'::text[], NULL, NULL, NULL, 'Closed by: — (outcome of the tender is a separate event)
Date gate: — (the application deadline goes to `facts.deadlines`, owner = us)
Relevance window: until the application deadline («срок подачи заявок»); default when no deadline is given
Relations: — in v204. Agency pack: merges with `CONTRACT_RETENDER_ANNOUNCED` into one re-pitch card (Maslov §5.5).
Deal effect: per org rule. Usual: deal entry (deal type «тендер»). IN4COM: **deal entry** (chains, hotel groups, state buyers). Agency: stage 1 «Новая возможность».', NULL, NULL),
  ('CONTRACT_TERMINATED', 'base', 'A', 'contract', 'Клиент расторгает договор', 'Клиент активно прекращает действующий договор: направляет уведомление о расторжении, отказ от исполнения или сообщает, что прекращает сотрудничество по договору с определённой даты.', 'Договор просто истёк, а продления нет — CONTRACT_NOT_RENEWED (watchdog). Отказ продлевать на следующий период до окончания срока — в агентском пакете CONTRACT_RENEWAL_DECLINED, в базе — этот код, только если клиент прямо прекращает отношения. Отмена одного заказа — SALES_BOOKING_CANCELLED (в дистрибуции ORDER_CANCELLED). Пауза в работе без расторжения — не этот код. Расторжение по нашей инициативе — не сигнал клиента. Угроза «будем вынуждены расторгнуть» без решения — COMPLAINT_* с эмоцией, не расторжение.', ARRAY['расторгаем договор', 'уведомляем о расторжении', 'односторонний отказ от исполнения договора', 'соглашение о расторжении', 'прекращаем сотрудничество', 'договор прекращает действие с', 'отказываемся от договора', 'больше не будем с вами работать']::text[], '{"business":["настоящим уведомляем о расторжении договора поставки №","направляем уведомление об одностороннем отказе от исполнения договора","просим считать договор расторгнутым с","во вложении соглашение о расторжении","в соответствии с п. договора уведомляем о прекращении","принято решение прекратить сотрудничество","договор будет расторгнут по истечении 30 дней с даты уведомления"],"chat":["мы с вами больше не работаем","всё, расходимся, договор расторгаем","руководство решило уйти от вас","закрываем с вами договор"],"terms":["уведомление о расторжении","соглашение о расторжении","односторонний отказ","ст. 450.1 ГК","ст. 523 ГК","досрочное расторжение"],"patterns":["«уведомляем о» + «расторжении / прекращении»","«расторгнуть договор с» + дата","«прекращаем сотрудничество с» + дата"]}'::jsonb, '[{"text":"«договор заканчивается 31.12, продлевать пока не планируем»","code":"CONTRACT_FRAME_EXPIRY"},{"text":"«отменяем заказ на следующую неделю»","code":"SALES_BOOKING_CANCELLED"},{"text":"«если так пойдёт дальше, будем вынуждены расторгнуть»","code":null},{"text":"«приостанавливаем закупки до нового года»","code":null}]'::jsonb, '«Настоящим уведомляем о расторжении договора поставки № 14/23 в одностороннем порядке с 01.12.2026 в соответствии с п. 9.3.»', '«Если ситуация с поставками не изменится, мы будем вынуждены рассмотреть расторжение договора» → это угроза внутри жалобы (COMPLAINT_TIMING + эмоция), решение не принято.', 'Укажи договор, дату прекращения и названную причину; шаги — связаться с ЛПР клиента, выяснить причину, оценить шанс сохранить отношения и закрыть взаиморасчёты.', 9, 'fixed', 'risk', false, 'event', 'medium', false, false, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Date gate: — (termination date goes to `facts.deadlines`)
Relations: leads over `CONTRACT_NOT_RENEWED` (an act beats the passing of time).
Deal effect: per org rule. Usual: outcome `lost` (or `cancelled`) for an open deal on this contract; otherwise context on the client. Never rewrites a won sale (Maslov §3.3). IN4COM: outcome for the supply-agreement deal.', NULL, NULL),
  ('SALES_BOOKING_RECEIVED', 'base', 'A', 'order', 'Клиент подтвердил заказ (твёрдое обязательство)', 'Клиент даёт обязывающее подтверждение заказа: подписанный заказ или заявку, гарантийное письмо, «согласовываем, запускайте», подписанное КП или спецификацию. Есть твёрдое решение купить, а не намерение.', 'Намерение («скорее всего возьмём», «планируем заказать») — не этот код. Просьба выслать подтверждение заказа от нас — SALES_ORDER_CONFIRMATION_REQUESTED. В организации с пакетом дистрибуции регулярный товарный заказ («отгрузите 12 коробок») — ORDER_REQUESTED, не этот код. Устный выбор поставщика без оформления — агентский PITCH_VERBAL_SELECTION. Оплата счёта — INVOICE_PAID.', ARRAY['подтверждаем заказ', 'согласовываем, запускайте', 'подписанная спецификация во вложении', 'гарантийное письмо', 'КП согласовано', 'принимаем ваше предложение', 'оформляем заказ', 'берём в работу по вашему КП']::text[], '{"business":["настоящим подтверждаем заказ","направляем подписанную заявку","согласовываем коммерческое предложение от","просим приступить к выполнению","гарантируем оплату","подписанный договор-заявка во вложении","принимаем ваше предложение в полном объёме","утверждаем смету"],"chat":["ок, берём","согласовали, запускайте","да, делаем по вашему варианту","подписали, отправила скан","го, заказываем"],"terms":["заявка","спецификация","ДС на поставку","гарантийное письмо","PO","purchase order","акцепт оферты"],"patterns":["«подтверждаем» + «заказ / заявку / объём»","«согласовываем» + «КП / смету»","просим приступить"]}'::jsonb, '[{"text":"«думаю, возьмём, но надо согласовать с директором»","code":null},{"text":"«пришлите подтверждение заказа»","code":"SALES_ORDER_CONFIRMATION_REQUESTED"},{"text":"«отгрузите, пожалуйста, 20 бут. Шабли»","code":"ORDER_REQUESTED"},{"text":"«оплатили счёт»","code":"INVOICE_PAID"}]'::jsonb, '«Коммерческое предложение от 12.11 согласовано, подписанную спецификацию направляем во вложении, просим приступить к поставке.»', '«Ваше предложение нам в целом нравится, обсудим внутри и вернёмся» → интереса недостаточно, решения нет.', 'Укажи, что именно подтверждено, сумму и срок; шаги — зафиксировать заказ, проверить документы, запустить исполнение.', 8, 'fixed', 'chance', false, 'event', 'medium', true, false, true, 'both', 'active', NULL, 'opportunity', '{}'::text[], NULL, NULL, NULL, 'Closes: — (agency: closes the formalisation question of the chosen opportunity, Maslov §5.5)
Relations: — in v204. Successor of retired `SALES_ORDER_CONFIRM`.
Deal effect: per org rule. Usual: stage move to the final stage «Заказ подтверждён» (agency stage 5). IN4COM: off — orders are `ORDER_*` and never move deals in step one (Q26).', NULL, NULL),
  ('CONTRACT_FRAME_EXPIRY', 'base', 'A', 'contract', 'Рамочный или годовой договор заканчивается (менее 8 недель)', 'В переписке обсуждается срок действия рамочного, годового или пролонгируемого договора, и указана дата его окончания; система проверяет, что до неё меньше 8 недель. Также процесс создаёт сигнал по дате окончания договора из CRM.', 'Модель не решает, «скоро ли» дата: она указывает код, когда обсуждается срок и заполнен contractEndDate; сервер отбрасывает код, если дата дальше окна. Клиент сам предлагает продлить — CONTRACT_RENEWAL_INTENT (ведёт). Клиент расторгает — CONTRACT_TERMINATED. Срок действия КП или цены («цены действительны до») — не договор. Разовый договор на один заказ — не этот код.', ARRAY['договор заканчивается', 'срок действия договора до', 'пролонгация', 'продление договора', 'доп. соглашение', 'договор поставки заканчивается', 'истекает срок договора', 'автопролонгация']::text[], '{"business":["срок действия договора истекает 31.12.2026","напоминаем, что договор действует до","просим рассмотреть вопрос пролонгации","необходимо подписать дополнительное соглашение о продлении","договор не предусматривает автоматической пролонгации","по окончании срока действия договора","готовим документы на следующий год"],"chat":["у нас договор до конца года, что дальше?","договор кончается в декабре","надо переподписать договор","давайте решим с договором на следующий год"],"terms":["ДС","доп. соглашение","пролонгация","автопролонгация","рамочный договор","годовой договор","договор поставки","срок действия"],"patterns":["«договор действует до» + дата","«истекает» + дата","«пролонгировать на» + срок"]}'::jsonb, '[{"text":"«продлим договор на следующий год, пришлите ДС»","code":"CONTRACT_RENEWAL_INTENT"},{"text":"«цены в КП действительны до 30.11»","code":null},{"text":"«уведомляем о расторжении»","code":"CONTRACT_TERMINATED"}]'::jsonb, '«Напоминаем, что срок действия договора поставки № 7 истекает 31.12.2026, автоматической пролонгации договор не предусматривает.»', '«Договор у нас бессрочный, условия обсудим весной» → нет даты окончания, нет сигнала.', 'Укажи договор и дату окончания; шаги — проверить условия, связаться с клиентом по продлению, подготовить доп. соглашение заранее.', 8, 'fixed', 'risk', false, 'watchdog', 'medium', true, true, false, 'both', 'active', NULL, 'account', '{}'::text[], '{"fact":"contractEndDate","test":"within","settingKey":"cards.frameExpiryWindowDays","days":56}'::jsonb, NULL, NULL, 'Emitted by: both (parser with date gate; process from the contract end date)
Closed by: — (the IN4COM risk clears with `CONTRACT_RENEWAL_INTENT` or a signed renewal)
Date gate: { fact: `contractEndDate`, test: within 0 to N days after the item, setting: `cards.frameExpiryWindowDays`, window: 56 }
Relevance window: until `contractEndDate`
Relations: `CONTRACT_RENEWAL_INTENT` leads over this code (the opportunity beats the warning).
Deal effect: per org rule. Usual: risk trigger. IN4COM: risk trigger «Договор заканчивается без продления» (no `CONTRACT_RENEWAL_INTENT` in the date window).', NULL, NULL),
  ('SALES_BUDGET_CUT', 'base', 'A', 'account', 'Клиент сокращает бюджет на работу с нами', 'Клиент сообщает, что сокращает бюджет или объём закупок у нас в целом или на период (квартал, год, направление).', 'Один заказ меньше прошлого — не этот код. Отмена конкретного заказа — SALES_BOOKING_CANCELLED (ведёт). Просьба о скидке — SALES_RENEGOTIATION. Сокращение бюджета клиента вообще, без связи с нами (новость о компании), — блок H. В дистрибуции вывод наших позиций из ассортимента — DELISTING_RISK.', ARRAY['сокращаем бюджет', 'урезали бюджет', 'бюджет на следующий год меньше', 'вынуждены сократить объёмы', 'режем расходы', 'оптимизация затрат', 'секвестр', 'заморозили бюджет']::text[], '{"business":["в связи с оптимизацией затрат бюджет на 2027 год сокращён на 30%","вынуждены сократить объём закупок","бюджет по направлению урезан","пересмотр бюджета в сторону уменьшения","лимиты на квартал снижены","финансирование сокращено"],"chat":["бюджет порезали","денег дали меньше","в этом году будем брать сильно меньше","нам срезали лимиты"],"terms":["оптимизация","секвестр","лимиты","бюджет на год","план закупок"],"patterns":["«сокращаем» + «бюджет / объёмы / закупки»","«бюджет меньше на» + %"]}'::jsonb, '[{"text":"«в этот раз возьмём поменьше»","code":null},{"text":"«отменяем заказ»","code":"SALES_BOOKING_CANCELLED"},{"text":"«дайте скидку, иначе не пройдём по бюджету»","code":"SALES_RENEGOTIATION"}]'::jsonb, '«Сообщаем, что бюджет на закупку на 2027 год утверждён на 25% ниже текущего, объёмы по договору придётся сократить.»', '«На Новый год в этот раз возьмём на пару коробок меньше» → это один заказ, не сокращение бюджета.', 'Укажи, на сколько и с какого срока сокращается бюджет; шаги — выяснить причину и приоритеты, предложить вариант в новом бюджете.', 8, 'fixed', 'risk', false, 'event', 'medium', true, false, true, 'both', 'active', NULL, 'opportunity', '{}'::text[], NULL, NULL, NULL, 'Relations: `SALES_BOOKING_CANCELLED` leads over this code (the concrete loss counts).
Deal effect: per org rule. Usual: in-stage context (budget), no stage move. Agency: risk trigger «Сокращение бюджета» (Maslov risk 11). IN4COM: off.', NULL, NULL),
  ('CONTRACT_NOT_RENEWED', 'base', 'A', 'contract', 'Договор истёк и не продлён', 'Дата окончания договора прошла, а продления (ДС, нового договора, подтверждения) нет. Создаётся процессом, не моделью.', 'Активное расторжение клиентом — CONTRACT_TERMINATED. Договор ещё действует, но скоро заканчивается — CONTRACT_FRAME_EXPIRY. Молчание клиента — не отказ: этот код говорит только о том, что срок прошёл без продления.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, 'Договор поставки истёк 31.10; на 01.11 в CRM нет ДС о продлении и нет переписки о продлении.', '', 'Укажи договор и дату окончания; шаги — уточнить у клиента планы на следующий период, предложить продление.', 8, 'fixed', 'risk', false, 'watchdog', 'medium', false, false, false, 'process', 'onHold', NULL, 'account', '{}'::text[], NULL, NULL, '{"ru":"RU: дата окончания договора (contractEndDate из сигналов или из карточки договора) прошла; после неё нет подписанного продления, сигнала CONTRACT_RENEWAL_INTENT с подтверждением или нового договора; один сигнал на договор. EN: the stored contract end date has passed; no renewal, no confirmed CONTRACT_RENEWAL_INTENT and no new contract after it; one signal per contract."}'::jsonb, 'Closed by: — (watchdog clears when a renewal is recorded)
Date gate: — (uses the stored contract end date)
Relations: `CONTRACT_TERMINATED` leads over this code.
Deal effect: per org rule. Usual: risk trigger on the account; no stage move.', NULL, NULL),
  ('SALES_OFFER_SENT', 'base', 'A', 'offer', 'Мы отправили коммерческое предложение', 'Служебное событие: мы (наша организация) отправили клиенту коммерческое предложение, смету или расчёт. Не создаёт карточку; закрывает открытый запрос КП этого клиента и запускает ожидание ответа.', 'Предложение пришло НАМ от поставщика — нет этого кода (поставщики — блок N). Прайс-лист без индивидуального расчёта — не КП: для него нет state-кода (см. Open points). Обещание «пришлём КП завтра» — ещё не отправка. Это исключение из правила «только автор-клиент»: код описывает НАШЕ письмо.', ARRAY['направляем коммерческое предложение', 'во вложении КП', 'направляем предложение', 'высылаем расчёт', 'смета во вложении', 'подготовили для вас предложение', 'как договаривались, отправляю КП', 'предложение действительно до']::text[], '{"business":["направляем в Ваш адрес коммерческое предложение","во вложении КП на поставку","по Вашему запросу подготовили предложение","высылаем расчёт стоимости","предложение действительно до 30.11","готовы обсудить условия"],"chat":["скинул КП на почту","отправила подборку и цены","вот расчёт, посмотрите","КП в файле"],"terms":["КП","ТКП","смета","расчёт","оферта","«подборка» (дистрибуция: подборка вин в карту)"],"patterns":["«направляем / высылаем / отправляем» + «КП / предложение / расчёт»","«во вложении» + «КП»"]}'::jsonb, '[{"text":"«подготовим КП до пятницы»","code":null},{"text":"«во вложении наш прайс-лист»","code":null},{"text":"«направляем вам коммерческое предложение» от поставщика нам","code":"SUPPLIER_PRICE_CHANGE"}]'::jsonb, '«Добрый день! Во вложении коммерческое предложение на поставку вин для банкетного меню, предложение действительно до 30.11.»', '«Коллеги, КП подготовим и направим до конца недели» → отправки ещё нет.', 'Карточку не создавать; закрыть открытый запрос КП этого клиента и отметить дату отправки.', 0, 'state', NULL, false, 'state', NULL, true, false, false, 'both', 'active', 'S0', 'opportunity', ARRAY['SALES_OFFER_REQUESTED']::text[], NULL, NULL, NULL, 'Display profile: S0 (state code, closes and makes no card)
Closes: `SALES_OFFER_REQUESTED` (same client / topic)
Relations: starts the `SALES_OFFER_NO_RESPONSE` watchdog (REPLY_WINDOW, or the countdown from `facts.offerValidUntil`).
Deal effect: none — our own action never moves a stage (spec §9.2, author-only rule).', NULL, NULL),
  ('SALES_OFFER_NO_RESPONSE', 'base', 'A', 'offer', 'Нет ответа на отправленное КП', 'Мы отправили КП (SALES_OFFER_SENT), а клиент не ответил в отведённое окно. Создаётся процессом.', 'Молчание — не отказ. Явный отказ — SALES_OFFER_DECLINED. Нет исходного КП (SALES_OFFER_SENT) — нет сигнала. Ответ клиента любого содержания («получили, посмотрим») снимает сигнал.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, 'КП отправлено 03.11, согласованной даты ответа нет; на 10.11 от клиента нет писем и сообщений по теме.', '', 'Укажи, что и когда отправлено; шаги — коротко напомнить контакту, уточнить сроки решения, не давить скидкой первым шагом.', 7, 'fixed', 'risk', false, 'watchdog', 'medium', true, false, false, 'process', 'onHold', NULL, 'opportunity', '{}'::text[], NULL, NULL, '{"ru":"RU (Q24-11): есть исходное событие SALES_OFFER_SENT; истёк срок ответа — согласованная дата, а если её нет, 7 календарных дней (noResponseDefaultDays); если известна дата действия КП (facts.offerValidUntil), вместо окна действует отсчёт до неё (OFFER_COUNTDOWN_STEPS); проверены все подключённые каналы (почта, мессенджеры) клиента; нет ответа клиента по этой теме. Недостаточно данных — сигнала нет. EN: an originating SALES_OFFER_SENT exists; the reply deadline passed (agreed date, else 7 calendar days; a known offerValidUntil replaces the window with the countdown); all connected channels checked; no qualifying client reply on the topic. Insufficient data → no signal."}'::jsonb, 'Closed by: any qualifying client reply on the topic (watchdog clears)
Relations: `SALES_OFFER_DECLINED` leads over this code (the explicit refusal closes the loop).
Deal effect: per org rule. Usual: none (context for the deal state; silence is never `lost`).', NULL, NULL),
  ('SALES_OFFER_REQUESTED', 'base', 'A', 'offer', 'Запрошено коммерческое предложение', 'Клиент просит индивидуальное коммерческое предложение, смету или расчёт под конкретную задачу, проект, объём или мероприятие.', 'Просьба прислать стандартный прайс или условия без расчёта под задачу — SALES_PRICE_REQUEST. Каталог или портфель — SALES_CATALOG_REQUESTED. Тендер с процедурой и сроком подачи — SALES_TENDER_INVITATION. Концепция, макет, презентация — SALES_MATERIAL_REQUESTED. В дистрибуции: заказ с позициями и количеством — ORDER_REQUESTED; образцы — SAMPLES_REQUESTED; ввод в карту — LISTING_OPPORTUNITY (можно вместе с этим кодом). Наше собственное предложение без запроса — не сигнал.', ARRAY['пришлите КП', 'коммерческое предложение', 'просчитайте', 'смета', 'сколько будет стоить проект', 'предложите подборку', 'подготовьте предложение', 'нужен расчёт']::text[], '{"business":["просим направить коммерческое предложение на поставку","прошу подготовить КП с учётом объёма","направьте, пожалуйста, ваше предложение по","просим рассчитать стоимость","ждём от вас предложение до","прошу предоставить смету","рассматриваем поставщиков, просим ваше предложение"],"chat":["скиньте КП","посчитайте, сколько выйдет","можете прислать предложение на банкет на 80 человек?","сделайте расчёт под нас","«подберите вина под меню и цены» (дистрибуция)","что предложите под новое меню?"],"terms":["КП","ТКП","смета","расчёт","«RFP» (без процедуры отбора)","предложение под ключ"],"patterns":["«просим / прошу + направить / подготовить / прислать» + «КП / предложение / расчёт»","«сколько будет стоить» + объём или проект","«предложите подборку» + повод (дистрибуция: винная карта, мероприятие, сеть)"]}'::jsonb, '[{"text":"«пришлите актуальный прайс»","code":"SALES_PRICE_REQUEST"},{"text":"«какой у вас портфель по Италии?»","code":"SALES_CATALOG_REQUESTED"},{"text":"«отгрузите 6 кор. Риохи»","code":"ORDER_REQUESTED"},{"text":"«объявлен запрос котировок, срок подачи 20.11»","code":"SALES_TENDER_INVITATION"}]'::jsonb, '«Открываем второй ресторан в декабре, просим направить коммерческое предложение на винную карту — около 40 позиций, бюджет на бутылку до 3 500 руб.»', '«Пришлите, пожалуйста, актуальный прайс-лист» → это SALES_PRICE_REQUEST: стандартный ответ, без расчёта под задачу.', 'Укажи задачу, объём, бюджет и срок клиента; шаги — уточнить недостающее, подготовить КП к сроку, отправить ответственному контакту.', 7, 'fixed', 'chance', false, 'event', 'complex', true, true, true, 'both', 'active', NULL, 'opportunity', '{}'::text[], NULL, NULL, NULL, 'Closed by: `SALES_OFFER_SENT`
Date gate: — (the requested deadline goes to `facts.deadlines`, owner = us)
Relations: both with `SALES_NEW_DEMAND` (the opportunity and the task). Agency: a more precise `PITCH_*` code leads.
Deal effect: per org rule. Usual: stage move to «Запрошено предложение» (agency stage 2). IN4COM: **deal entry for new clients only** (wine card, event, chain); for an existing client — context or the matching distribution code.', NULL, NULL),
  ('SALES_BOOKING_CANCELLED', 'base', 'A', 'order', 'Клиент отменил размещённый заказ', 'Клиент отзывает уже размещённый (подтверждённый) заказ полностью или существенную его часть.', 'Перенос сроков — не отмена (в дистрибуции ORDER_CHANGE_REQUESTED). Отказ от КП до заказа — SALES_OFFER_DECLINED. Расторжение договора целиком — CONTRACT_TERMINATED. В дистрибуции отмена товарного заказа — ORDER_CANCELLED.', ARRAY['отменяем заказ', 'просим аннулировать заявку', 'заказ больше не актуален', 'отзываем заявку', 'не запускайте', 'снимаем заказ', 'отказываемся от заказа', 'заказ отменён']::text[], '{"business":["просим аннулировать заказ № от","в связи с изменением планов заказ отменяем","отзываем ранее направленную заявку","прошу считать заказ недействительным","мероприятие отменено, заказ просим снять"],"chat":["отбой по заказу","заказ отменяем, сорри","не надо, мы передумали","стопните заказ"],"terms":["аннулирование","отзыв заявки","отмена PO"],"patterns":["«отменяем / аннулируем / отзываем» + «заказ / заявку»"]}'::jsonb, '[{"text":"«перенесите поставку на следующую неделю»","code":"ORDER_CHANGE_REQUESTED"},{"text":"«ваше предложение нам не подходит»","code":"SALES_OFFER_DECLINED"},{"text":"«расторгаем договор»","code":"CONTRACT_TERMINATED"}]'::jsonb, '«Корпоратив перенесли на неопределённый срок, поэтому заказ № 318 от 05.11 просим аннулировать.»', '«Поставку по заказу 318 сдвиньте, пожалуйста, на 20-е» → это перенос, не отмена.', 'Укажи заказ, сумму и названную причину; шаги — выяснить причину, предложить перенос или замену, проверить расходы, уже понесённые по заказу.', 7, 'fixed', 'risk', false, 'event', 'medium', true, false, true, 'both', 'active', NULL, 'opportunity', '{}'::text[], NULL, NULL, NULL, 'Relations: leads over `SALES_BUDGET_CUT` (the concrete loss counts); leads over `ACCOUNT_REVENUE_DECLINE_YOY` (block K — the decline is context in the cancellation card).
Deal effect: per org rule. Usual: outcome `cancelled` for the linked deal only when the whole deal is cancelled; otherwise context. IN4COM: off.', NULL, NULL),
  ('SALES_RENEGOTIATION', 'base', 'A', 'contract', 'Клиент хочет пересмотреть согласованные условия', 'Клиент хочет заново открыть уже согласованные условия: цену, скидку, бонус, срок оплаты, объём обязательств, условия поставки.', 'Только недовольство ценой без просьбы изменить условия — COMPLAINT_PRICE (бывают вместе). Первый запрос цены — SALES_PRICE_REQUEST. В дистрибуции просьба об отсрочке, лимите или работе без предоплаты — PAYMENT_TERMS_REQUEST, не этот код. Торг по ещё не согласованному КП — SALES_OFFER_REQUESTED / агентский PITCH_FINAL_TERMS_DISCUSSION.', ARRAY['пересмотреть условия', 'пересмотреть скидку', 'поднять скидку', 'изменить условия', 'снизить цену', 'новые условия с 1 января', 'перезаключить на других условиях', 'изменить срок оплаты']::text[], '{"business":["просим пересмотреть условия договора","предлагаем обсудить изменение коммерческих условий","рассчитываем на увеличение скидки при сохранении объёмов","просим зафиксировать цены на 2027 год","готовы продлить при условии снижения цены","просим изменить порядок оплаты"],"chat":["давайте пересоберём условия","можно скидку побольше?","нам надо дешевле, иначе не потянем","давайте пересмотрим бонус","поднимите скидку до 15"],"terms":["скидка","ретро-бонус","бонус за объём","«отсрочка платежа» (без пакета дистрибуции)","фиксация цен","ДС об изменении условий"],"patterns":["«пересмотреть / изменить / обсудить» + «условия / скидку / цены»","«при условии» + «снижения / увеличения»"]}'::jsonb, '[{"text":"«у вас дорого» без просьбы","code":"COMPLAINT_PRICE"},{"text":"«дайте отсрочку 60 дней»","code":"PAYMENT_TERMS_REQUEST"},{"text":"«пришлите прайс»","code":"SALES_PRICE_REQUEST"}]'::jsonb, '«С января просим пересмотреть скидку: при текущих объёмах рассчитываем на 12% вместо 8%, иначе будем смотреть альтернативы.»', '«Цены у вас выросли, неприятно» → недовольство без просьбы изменить условия (COMPLAINT_PRICE).', 'Укажи, какие условия клиент хочет изменить и на что; шаги — оценить маржу, подготовить позицию для переговоров, согласовать встречу.', 7, 'fixed', 'risk', false, 'event', 'medium', true, false, true, 'both', 'active', NULL, 'opportunity', '{}'::text[], NULL, NULL, NULL, 'Relations: — in v204. Often together with `COMPLAINT_PRICE` (complaint + request).
Deal effect: per org rule. IN4COM: risk trigger «Конкурент предлагает дешевле» (not at the first-contact stage) and a postponement event for «Решение откладывается» (2nd distinct postponement, Q24-3).', NULL, NULL),
  ('SALES_NEW_DEMAND', 'base', 'A', 'offer', 'Дополнительная потребность действующего клиента', 'Действующий клиент просит то, чего раньше у нас не покупал: другую услугу, другую категорию товара или существенно больший объём того же. Нужна история заказов клиента.', 'Обычный повторный заказ — не этот код (в дистрибуции ORDER_REQUESTED). Изменение задач внутри уже оплаченного объёма — агентский DELIVERY_CHANGE_REQUESTED. Новый клиент без истории — не этот код (SALES_OFFER_REQUESTED, PROSPECT_NEED_EXPRESSED). Общие слова о планах без запроса — агентский ACCOUNT_PRIORITIES_CHANGED или нет сигнала. В дистрибуции ввод в карту — LISTING_OPPORTUNITY, новая точка — NEW_VENUE_OPENING.', ARRAY['хотим добавить', 'а вы можете ещё и', 'нам также нужно', 'расширить сотрудничество', 'рассматриваем у вас ещё', 'новое направление', 'увеличить объём в два раза', 'интересует также']::text[], '{"business":["помимо текущих поставок нас интересует","рассматриваем возможность расширить сотрудничество","просим рассмотреть дополнительно поставку","планируем увеличить объём закупок по","хотели бы подключить ещё одну категорию","есть потребность в"],"chat":["«а крепкое вы тоже возите?» (дистрибуция)","«можете ещё и игристое закрыть?» (дистрибуция)","хотим у вас брать ещё и","нам бы ещё","расширяемся, давайте больше"],"terms":["допродажа","кросс-продажа","новая категория","доп. объём"],"patterns":["«помимо / кроме» + текущего","«также / ещё и» + новая категория или услуга","«увеличить объём» + цифра"]}'::jsonb, '[{"text":"«повторите прошлый заказ»","code":"ORDER_REQUESTED"},{"text":"«добавьте в заказ 2 кор.»","code":"ORDER_CHANGE_REQUESTED"},{"text":"«рассматриваем ваши вина в новую карту»","code":"LISTING_OPPORTUNITY"}]'::jsonb, '«Сейчас берём у вас только вино, но с весны хотим закрыть у вас и крепкий алкоголь для бара — подготовьте, пожалуйста, предложение.»', '«Пришлите, как обычно, 10 коробок Пино Гриджо» → обычный повторный заказ.', 'Укажи, что нового хочет клиент и в каком объёме; шаги — уточнить потребность и сроки, подготовить предложение.', 7, 'fixed', 'chance', false, 'event', 'medium', true, false, true, 'both', 'active', NULL, 'opportunity', '{}'::text[], NULL, NULL, NULL, 'Relations: both with `SALES_OFFER_REQUESTED` (the opportunity and the task).
Deal effect: per org rule. Usual: deal entry (incremental opportunity, agency stage 1). IN4COM: under review — listings and new venues have own codes (`LISTING_OPPORTUNITY`, `NEW_VENUE_OPENING`).', NULL, NULL),
  ('SALES_BUDGET_INCREASE', 'base', 'A', 'account', 'Клиент увеличивает бюджет на работу с нами', 'Клиент сообщает, что увеличивает бюджет или плановый объём закупок у нас на период или направление.', 'Один крупный заказ — не этот код. Запрос новой категории — SALES_NEW_DEMAND. Сумма конкретной задачи — SALES_BUDGET_MENTIONED. Рост бюджета клиента вообще (новость) — блок H.', ARRAY['увеличиваем бюджет', 'бюджет на следующий год больше', 'планируем увеличить закупки', 'добавили денег', 'расширили лимит', 'объём вырастет', 'план закупок увеличен', 'выделили дополнительный бюджет']::text[], '{"business":["бюджет на 2027 год утверждён с ростом на 20%","планируем увеличить объём закупок у вас","выделен дополнительный бюджет на направление","лимит по договору увеличен"],"chat":["бюджет дали больше","в следующем году будем брать больше","денег добавили, можем развернуться"],"terms":["лимит","план закупок","бюджет на год"],"patterns":["«увеличиваем / расширяем» + «бюджет / лимит / объём»","«больше на» + %"]}'::jsonb, '[{"text":"«в этот раз нужно в два раза больше»","code":"ORDER_REQUESTED"},{"text":"«нужен бюджет 500 тыс. на мероприятие»","code":"SALES_BUDGET_MENTIONED"}]'::jsonb, '«Хорошие новости: бюджет на закупку на следующий год согласовали на 30% больше, хотим основную часть разместить у вас.»', '«На корпоратив в этот раз возьмём побольше, человек будет 120» → один заказ, не бюджет.', 'Укажи период и размер увеличения; шаги — обсудить, на что клиент хочет направить рост, подготовить предложение.', 7, 'fixed', 'chance', false, 'event', 'medium', true, false, true, 'both', 'active', NULL, 'opportunity', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule. Usual: in-stage context (budget), no stage move; the amount never enters the forecast automatically. IN4COM: off.', NULL, NULL),
  ('CONTRACT_RENEWAL_INTENT', 'base', 'A', 'contract', 'Клиент сам поднял вопрос продления договора', 'Клиент по своей инициативе поднимает продление действующего договора на следующий период: предлагает продлить, просит ДС о пролонгации, спрашивает об условиях на следующий год.', 'Наше напоминание о продлении — не сигнал клиента. Просто дата окончания без инициативы клиента — CONTRACT_FRAME_EXPIRY. Общее «надеемся на продолжение сотрудничества» — не этот код (Q24-10). Продление при условии новых цен — этот код вместе с SALES_RENEGOTIATION. Явное решение продолжить работу до оформления — в агентском пакете CONTRACT_CONTINUATION_CONFIRMED. Отказ от продления — не этот код.', ARRAY['продлим договор на следующий год', 'пришлите ДС о пролонгации', 'хотим продлить договор', 'давайте продлим', 'условия на следующий год', 'готовы пролонгировать', 'переподпишем договор на 2027', 'продление на тех же условиях']::text[], '{"business":["предлагаем продлить действие договора на 2027 год","просим направить дополнительное соглашение о пролонгации","планируем продолжить сотрудничество на следующий период, просим условия","готовы пролонгировать договор на прежних условиях","рассматриваем продление договора поставки"],"chat":["давайте продлеваться","договор на следующий год делаем?","пришлите допник на продление","продлеваем, кидайте документы"],"terms":["ДС","допник","доп. соглашение","пролонгация","перезаключение"],"patterns":["«продлить / пролонгировать» + «договор / сотрудничество» + период","условия на следующий год"]}'::jsonb, '[{"text":"«надеемся на дальнейшее сотрудничество»","code":null},{"text":"«договор действует до 31.12»","code":"CONTRACT_FRAME_EXPIRY"},{"text":"«продлевать не будем»","code":"CONTRACT_RENEWAL_DECLINED"}]'::jsonb, '«Договор у нас до конца года, мы планируем продлить его на 2027 год — пришлите, пожалуйста, дополнительное соглашение и актуальные условия.»', '«Спасибо за год работы, надеемся и дальше сотрудничать» → вежливость, нет конкретного продления.', 'Укажи договор, период и условия, о которых говорит клиент; шаги — подготовить ДС, проверить условия и цены, согласовать подписание.', 7, 'fixed', 'chance', false, 'event', 'medium', false, true, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Closes: — (clears the IN4COM risk «Договор заканчивается без продления»)
Relevance window: until the current contract end date, if known; else default
Relations: leads over `CONTRACT_FRAME_EXPIRY` (the opportunity beats the warning).
Deal effect: per org rule. IN4COM: **deal entry (renewal)**. Agency (Q24-10): stage 4 only when the contract / service is identifiable, the next period or scope is defined and the client explicitly confirms the choice; otherwise context.', NULL, NULL),
  ('SALES_PRICE_REQUEST', 'base', 'A', 'offer', 'Запрошены цены, прайс-лист или стандартные условия', 'Клиент просит цены, прайс-лист, стандартные условия поставки или скидки. Это стандартный ответ, а не индивидуальное предложение.', 'Расчёт под конкретную задачу — SALES_OFFER_REQUESTED. Поставщик или производитель присылает НАМ свой прайс или дилерские цены — SUPPLIER_PRICE_CHANGE. Жалоба «дорого» — COMPLAINT_PRICE. В дистрибуции вопрос о наличии или остатках без цены — STOCK_AVAILABILITY_REQUEST; позиции с количеством — ORDER_REQUESTED.', ARRAY['прайс', 'прайс-лист', 'цены', 'условия', 'скидка от объёма', 'какая цена', 'актуальные цены', 'спеццена']::text[], '{"business":["просим направить актуальный прайс-лист","прошу сообщить стоимость и условия поставки","укажите, пожалуйста, цену за единицу с НДС","какие у вас условия по скидкам от объёма","«просим предоставить условия для HoReCa» (дистрибуция)","интересуют оптовые цены"],"chat":["скиньте прайс плиз","«почём Шабли?» (дистрибуция)","сколько стоит?","какая цена за коробку?","есть спеццена на объём?","«киньте цены на игристое» (дистрибуция)"],"terms":["прайс","ПЛ","опт","РРЦ","с НДС / без НДС","спеццена","скидка от объёма","бонус за объём","ДДП","EXW"],"patterns":["«пришлите / направьте» + «прайс / цены»","«сколько стоит / почём / какая цена» + товар","«какие условия по» + «скидкам / оплате / доставке»"]}'::jsonb, '[{"text":"«посчитайте нам банкет на 80 человек»","code":"SALES_OFFER_REQUESTED"},{"text":"«во вложении наш новый прайс с 01.12» от производителя","code":"SUPPLIER_PRICE_CHANGE"},{"text":"«у вас дорого»","code":"COMPLAINT_PRICE"},{"text":"«есть ли в наличии Бароло?»","code":"STOCK_AVAILABILITY_REQUEST"}]'::jsonb, '«Добрый день! Пришлите, пожалуйста, актуальный прайс-лист для HoReCa и условия по скидкам от объёма.»', '«Направляем вам наш обновлённый прайс-лист, действует с 1 декабря» (письмо поставщика нам) → это SUPPLIER_PRICE_CHANGE.', 'Укажи, какие цены и условия запрошены; шаги — отправить актуальный прайс или условия, уточнить объём и задачу клиента.', 6, 'fixed', 'chance', false, 'event', 'quick', true, true, true, 'both', 'active', NULL, 'opportunity', '{}'::text[], NULL, NULL, NULL, 'Closed by: — (no "price list sent" state code; see Open points)
Deal effect: per org rule. Usual: none (a standard reply, not an individual offer). IN4COM: none.', NULL, NULL),
  ('SALES_MATERIAL_REQUESTED', 'base', 'A', 'offer', 'Запрошены индивидуальные материалы (концепция, макет, презентация)', 'Клиент просит материалы, которые мы делаем индивидуально: концепцию, макет, презентацию под задачу клиента, план, дизайн, проект.', 'Готовый каталог или общая презентация компании — SALES_CATALOG_REQUESTED. Цена или расчёт — SALES_PRICE_REQUEST / SALES_OFFER_REQUESTED. В дистрибуции образцы товара — SAMPLES_REQUESTED; дегустация — TASTING_REQUESTED; POS-материалы и промо — PROMO_SUPPORT_REQUESTED. Кейсы и анкеты для отбора — агентский PITCH_CREDENTIALS_REQUESTED.', ARRAY['подготовьте концепцию', 'нужен макет', 'сделайте презентацию под нас', 'пришлите визуализацию', 'нужен проект', 'разработайте предложение по оформлению', 'покажите, как это будет выглядеть', 'нужна концепция мероприятия']::text[], '{"business":["просим подготовить концепцию проекта","направьте, пожалуйста, макет для согласования","прошу подготовить презентацию решения для руководства","просим разработать дизайн-проект","нужна визуализация к совещанию"],"chat":["накидайте концепт","сделайте макетик","покажите пару вариантов","нужна презуха под нас"],"terms":["концепция","концепт","макет","визуал","мудборд","презентация","ТЗ","бриф"],"patterns":["«подготовьте / разработайте / сделайте» + «концепцию / макет / презентацию» + «под нас / под задачу»"]}'::jsonb, '[{"text":"«пришлите презентацию компании»","code":"SALES_CATALOG_REQUESTED"},{"text":"«пришлите образцы»","code":"SAMPLES_REQUESTED"},{"text":"«нужны воблеры и POS»","code":"PROMO_SUPPORT_REQUESTED"}]'::jsonb, '«Подготовьте, пожалуйста, концепцию оформления стенда под нашу выставку и пару вариантов макета к среде.»', '«Пришлите, пожалуйста, общую презентацию вашей компании» → готовый материал, SALES_CATALOG_REQUESTED.', 'Укажи, какой материал и к какому сроку нужен; шаги — уточнить бриф, согласовать объём работы и срок, назначить исполнителя.', 6, 'fixed', 'chance', false, 'event', 'complex', true, true, true, 'both', 'active', NULL, 'opportunity', '{}'::text[], NULL, NULL, NULL, 'Relations: — in v204. Agency: `PITCH_SOLUTION_REQUESTED` leads; one card (Maslov §5.5). Successor area of retired `SALES_CONCEPT`, `SALES_MOCKUP`, `SALES_PRESENTATION`.
Deal effect: per org rule. Agency: stage move to stage 2 only when no more precise `PITCH_*` code applies. IN4COM: off.', NULL, NULL),
  ('SALES_ORDER_CONFIRMATION_REQUESTED', 'base', 'A', 'order', 'Клиент просит подтвердить заказ', 'Клиент просит нас письменно подтвердить его заказ: подтверждение приёма заказа, сроков, цены или наличия, подписанную нами заявку, счёт как подтверждение.', 'Клиент сам подтверждает заказ — SALES_BOOKING_RECEIVED (или ORDER_REQUESTED в дистрибуции). Вопрос о статусе доставки — не этот код (в дистрибуции DELIVERY_SCHEDULE_REQUEST). Запрос документов по отгрузке (УПД, ТТН) — DOCUMENTS_REQUESTED (дистрибуция). В дистрибуции этот код пересекается с ORDER_REQUESTED → ORDER_CONFIRMED; см. Open points.', ARRAY['подтвердите заказ', 'подтвердите получение заявки', 'пришлите подтверждение', 'подтвердите сроки и цену', 'заказ принят?', 'выставите счёт на заказ', 'подтвердите наличие по заказу', 'ждём подтверждения']::text[], '{"business":["просим подтвердить принятие заказа в работу","прошу подтвердить сроки поставки по заявке","направьте, пожалуйста, подтверждение заказа","подтвердите, пожалуйста, цену и количество","ждём счёт для подтверждения заказа"],"chat":["заявку получили?","подтвердите, что всё ок по заказу","скиньте счёт, чтобы мы понимали, что заказ принят","маякните, что взяли в работу"],"terms":["подтверждение заказа","order confirmation","счёт на предоплату","акцепт заявки"],"patterns":["«подтвердите / прошу подтвердить» + «заказ / заявку / сроки / цену»"]}'::jsonb, '[{"text":"«подтверждаем заказ» (клиент)","code":"SALES_BOOKING_RECEIVED"},{"text":"«когда привезёте?»","code":"DELIVERY_SCHEDULE_REQUEST"},{"text":"«пришлите УПД»","code":"DOCUMENTS_REQUESTED"}]'::jsonb, '«Направили вчера заявку на 18 позиций, подтвердите, пожалуйста, что всё есть в наличии и срок поставки до 28.11.»', '«Заказ подтверждаем, запускайте» → это подтверждение клиента, SALES_BOOKING_RECEIVED.', 'Укажи заказ и что именно нужно подтвердить; шаги — проверить наличие, сроки и цену, отправить подтверждение.', 6, 'fixed', 'chance', false, 'event', 'quick', true, true, true, 'both', 'active', NULL, 'opportunity', '{}'::text[], NULL, NULL, NULL, 'Closed by: `SALES_ORDER_CONFIRMATION_SENT`
Relations: the `SALES_ORDER_CONFIRMATION_OPEN` watchdog starts when we promise the confirmation.
Deal effect: per org rule. Usual: none. IN4COM: none (orders are outside deals in step one, Q26).', NULL, NULL),
  ('SALES_OFFER_DECLINED', 'base', 'A', 'offer', 'Клиент отклонил предложение', 'Клиент прямо отказывается от нашего предложения: выбрал другого поставщика, решил не покупать или говорит, что предложение не подходит.', 'Молчание — не отказ (SALES_OFFER_NO_RESPONSE). Просьба изменить предложение («дороговато, пересчитайте») — не отказ (COMPLAINT_PRICE / SALES_RENEGOTIATION). Перенос решения — не отказ. Отмена уже размещённого заказа — SALES_BOOKING_CANCELLED.', ARRAY['не подходит', 'выбрали другого поставщика', 'вынуждены отказаться', 'решили не продолжать', 'приняли решение в пользу другой компании', 'ваше предложение не прошло', 'не будем заказывать', 'отказываемся от предложения']::text[], '{"business":["благодарим за предложение, однако приняли решение в пользу другого поставщика","к сожалению, ваше предложение нам не подходит","по итогам рассмотрения вынуждены отказаться","в текущем году закупку проводить не будем","ваше предложение не прошло согласование"],"chat":["не, не берём","спасибо, но мы пас","взяли у других","руководство не одобрило, увы","не зашло"],"terms":["отказ","не прошли по цене","не согласовано"],"patterns":["вынуждены отказаться от","«выбрали / остановились на» + другой поставщик","«не подходит» + по цене / по срокам / по ассортименту"]}'::jsonb, '[{"text":"«дорого, можете пересчитать?»","code":"COMPLAINT_PRICE"},{"text":"«вернёмся к вопросу после нового года»","code":null},{"text":"тишина после КП","code":"SALES_OFFER_NO_RESPONSE"}]'::jsonb, '«Спасибо за предложение, но по итогам сравнения мы выбрали другого поставщика — у них условия по отсрочке лучше.»', '«Пока не готовы принять решение, вернёмся в январе» → это перенос, не отказ.', 'Укажи, от чего отказался клиент и названную причину; шаги — поблагодарить, уточнить причину и условия победителя, договориться о следующем контакте.', 6, 'fixed', 'risk', false, 'event', 'medium', false, false, true, 'both', 'active', NULL, 'opportunity', ARRAY['SALES_OFFER_NO_RESPONSE']::text[], NULL, NULL, NULL, 'Closes: — (ends the `SALES_OFFER_NO_RESPONSE` wait)
Relations: leads over `SALES_OFFER_NO_RESPONSE` (the explicit refusal closes the loop). Agency: one outcome card with `PITCH_EXCLUDED` (Maslov §5.5).
Deal effect: per org rule. Usual: outcome `lost` only when the refusal covers the whole deal; a refusal of one offer version may keep the deal open (Maslov §3.2).', NULL, NULL),
  ('SALES_ORDER_CONFIRMATION_OPEN', 'base', 'A', 'order', 'Обещанное подтверждение заказа не отправлено', 'Клиент запросил подтверждение заказа, мы его обещали, но оно не ушло в срок. Создаётся процессом.', 'Это наша задержка, а не жалоба клиента: если клиент пишет «сколько ждать подтверждения?», это COMPLAINT_TIMING. Без исходного запроса или обещания — нет сигнала.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, 'Клиент 10.11 просил подтвердить заказ, менеджер ответил «подтвердим завтра»; 12.11 подтверждения в переписке нет.', '', 'Укажи заказ и дату обещания; шаги — отправить подтверждение сегодня или сообщить клиенту новый срок.', 5, 'fixed', 'risk', false, 'watchdog', 'medium', true, false, false, 'process', 'onHold', NULL, 'opportunity', '{}'::text[], NULL, NULL, '{"ru":"RU: есть открытый SALES_ORDER_CONFIRMATION_REQUESTED (или наше обещание с датой в facts.deadlines, owner = us); срок прошёл (согласованная дата, иначе окно ответа организации); нет SALES_ORDER_CONFIRMATION_SENT по этой теме. EN: an open SALES_ORDER_CONFIRMATION_REQUESTED (or our dated promise, owner = us); the deadline passed (agreed date, else the org reply window); no SALES_ORDER_CONFIRMATION_SENT on the topic."}'::jsonb, 'Closed by: `SALES_ORDER_CONFIRMATION_SENT`
Relations: follows `SALES_ORDER_CONFIRMATION_REQUESTED`.
Deal effect: per org rule. Usual: none.', NULL, NULL),
  ('SALES_ORDER_CONFIRMATION_SENT', 'base', 'A', 'order', 'Мы отправили подтверждение заказа', 'Служебное событие: мы отправили клиенту подтверждение заказа (письмо, подписанную заявку, счёт как подтверждение). Закрывает запрос подтверждения и ожидание.', 'Подтверждение заказа от поставщика НАМ — не этот код. Клиент подтверждает свой заказ — SALES_BOOKING_RECEIVED. В дистрибуции подтверждение товарного заказа — ORDER_CONFIRMED (см. Open points).', ARRAY['подтверждаем принятие заказа', 'заказ принят в работу', 'подтверждаем сроки поставки', 'во вложении подтверждение заказа', 'счёт на оплату по заказу во вложении', 'заявка принята', 'отгрузка запланирована на']::text[], '{"business":["подтверждаем получение и принятие заказа № в работу","подтверждаем наличие и срок поставки","направляем подтверждение заказа и счёт","заявка принята, отгрузка запланирована на 25.11"],"chat":["заказ взяли, всё ок","подтверждаю, отгрузим в четверг","приняли, счёт скинул"],"terms":["подтверждение заказа","order confirmation","счёт","акцепт"],"patterns":["«подтверждаем» + «заказ / сроки / наличие» (в НАШЕМ письме)"]}'::jsonb, '[{"text":"«подтверждаем заказ, запускайте» (клиент)","code":"SALES_BOOKING_RECEIVED"},{"text":"«ваш заказ у производителя подтверждён» (поставщик нам)","code":null}]'::jsonb, '«Подтверждаем принятие заказа № 412 в работу, все позиции в наличии, отгрузка запланирована на 26.11, счёт во вложении.»', '«Подтвердим заказ после проверки склада» → обещание, подтверждения ещё нет.', 'Карточку не создавать; закрыть открытый запрос подтверждения по этому заказу.', 0, 'state', NULL, false, 'state', NULL, false, false, false, 'both', 'active', 'S0', 'opportunity', ARRAY['SALES_ORDER_CONFIRMATION_REQUESTED', 'SALES_ORDER_CONFIRMATION_OPEN']::text[], NULL, NULL, NULL, 'Display profile: S0 (state code, closes and makes no card)
Closes: `SALES_ORDER_CONFIRMATION_REQUESTED`, `SALES_ORDER_CONFIRMATION_OPEN` (same client / topic)
Deal effect: none — our own action.', NULL, NULL),
  ('SALES_MATERIAL_NO_RESPONSE', 'base', 'A', 'offer', 'Нет реакции на индивидуальные материалы', 'Мы отправили клиенту запрошенные индивидуальные материалы (концепцию, макет, презентацию), а реакции нет в отведённое окно. Создаётся процессом.', 'Молчание — не отказ. Без исходного запроса (SALES_MATERIAL_REQUESTED) и нашей отправки — нет сигнала. Любой ответ клиента по теме снимает сигнал.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, 'Макеты отправлены 02.11 по запросу клиента; до 09.11 ответа ни в почте, ни в мессенджере нет.', '', 'Укажи, какой материал и когда отправлен; шаги — уточнить, посмотрел ли клиент, предложить короткий созвон для обсуждения.', 5, 'fixed', 'risk', false, 'watchdog', 'medium', true, false, false, 'process', 'onHold', NULL, 'opportunity', '{}'::text[], NULL, NULL, '{"ru":"RU (Q24-11): есть исходный запрос SALES_MATERIAL_REQUESTED и наша отправка материала по этой теме; истёк срок ответа (согласованная дата, иначе 7 календарных дней, noResponseDefaultDays); проверены подключённые каналы; нет ответа клиента. EN: an originating SALES_MATERIAL_REQUESTED and our sending exist; the reply deadline passed (agreed date, else 7 calendar days); channels checked; no client reply."}'::jsonb, 'Closed by: any qualifying client reply on the topic (watchdog clears)
Deal effect: per org rule. Usual: none (silence is never `lost`).', NULL, NULL),
  ('SALES_PRICE_NO_RESPONSE', 'base', 'A', 'offer', 'Нет реакции на отправленные цены', 'Мы отправили клиенту запрошенный прайс-лист или условия, а реакции нет в отведённое окно. Создаётся процессом.', 'Молчание — не отказ. Без исходного SALES_PRICE_REQUEST и нашей отправки прайса — нет сигнала. Рассылка прайса всем клиентам по нашей инициативе — не основание.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, 'Прайс для HoReCa отправлен 05.11 по запросу ресторана; к 12.11 клиент не ответил и не сделал заказ.', '', 'Укажи, что и когда отправлено; шаги — уточнить, какие позиции интересны, предложить подборку или образцы.', 5, 'fixed', 'risk', false, 'watchdog', 'medium', true, false, false, 'process', 'onHold', NULL, 'opportunity', '{}'::text[], NULL, NULL, '{"ru":"RU (Q24-11): есть исходный SALES_PRICE_REQUEST и наша отправка прайса или условий по этой теме; истёк срок ответа (согласованная дата, иначе 7 календарных дней); проверены подключённые каналы; нет ответа клиента. Для фиксации отправки прайса сейчас нет state-кода — процессу нужен факт отправки (см. Open points). EN: an originating SALES_PRICE_REQUEST and our price-list sending exist; reply deadline passed (agreed date, else 7 days); channels checked; no client reply. A \"price list sent\" fact is needed (see Open points)."}'::jsonb, 'Closed by: any qualifying client reply on the topic (watchdog clears)
Deal effect: per org rule. Usual: none.', NULL, NULL),
  ('SALES_CATALOG_REQUESTED', 'base', 'A', 'offer', 'Запрошен каталог или обзор ассортимента / услуг', 'Клиент просит готовый каталог, портфель, обзор ассортимента или услуг, общую презентацию компании. Материал отправляется готовым, не создаётся под клиента.', 'Цены — SALES_PRICE_REQUEST (часто вместе: «каталог с ценами» → оба кода допустимы, ведёт цена по весу). Материал под задачу клиента — SALES_MATERIAL_REQUESTED. Подборка под конкретный повод с расчётом — SALES_OFFER_REQUESTED. Кейсы для отбора — агентский PITCH_CREDENTIALS_REQUESTED.', ARRAY['каталог', 'портфель', 'что есть из Бургундии', 'пришлите ассортимент', 'презентация компании', 'обзор услуг', 'какие бренды у вас есть', 'полный список позиций']::text[], '{"business":["просим направить каталог продукции","прошу прислать презентацию компании и перечень услуг","направьте, пожалуйста, ваш портфель","интересует полный ассортимент по категории","просим ознакомить с линейкой"],"chat":["скиньте каталог","«что у вас есть по Италии?» (дистрибуция)","«есть что-нибудь из Бургундии?» (дистрибуция)","«какие хозяйства возите?» (дистрибуция)","покажите, что вообще делаете"],"terms":["каталог","портфель","портфолио","ассортиментная матрица","линейка","SKU-лист"],"patterns":["«пришлите / направьте» + «каталог / портфель / ассортимент / презентацию компании»","«что есть из / по» + регион или категория (дистрибуция)"]}'::jsonb, '[{"text":"«прайс с ценами для HoReCa»","code":"SALES_PRICE_REQUEST"},{"text":"«подберите 10 вин под новое меню»","code":"SALES_OFFER_REQUESTED"},{"text":"«есть ли в наличии 12 бут. Шабли Премьер Крю?»","code":"STOCK_AVAILABILITY_REQUEST"}]'::jsonb, '«Пришлите, пожалуйста, ваш актуальный портфель — что есть из Бургундии и Пьемонта, хотим обновить винную карту.»', '«Пришлите прайс на игристое» → это SALES_PRICE_REQUEST.', 'Укажи, какой каталог или раздел запрошен; шаги — отправить актуальный каталог, уточнить интерес и предложить следующий шаг.', 5, 'fixed', 'chance', false, 'event', 'quick', false, true, true, 'both', 'active', NULL, 'opportunity', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule. Usual: none. IN4COM: none.', NULL, NULL),
  ('SALES_BUDGET_MENTIONED', 'base', 'A', 'offer', 'Клиент назвал бюджет конкретной задачи', 'Клиент называет сумму или бюджет конкретной задачи или проекта, на которую готов ориентироваться.', 'Сумма счёта, оплаты или долга — не этот код (INVOICE_*). Цифра без намерения (оборот компании, цена из новостей) — нет сигнала. Изменение бюджета на работу с нами в целом — SALES_BUDGET_CUT / SALES_BUDGET_INCREASE. Сумма в нашем КП — SALES_OFFER_SENT.', ARRAY['бюджет на проект', 'рассчитываем уложиться в', 'готовы потратить до', 'бюджет до', 'в пределах суммы', 'бюджет на мероприятие', 'лимит на закупку', 'ориентируемся на сумму']::text[], '{"business":["бюджет проекта составляет около 2 млн руб.","рассчитываем уложиться в 500 тыс. руб. с НДС","на эту задачу выделено до","ориентировочный бюджет мероприятия","максимальная сумма закупки"],"chat":["у нас на это 300к","бюджет около ляма","больше 200 не дадут","в 150 тыс. уложимся?"],"terms":["бюджет","лимит","т.р.","тыс.","млн","«к» (300к)","с НДС / без НДС"],"patterns":["«бюджет / лимит» + сумма + задача","«уложиться в» + сумма","«до» + сумма + «на» + задачу"]}'::jsonb, '[{"text":"«оплатили 240 000 руб.»","code":"INVOICE_PAID"},{"text":"«оборот сети — 3 млрд»","code":null},{"text":"«бюджет на следующий год урезали»","code":"SALES_BUDGET_CUT"}]'::jsonb, '«На новогодний корпоратив у нас бюджет на напитки около 350 тыс. руб., предложите что-то в эти рамки.»', '«Счёт на 350 тыс. руб. оплатим в пятницу» → это оплата, не бюджет задачи.', 'Укажи задачу и сумму; шаги — сверить бюджет с вариантами, предложить решение в рамках суммы.', 4, 'fixed', 'chance', false, 'event', 'medium', true, false, true, 'both', 'active', NULL, 'opportunity', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule. Usual: in-stage context (budget); never a stage move by the amount, never in the forecast automatically. IN4COM: off.', NULL, NULL),
  ('CONTRACT_DPA', 'base', 'B', 'contract', 'Соглашение (поручение) об обработке персональных данных', 'Запрошено, отправлено или подписано соглашение об обработке персональных данных: поручение на обработку ПДн по 152-ФЗ, соглашение о защите персональных данных, приложение о ПДн к договору.', 'Соглашение о конфиденциальности (коммерческая тайна) — CONTRACT_NDA. Анкеты по санкциям, проверке контрагента, ESG — CONTRACT_COMPLIANCE_DECLARATION. Согласие на рассылку или политика конфиденциальности сайта в подписи письма — нет сигнала. Основной договор поставки или услуг — не этот код.', ARRAY['поручение на обработку персональных данных', 'соглашение об обработке ПДн', '152-ФЗ', 'персональные данные', 'приложение о защите персональных данных', 'DPA', 'обработка ПДн по поручению', 'соглашение о защите данных']::text[], '{"business":["просим подписать поручение на обработку персональных данных","направляем соглашение об обработке ПДн к договору","необходимо приложение о защите персональных данных в соответствии с 152-ФЗ","во вложении подписанное соглашение о ПДн","просим подтвердить меры по защите ПДн"],"chat":["юристы просят допник по персданным","нужно подписать бумагу по ПДн","пришлите соглашение по персональным данным"],"terms":["ПДн","152-ФЗ","DPA","поручение оператора","РКН","локализация ПДн","ст. 6 152-ФЗ"],"patterns":["«поручение / соглашение / приложение» + «об обработке / о защите» + «персональных данных»"]}'::jsonb, '[{"text":"«подписали NDA»","code":"CONTRACT_NDA"},{"text":"«заполните анкету контрагента»","code":"CONTRACT_COMPLIANCE_DECLARATION"},{"text":"дисклеймер «письмо содержит персональные данные» в подписи","code":null}]'::jsonb, '«Для запуска рассылки по нашей базе гостей юристы просят подписать поручение на обработку персональных данных — проект во вложении.»', '«Настоящее сообщение и вложения конфиденциальны и могут содержать персональные данные» (подпись) → нет сигнала.', 'Укажи, какой документ по ПДн и в каком статусе; шаги — передать юристу, согласовать текст, подписать.', 4, 'fixed', 'fyi', false, 'event', 'medium', false, true, false, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule. Usual: none.', NULL, NULL)
ON CONFLICT DO NOTHING;
