INSERT INTO "signal_category" ("code", "pack_code", "block_code", "family", "label_ru", "definition_ru", "boundary_ru", "cues_prompt_ru", "synonyms_ru", "anti_cues_ru", "example_ru", "counter_example_ru", "card_note_ru", "weight", "score_rule", "class", "class_by_relation", "kind", "effort", "carries_amount", "asks_us", "inbound_only", "emitted_by", "stage", "display_profile", "recipient_role", "closes_codes", "date_gate", "relevance_days", "trigger_rule", "note_ru", "retired_at", "successor_code") VALUES
  ('CONTRACT_NDA', 'base', 'B', 'contract', 'Подписано соглашение о конфиденциальности (NDA)', 'Подписано соглашение о конфиденциальности (о неразглашении, о коммерческой тайне). Это подтверждение факта, а не задача.', 'Анкеты и заверения (санкции, экспортный контроль, ESG, проверка контрагента) — CONTRACT_COMPLIANCE_DECLARATION. Договор поставки, услуг или агентский договор, присланный на подпись, — не этот код. Соглашение о ПДн — CONTRACT_DPA. Стандартный дисклеймер о конфиденциальности в подписи — нет сигнала.', ARRAY['NDA подписано', 'соглашение о конфиденциальности подписано', 'соглашение о неразглашении', 'режим коммерческой тайны', 'подписанный NDA во вложении', 'договор о конфиденциальности', 'соглашение о неразглашении информации']::text[], '{"business":["направляем подписанное соглашение о конфиденциальности","соглашение о неразглашении подписано с нашей стороны","во вложении скан подписанного NDA","просим подписать соглашение о конфиденциальности до передачи документации"],"chat":["NDA подписали, кидаю скан","эндиэй подписан","подписали бумагу о неразглашении"],"terms":["NDA","«КТ» (коммерческая тайна)","98-ФЗ","соглашение о конфиденциальности"],"patterns":["«подписан(о) / подписали» + «NDA / соглашение о конфиденциальности / о неразглашении»"]}'::jsonb, '[{"text":"«заполните анкету по санкциям»","code":"CONTRACT_COMPLIANCE_DECLARATION"},{"text":"«направляем договор поставки на подпись»","code":null},{"text":"«информация в письме конфиденциальна»","code":null}]'::jsonb, '«Соглашение о конфиденциальности подписано с нашей стороны, скан во вложении — можем передавать вам техническое задание.»', '«Направляем на подпись договор поставки на 2027 год» → это не NDA.', 'Отметь, что NDA подписано и с какой датой; шаг — сохранить документ в карточке клиента.', 2, 'fixed', 'fyi', false, 'event', 'medium', false, true, false, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule. Usual: none — NDA is a separate fact, never a stage move (Maslov §3).', NULL, NULL),
  ('CONTRACT_COMPLIANCE_DECLARATION', 'base', 'B', 'contract', 'Запрошена анкета или заверение о соответствии (санкции, проверка контрагента, ESG)', 'Клиент, госзаказчик или тендер просит у нас анкету, заверение или декларацию о соответствии требованиям — либо мы отправляем её: санкционные заверения и конечное использование, проверка контрагента (должная осмотрительность), антикоррупционные заверения, кодекс поставщика, ESG / анкета устойчивого развития.', 'Соглашение о конфиденциальности — CONTRACT_NDA; о ПДн — CONTRACT_DPA. В организации с пакетом дистрибуции документы на товар (сертификат, декларация соответствия ЕАЭС, удостоверение качества, справки А/Б к ТТН) — DOCUMENTS_REQUESTED, не этот код. Пакет документов в составе тендерной заявки — часть SALES_TENDER_INVITATION, если отдельного запроса нет.', ARRAY['анкета контрагента', 'проверка контрагента', 'заверения об обстоятельствах', 'санкционная оговорка', 'заверение о конечном использовании', 'антикоррупционная оговорка', 'кодекс поставщика', 'ESG-анкета']::text[], '{"business":["для проверки контрагента просим заполнить анкету и предоставить пакет документов","просим подписать заверения об обстоятельствах (ст. 431.2 ГК)","требуется гарантийное письмо об отсутствии санкционных ограничений","просим подтвердить, что конечный получатель не находится под санкциями","просим ознакомиться и подписать кодекс поведения поставщика","служба безопасности запросила документы для согласования поставщика","просим заполнить анкету по устойчивому развитию"],"chat":["СБ просит анкету на вас","служба безопасности не пропускает без пакета документов","надо заполнить анкету поставщика, скинула форму","подпишите антикоррупционку"],"terms":["СБ","KYC","должная осмотрительность","ст. 431.2 ГК","антикоррупционная оговорка","санкционная оговорка","ESG","кодекс поставщика","выписка ЕГРЮЛ","карточка предприятия","ОКВЭД"],"patterns":["«просим заполнить / подписать» + «анкету / заверения / декларацию / кодекс»","«для проверки / согласования» + «контрагента / поставщика»"]}'::jsonb, '[{"text":"«пришлите сертификаты и декларации на поставленный товар»","code":"DOCUMENTS_REQUESTED"},{"text":"«подписали NDA»","code":"CONTRACT_NDA"},{"text":"«пришлите ваши реквизиты для счёта»","code":null}]'::jsonb, '«Служба безопасности просит заполнить анкету контрагента и подписать заверения об обстоятельствах — без этого не можем завести вас в систему поставщиков.»', '«Пришлите, пожалуйста, декларации соответствия на партию из последней поставки» → документы на товар (DOCUMENTS_REQUESTED в дистрибуции).', 'Укажи, какую анкету или заверение просят и к какому сроку; шаги — собрать документы, согласовать текст с юристом, отправить.', 4, 'fixed', 'fyi', false, 'event', 'quick', false, true, false, 'parser', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule. Usual: none.', NULL, NULL),
  ('DELIVERY_REPORT_REQUESTED', 'base', 'C', 'delivery', 'Клиент запросил отчёт', 'Клиент просит отчёт о выполненной работе, итоговый или промежуточный отчёт, отчёт по результатам, статистику, отчёт по продажам или промо.', 'Закрывающие бухгалтерские документы (акт, УПД, счёт-фактура) — не отчёт (в дистрибуции DOCUMENTS_REQUESTED). Акт сверки — RECONCILIATION_REQUESTED (дистрибуция) или нет сигнала. Протокол встречи от клиента — DELIVERY_PROTOCOL. Жалоба «отчёта до сих пор нет» — COMPLAINT_TIMING.', ARRAY['пришлите отчёт', 'нужен отчёт по итогам', 'отчёт за месяц', 'итоговый отчёт', 'предоставьте статистику', 'отчёт по продажам', 'отчёт о выполнении', 'промежуточный отчёт']::text[], '{"business":["просим предоставить отчёт о проделанной работе за октябрь","направьте, пожалуйста, итоговый отчёт по проекту","прошу подготовить отчёт по результатам акции","необходим отчёт для руководства до","просим отчёт по исполнению договора"],"chat":["скиньте отчётик за месяц","где посмотреть результаты?","нужна статистика по акции","«пришлите цифры по продажам нашей сети» (дистрибуция)"],"terms":["отчёт","отчётность","статистика","sell-out","sell-in","KPI","итоги"],"patterns":["«пришлите / подготовьте / предоставьте» + «отчёт / статистику / итоги» + период или проект"]}'::jsonb, '[{"text":"«пришлите УПД и счёт-фактуру»","code":"DOCUMENTS_REQUESTED"},{"text":"«пришлите акт сверки»","code":"RECONCILIATION_REQUESTED"},{"text":"«отчёт обещали ещё в понедельник»","code":"COMPLAINT_TIMING"}]'::jsonb, '«Подготовьте, пожалуйста, итоговый отчёт по результатам промо в наших магазинах за ноябрь до 10 декабря.»', '«Пришлите акты за октябрь для бухгалтерии» → закрывающие документы, не отчёт.', 'Укажи, какой отчёт, за какой период и к какому сроку; шаги — собрать данные, подготовить отчёт, отправить к сроку.', 6, 'fixed', 'fyi', false, 'event', 'medium', false, true, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Closed by: — (no "report sent" state code; see Open points)
Date gate: — (the report deadline goes to `facts.deadlines`, owner = us)
Relevance window: until the report deadline, if given; else default
Relations: the `DELIVERY_REPORT_OPEN` watchdog follows this code.
Deal effect: per org rule. Usual: none.', NULL, NULL),
  ('DELIVERY_REPORT_OPEN', 'base', 'C', 'delivery', 'Запрошенный отчёт ещё не предоставлен', 'Клиент запросил отчёт, мы его обещали, но отчёт не отправлен в срок. Создаётся процессом.', 'Жалоба клиента на задержку отчёта — COMPLAINT_TIMING. Без исходного DELIVERY_REPORT_REQUESTED — нет сигнала.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, 'Клиент просил отчёт до 10.12; на 11.12 в теме нет нашего письма с отчётом.', '', 'Укажи отчёт и пропущенный срок; шаги — отправить отчёт или сообщить клиенту новый срок.', 4, 'fixed', 'risk', false, 'watchdog', 'medium', false, false, false, 'process', 'onHold', NULL, 'account', '{}'::text[], NULL, NULL, '{"ru":"RU: есть открытый DELIVERY_REPORT_REQUESTED; срок (facts.deadlines, owner = us, или окно организации) прошёл; в теме нет нашего письма с отчётом. EN: an open DELIVERY_REPORT_REQUESTED; the deadline (owner = us, else the org window) passed; no outgoing report on the topic."}'::jsonb, 'Closed by: a recorded report sending on the topic (no state code today)
Relations: follows `DELIVERY_REPORT_REQUESTED`.
Deal effect: per org rule. Usual: none.', NULL, NULL),
  ('DELIVERY_PROTOCOL', 'base', 'C', 'delivery', 'Получен протокол или итоги встречи от клиента', 'От клиента пришёл протокол, итоги или резюме встречи, совещания или звонка. Для информации.', 'Наш собственный исходящий протокол — не этот код. Повестка будущей встречи — нет сигнала. Если в протоколе есть новая задача для нас (запрос КП, отчёта, жалоба) — указать ещё и соответствующий код; протокол сам по себе — только информация.', ARRAY['протокол встречи', 'итоги встречи', 'по итогам совещания', 'резюме звонка', 'фиксируем договорённости', 'протокол во вложении', 'краткие итоги', 'договорились о следующем']::text[], '{"business":["направляем протокол рабочей встречи от 12.11","по итогам совещания фиксируем следующие договорённости","во вложении протокол переговоров","кратко резюмирую итоги нашего звонка","прошу проверить протокол и дать комментарии"],"chat":["закинула итоги созвона","фиксирую, о чём договорились","по встрече: 1) 2) 3)","вот наши записи со встречи"],"terms":["протокол","MoM","минутки","резюме","follow-up","итоги"],"patterns":["«по итогам» + «встречи / совещания / звонка»","«фиксируем / договорились» + список пунктов"]}'::jsonb, '[{"text":"«направляем протокол нашей встречи» (наше письмо)","code":null},{"text":"«повестка на четверг»","code":null},{"text":"«по итогам встречи просим КП до пятницы»","code":"SALES_OFFER_REQUESTED"}]'::jsonb, '«Коллеги, направляем протокол встречи от 12.11: согласовали запуск дегустаций в трёх ресторанах, следующая встреча — 26.11.»', '«Предлагаю повестку на четверг: ассортимент, условия, логистика» → будущая встреча, протокола нет.', 'Кратко перечисли договорённости из протокола; шаг — сверить с нашими записями и внести сроки в задачи.', 2, 'fixed', 'fyi', false, 'event', 'medium', false, false, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule. Usual: none (deal-state context).', NULL, NULL),
  ('THREAD_DEADLINE_NEAR', 'base', 'C', 'delivery', 'До срока по теме осталось не более двух дней', 'Ближайший открытый срок по теме (наш срок) наступает не позже чем через два дня. Вычисляется процессом; припаркован вместе с логикой тредов.', 'Срок клиента (owner = them) — не этот код. В Topics эту задачу частично решает эскалация по сроку (спец. §8.2), поэтому код остаётся припаркованным.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, 'Клиент просил КП к 14.11; 12.11 КП ещё не отправлено.', '', 'Укажи срок и что нужно сдать; шаг — закрыть задачу до срока или предупредить клиента.', 4, 'fixed', 'risk', false, 'derived', 'medium', false, false, false, 'process', 'parked', NULL, 'account', '{}'::text[], NULL, NULL, '{"ru":"RU: у темы есть открытый срок из facts.deadlines с owner = us; до него ≤ 2 рабочих дней по производственному календарю РФ; тема не закрыта. EN: the topic has an open deadline (owner = us) at most 2 working days away (Russian production calendar); the topic is open."}'::jsonb, 'Closed by: — (the deadline is met or moved)
Relevance window: until the deadline
Deal effect: per org rule. Usual: none.', NULL, NULL),
  ('INVOICE_OVERDUE', 'base', 'D', 'invoice', 'Наш счёт клиенту не оплачен в срок или оспорен', 'Наш (исходящий) счёт клиенту не оплачен в срок, есть задолженность, или клиент оспаривает счёт. Код ставится и на наше письмо-напоминание об оплате, и на сообщение клиента о задержке или споре.', 'Входящий счёт поставщика НАМ — не этот код. Счёт ещё не просрочен и вопросов нет — нет сигнала. Клиент обещает оплатить к дате — PAYMENT_PROMISE (дистрибуция) на той же теме; в базе — контекст к этому коду. Запрос акта сверки без долга — RECONCILIATION_REQUESTED (дистрибуция). Просьба об отсрочке на будущее — PAYMENT_TERMS_REQUEST (дистрибуция) / SALES_RENEGOTIATION.', ARRAY['напоминаем об оплате', 'просрочка', 'задолженность', 'акт сверки показывает долг', 'просрочка оплаты', 'дебиторка', 'счёт не оплачен', 'оспариваем счёт']::text[], '{"business":["напоминаем, что срок оплаты по счёту № истёк","за вами числится задолженность в размере","просим погасить просроченную задолженность","по акту сверки на 01.11 задолженность составляет","досудебная претензия об оплате","не согласны с суммой счёта, просим скорректировать","оплата задерживается в связи с"],"chat":["когда оплатите?","у вас долг висит с октября","бухгалтерия пока не провела","оплата съехала на следующую неделю","счёт неверный, не будем пока платить"],"terms":["ДЗ","дебиторка","просрочка","акт сверки","претензия","пени","неустойка","отсрочка истекла","ПП не поступало"],"patterns":["«срок оплаты» + «истёк / прошёл»","«задолженность в размере» + сумма","просим оплатить / погасить","не согласны со счётом"]}'::jsonb, '[{"text":"«во вложении счёт от поставщика на оплату» (нам)","code":null},{"text":"«оплатили, платёжка во вложении»","code":"INVOICE_PAID"},{"text":"«оплатим до пятницы»","code":"PAYMENT_PROMISE"},{"text":"«пришлите акт сверки за квартал»","code":"RECONCILIATION_REQUESTED"}]'::jsonb, '«Напоминаем, что по счёту № 1187 от 02.10 на 214 600 руб. срок оплаты истёк 16.10, просим погасить задолженность до конца недели.»', '«Счёт № 1240 получили, оплатим в установленный договором срок» → просрочки нет.', 'Укажи счёт, сумму, дату и число дней просрочки; шаги — связаться с бухгалтерией клиента, выяснить причину, согласовать дату оплаты.', 7, 'fixed', 'risk', false, 'event', 'medium', true, false, false, 'both', 'active', NULL, 'finance', '{}'::text[], NULL, NULL, NULL, 'Closed by: `INVOICE_PAID`
Relations: — in v204. Agency: one card with `INVOICE_DISPUTE_RAISED` (a dispute does not replace the overdue fact, Maslov §5.5). Distribution: `PAYMENT_PROMISE` attaches to this topic.
Deal effect: per org rule. IN4COM: risk trigger «Долг клиента» (open deal of this client); clears with `INVOICE_PAID` or a kept `PAYMENT_PROMISE`.', NULL, NULL),
  ('INVOICE_PAID', 'base', 'D', 'invoice', 'Клиент оплатил счёт', 'Служебное событие: клиент сообщает об оплате нашего счёта или мы фиксируем поступление денег. Закрывает открытый вопрос просрочки по этому счёту; карточку не создаёт.', 'Обещание оплатить — не оплата (PAYMENT_PROMISE в дистрибуции). Урегулирование спора без оплаты — не этот код (агентский INVOICE_DISPUTE_RESOLVED). Наша оплата поставщику — не этот код. Частичная оплата закрывает только оплаченную часть: если долг остаётся, INVOICE_OVERDUE остаётся открытым.', ARRAY['оплатили', 'платёжка', 'деньги ушли', 'платёжное поручение', 'оплата прошла', 'оплата поступила', 'счёт оплачен', 'перевели']::text[], '{"business":["оплата по счёту № произведена, платёжное поручение во вложении","денежные средства перечислены","подтверждаем оплату","задолженность погашена в полном объёме","оплата поступила на расчётный счёт"],"chat":["оплатили, кидаю платёжку","деньги ушли","перевели сегодня","закинули оплату","платёжка в почте"],"terms":["ПП","п/п","платёжка","платёжное поручение","выписка банка","зачисление"],"patterns":["«оплачен(о) / оплатили» + счёт","«перечислили / перевели» + сумма","платёжное поручение во вложении"]}'::jsonb, '[{"text":"«оплатим в пятницу»","code":"PAYMENT_PROMISE"},{"text":"«отправили платёжку на согласование директору»","code":null},{"text":"«спор по счёту сняли»","code":"INVOICE_DISPUTE_RESOLVED"}]'::jsonb, '«Счёт № 1187 оплатили сегодня, платёжное поручение во вложении.»', '«Платёж поставили в реестр на следующую неделю» → это обещание, оплаты ещё нет.', 'Карточку не создавать; закрыть открытую просрочку по этому счёту, при частичной оплате оставить остаток открытым.', 0, 'state', NULL, false, 'state', NULL, false, false, false, 'both', 'active', 'S0', 'finance', ARRAY['INVOICE_OVERDUE']::text[], NULL, NULL, NULL, 'Display profile: S0 (state code, closes and makes no card)
Closes: `INVOICE_OVERDUE` (same client / invoice topic)
Deal effect: per org rule. IN4COM: clears the risk «Долг клиента». Payment is a separate fact, never a stage move.', NULL, NULL),
  ('COMPLAINT_PRICE', 'base', 'E', 'complaint', 'Жалоба на цену или условия', 'Клиент недоволен нашей ценой или условиями: считает дорого, ссылается на более дешёвое предложение конкурента, возмущается ростом цен или условиями оплаты и поставки.', 'Конкретная просьба изменить согласованные условия — SALES_RENEGOTIATION (может быть вместе с этим кодом). Отказ от КП из-за цены — SALES_OFFER_DECLINED. Нейтральный вопрос о цене — SALES_PRICE_REQUEST. Поставщик повышает цены НАМ — SUPPLIER_PRICE_CHANGE. Ошибка в цене в счёте — INVOICE_OVERDUE (спор по счёту).', ARRAY['у другого поставщика дешевле', 'нам предложили по цене ниже', 'слишком дорого', 'цены неприемлемы', 'опять подняли цены', 'у конкурентов условия лучше', 'не можем работать по таким ценам', 'цена не рыночная']::text[], '{"business":["ваши цены существенно выше рыночных","нам поступило предложение на аналогичную позицию на 15% дешевле","повышение цен с 1 декабря для нас неприемлемо","условия оплаты не соответствуют рынку","просим обосновать повышение стоимости","при таких ценах вынуждены рассмотреть других поставщиков"],"chat":["чего так дорого?","вы опять цены задрали","у других то же самое дешевле на сотку","нам у соседей дали лучше","ну это грабёж","за такие деньги не возьмём"],"terms":["наценка","РРЦ","спеццена","рыночная цена","конкурентное предложение","прайс конкурента"],"patterns":["дорого / дороже / выше рынка","«у других / у конкурентов / нам предложили» + «дешевле / по цене ниже»","«повышение цен» + «неприемлемо / не согласны»"]}'::jsonb, '[{"text":"«просим поднять скидку до 12%»","code":"SALES_RENEGOTIATION"},{"text":"«сколько стоит Шабли?»","code":"SALES_PRICE_REQUEST"},{"text":"«производитель повышает цены с января» (письмо поставщика)","code":"SUPPLIER_PRICE_CHANGE"},{"text":"«цены хорошие, всё устраивает»","code":"FEEDBACK_PRICE_PRAISE"}]'::jsonb, '«Нам предложили то же Просекко у другого поставщика по 690 руб. за бутылку, а у вас 820 — честно говоря, не понимаем, почему такая разница.»', '«Подскажите, какая цена на Просекко при заказе от 10 коробок?» → это нейтральный запрос цены.', 'Укажи, на что жалуется клиент и какую цену конкурента называет; шаги — проверить сравнимость предложения, подготовить аргументы или вариант условий, связаться с ЛПР.', 8, 'fixed', 'risk', false, 'event', 'medium', false, true, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Closed by: — (agency: `COMPLAINT_RESOLUTION_CONFIRMED`)
Relations: both with `COMPLAINT_ESCALATED` (the escalation and the complaint underneath it). Often together with `SALES_RENEGOTIATION`.
Deal effect: per org rule. IN4COM: risk trigger **«Конкурент предлагает дешевле»** (incl. a competitor''s cheaper offer; not at the first-contact stage).', NULL, NULL),
  ('COMPLAINT_ESCALATED', 'base', 'E', 'complaint', 'Жалоба передана на более высокий уровень', 'Клиент поднимает проблему на более высокий уровень: подключает своего руководителя, пишет нашему руководству, ставит их в копию, грозит официальной претензией или обращается «выше».', 'Обычная жалоба без вовлечения руководства — только соответствующий COMPLAINT_*. Руководитель клиента просто в копии рабочей переписки без жалобы — нет сигнала. Внутренняя эскалация у нас (коллега пишет коллеге) — блок J (TEAM_ESCALATION, gated). Угроза расторжения без решения — этот код + жалоба, не CONTRACT_TERMINATED.', ARRAY['ставлю в копию руководство', 'пишу вашему директору', 'вынуждены обратиться к руководству', 'передаю вопрос генеральному', 'досудебная претензия', 'направляем официальную претензию', 'эскалируем', 'прошу подключить вашего руководителя']::text[], '{"business":["в связи с отсутствием реакции ставлю в копию вашего генерального директора","вопрос передан на уровень коммерческого директора","направляем официальную претензию","будем вынуждены обратиться к руководству вашей компании","прошу руководителя отдела продаж взять ситуацию на контроль","досудебная претензия во вложении"],"chat":["я уже нашему директору пожаловалась","если не решите, иду к вашему начальству","дайте контакт вашего руководителя","подключаю шефа, разбирайтесь"],"terms":["эскалация","претензия","досудебка","ГД","КД","в копии","на контроле у руководства"],"patterns":["«ставлю в копию» + руководитель","«обратиться / передать» + «руководству / директору»","официальная / досудебная претензия"]}'::jsonb, '[{"text":"руководитель клиента в копии письма о графике поставок без жалобы","code":null},{"text":"«опять задержка» без вовлечения руководства","code":"COMPLAINT_TIMING"},{"text":"коллега пишет нам внутри компании «клиент недоволен»","code":null}]'::jsonb, '«Это уже третья задержка за месяц, ставлю в копию вашего коммерческого директора и прошу взять ситуацию на личный контроль.»', '«Ставлю в копию нашего директора, чтобы он видел график поставок на декабрь» → информирование, не эскалация жалобы.', 'Укажи, кто подключён и какая проблема под эскалацией; шаги — ответить в тот же день с позиции руководителя, дать план решения и срок.', 8, 'fixed', 'risk', false, 'event', 'medium', false, true, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Closed by: — (agency: `COMPLAINT_RESOLUTION_CONFIRMED` closes the complaint and the linked escalation)
Relations: both with `COMPLAINT_PRICE`, `COMPLAINT_TIMING`, `COMPLAINT_COMM`, `COMPLAINT_QUANTITY`, `COMPLAINT_QUALITY` (the escalation and the complaint underneath it; one incident card, Maslov §5.5).
Deal effect: per org rule. IN4COM: risk trigger **«Повторные жалобы»** (one escalated complaint is enough).', NULL, NULL),
  ('COMPLAINT_TIMING', 'base', 'E', 'complaint', 'Жалоба на сроки и задержку с нашей стороны', 'Клиент жалуется на задержку с нашей стороны: поставка, результат, документ, отчёт или обещанный ответ по задаче пришли позже срока или до сих пор не пришли.', 'Поставщик сообщает НАМ, что его поставка задерживается, — SUPPLIER_DELIVERY_DELAY. Клиент не может до нас дозвониться, нам не отвечают на письма вообще — COMPLAINT_COMM (здесь — задержка конкретного результата или обещания). Нейтральный вопрос «когда привезёте?» без упрёка — не жалоба (в дистрибуции DELIVERY_SCHEDULE_REQUEST). Задержка по вине клиента — нет этого кода.', ARRAY['сорвали сроки', 'опять задержка', 'мы до сих пор ждём', 'не привезли вовремя', 'обещали ещё в понедельник', 'срок прошёл', 'сколько можно ждать', 'у нас из-за вас простой']::text[], '{"business":["поставка по заказу № не выполнена в согласованный срок","вы нарушили сроки, установленные договором","до настоящего времени товар не получен","обещанный отчёт так и не поступил","просим объяснить причины задержки","из-за задержки мы сорвали открытие"],"chat":["ну что там по доставке??","где машина?","опять не привезли","вы обещали к обеду, уже вечер","третий раз переносите","«гости ждут, а вина нет» (дистрибуция)"],"terms":["просрочка поставки","срыв сроков","неустойка за просрочку","пени","SLA"],"patterns":["«до сих пор / так и не» + «не получили / не пришло»","«опять / снова / в который раз» + «задержка / перенос»","«обещали к» + дата"]}'::jsonb, '[{"text":"«контейнер задерживается на таможне» (письмо поставщика нам)","code":"SUPPLIER_DELIVERY_DELAY"},{"text":"«третий день не можем до вас дозвониться»","code":"COMPLAINT_COMM"},{"text":"«подскажите, в какое окно привезёте?»","code":"DELIVERY_SCHEDULE_REQUEST"},{"text":"«пока не получили» (факт без упрёка)","code":null}]'::jsonb, '«Заказ должны были привезти во вторник, сегодня пятница — мы до сих пор ждём, и это уже вторая задержка подряд.»', '«Поставку пока не получили, подскажите, пожалуйста, ориентировочное время» → нейтральный вопрос, без упрёка.', 'Укажи, что задерживается и на сколько; шаги — выяснить статус, дать клиенту точный срок, предложить компенсацию при повторе.', 7, 'fixed', 'risk', false, 'event', 'medium', false, true, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Closed by: — (agency: `COMPLAINT_RESOLUTION_CONFIRMED`)
Relations: both with `COMPLAINT_ESCALATED`.
Deal effect: per org rule. IN4COM: risk trigger **«Повторные жалобы»** (≥ 2 complaints of this client in 30 days).', NULL, NULL),
  ('COMPLAINT_COMM', 'base', 'E', 'complaint', 'Жалоба на коммуникацию и недоступность', 'Клиент жалуется, что до нас не достучаться: не отвечаем на письма и звонки, отвечаем медленно, путаем, не держим в курсе, меняем контактных лиц без предупреждения.', 'Задержка конкретного результата, поставки или документа — COMPLAINT_TIMING. Клиент просто повторно пишет без упрёка — не жалоба (повторы считает THREAD_UNANSWERED_FOLLOWUP, parked). Жалоба на грубость или ошибки сотрудника в работе — этот код, если про общение; если про результат — COMPLAINT_QUALITY.', ARRAY['не можем до вас дозвониться', 'вы не отвечаете', 'жду ответа третий день', 'никто не перезвонил', 'нас не держат в курсе', 'невозможно связаться с менеджером', 'пишу уже не первый раз', 'отвечаете через неделю']::text[], '{"business":["на наши письма от 05.11 и 08.11 ответа не поступило","не можем связаться с закреплённым менеджером","просим назначить контактное лицо, которое будет отвечать","информацию приходится запрашивать по несколько раз","нас не уведомили об изменениях"],"chat":["ау, есть кто живой?","вы вообще читаете?","третий раз пишу","до менеджера не дозвониться","почему никто не отвечает?","игнорите?"],"terms":["нет обратной связи","ОС","не на связи","менеджер недоступен"],"patterns":["«не можем / невозможно» + «дозвониться / связаться»","«не отвечаете / не ответили» + срок","уже не первый раз пишу"]}'::jsonb, '[{"text":"«где обещанное КП, срок был вчера?»","code":"COMPLAINT_TIMING"},{"text":"«напоминаю о своём вопросе» без упрёка","code":null},{"text":"«спасибо, что всегда на связи»","code":"FEEDBACK_COMM_PRAISE"}]'::jsonb, '«Третий день не можем дозвониться до вашего менеджера, на письма тоже тишина — с кем вообще можно решить вопрос?»', '«Добрый день, напомню про мой вопрос по ассортименту, когда будет возможность — ответьте» → вежливое напоминание без упрёка.', 'Укажи, сколько клиент ждёт ответа и по какому вопросу; шаги — ответить сегодня, назвать контактное лицо и способ связи.', 7, 'fixed', 'risk', false, 'event', 'medium', false, true, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Closed by: — (agency: `COMPLAINT_RESOLUTION_CONFIRMED`)
Relations: both with `COMPLAINT_ESCALATED`.
Deal effect: per org rule. Usual: none (not in the IN4COM risk list).', NULL, NULL),
  ('COMPLAINT_QUANTITY', 'base', 'E', 'complaint', 'Жалоба на недопоставку (меньше согласованного)', 'Клиент получил меньше, чем согласовано: не тот объём, не хватает позиций, количество меньше заказанного. «Мало» — это объём, даже если клиент называет это браком.', 'Неверное качество, вкус, дефект товара — COMPLAINT_QUALITY. В организации с пакетом дистрибуции расхождение, выявленное при приёмке конкретной поставки (недовложение, бой, пересорт, акт ТОРГ-2), — DELIVERY_DISCREPANCY; этот код остаётся для жалобы на объём в целом (систематическая недопоставка, урезанный объём заказа без согласования). Наша плановая частичная отгрузка, о которой клиент знает, — нет сигнала.', ARRAY['пришло меньше', 'не хватает позиций', 'недопоставка', 'недогруз', 'отгрузили не всё', 'заказывали 50, пришло 30', 'урезали заказ', 'объём не соответствует заказу']::text[], '{"business":["поставка выполнена не в полном объёме","по заказу № отгружено 30 из 50 единиц","отсутствуют позиции, указанные в спецификации","объём выполненных работ не соответствует договору","систематически поставляете меньше заказанного"],"chat":["пришло меньше, чем заказывали","опять не всё привезли","где ещё две коробки?","вы нам ползаказа привезли","половины позиций нет"],"terms":["недопоставка","недогруз","«недовложение» (в дистрибуции → DELIVERY_DISCREPANCY)","частичная отгрузка","отгрузка не в полном объёме"],"patterns":["заказывали столько-то, а пришло меньше","«не хватает» + позиции / штук","не в полном объёме"]}'::jsonb, '[{"text":"«две бутылки пришли битые»","code":"DELIVERY_DISCREPANCY"},{"text":"«вино пробковое»","code":"COMPLAINT_QUALITY"},{"text":"«по акту приёмки недовложение 3 бутылки»","code":"DELIVERY_DISCREPANCY"},{"text":"«остаток заказа довезите в четверг, как договаривались»","code":null}]'::jsonb, '«Уже второй раз подряд вы отгружаете не весь заказ: заказывали 40 коробок, пришло 28, остальное никто не согласовывал.»', '«При приёмке обнаружили недовложение 2 бутылок, составили акт ТОРГ-2» → в организации с пакетом дистрибуции это DELIVERY_DISCREPANCY.', 'Укажи заказ, сколько заказано и сколько пришло; шаги — проверить отгрузку, согласовать довоз или корректировку документов.', 7, 'fixed', 'risk', false, 'event', 'medium', false, true, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Closed by: — (distribution: `DELIVERY_DISCREPANCY_RESOLVED` when the case is a discrepancy)
Relations: leads over `COMPLAINT_QUALITY` (when too little was delivered); both with `COMPLAINT_ESCALATED`.
Deal effect: per org rule. Usual: none (not in the IN4COM risk list).', NULL, NULL),
  ('COMPLAINT_QUALITY', 'base', 'E', 'complaint', 'Жалоба на качество, брак или ошибку', 'То, что мы поставили или сделали, с дефектом: брак, ошибка, не тот товар или результат, техническая неисправность, рекламация. В вине: пробковый тон, окисление, осадок, подтёк, повреждённая этикетка.', 'Пришло меньше — COMPLAINT_QUANTITY (ведёт). В организации с пакетом дистрибуции бой, недовложение и пересорт при приёмке — DELIVERY_DISCREPANCY; просьба вернуть товар — RETURN_REQUESTED (вместе с этим кодом, если причина — брак). Ошибка в счёте — INVOICE_OVERDUE (спор). Вкусовое «нам не понравилось» без дефекта — нет сигнала или SALES_OFFER_DECLINED.', ARRAY['брак', 'ошибка', 'не то', 'претензия', 'рекламация', 'возврат', 'пробковый', 'повреждена этикетка']::text[], '{"business":["направляем претензию по качеству поставленного товара","выявлены дефекты","товар не соответствует заявленным характеристикам","просим заменить бракованную продукцию","прошу принять рекламацию","в результате допущена ошибка в","требуем возврата денежных средств за некачественный товар"],"chat":["«вино пробковое» (дистрибуция)","«бутылка окислилась» (дистрибуция)","«в бутылках осадок, гости вернули» (дистрибуция)","«подтёк по пробке» (дистрибуция)","«этикетки рваные» (дистрибуция)","прислали не то","опять косяк","это брак, заберите"],"terms":["брак","рекламация","претензия","несоответствие","«пересорт» (в дистрибуции → DELIVERY_DISCREPANCY)","пробковый тон","TCA","окислено","«осадок» (дистрибуция)"],"patterns":["«претензия / рекламация по» + товар или работа","«не соответствует» + требованию","«просим заменить / вернуть» + из-за дефекта"]}'::jsonb, '[{"text":"«пришло 30 вместо 50»","code":"COMPLAINT_QUANTITY"},{"text":"«при приёмке 3 бутылки бой»","code":"DELIVERY_DISCREPANCY"},{"text":"«хотим вернуть нераспроданное» без дефекта","code":"RETURN_REQUESTED"},{"text":"«гостям не зашло, слишком кислое»","code":null}]'::jsonb, '«Из последней партии Шабли уже четыре бутылки с пробковым тоном, гости вернули — просим заменить и разобраться с партией.»', '«Гостям больше понравилось Совиньон, чем Шардоне, в следующий раз возьмём его» → предпочтение, не дефект.', 'Укажи товар или работу, суть дефекта и партию; шаги — запросить фото и документы, согласовать замену или возврат, проверить партию.', 7, 'fixed', 'risk', false, 'event', 'medium', false, true, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Closed by: — (agency: `COMPLAINT_RESOLUTION_CONFIRMED`)
Relations: `COMPLAINT_QUANTITY` leads over this code (when too little was delivered); both with `COMPLAINT_ESCALATED`. Successor of retired `COMPLAINT_ERROR`.
Deal effect: per org rule. IN4COM: risk trigger **«Повторные жалобы»** (≥ 2 complaints of this client in 30 days).', NULL, NULL),
  ('FEEDBACK_REFERRAL', 'base', 'E', 'contact', 'Клиент рекомендует нас или даёт контакт', 'Клиент рекомендует нас другим компаниям или людям, даёт конкретный контакт, знакомит нас; либо новый контакт пишет, что нас ему рекомендовал наш клиент.', 'Общая похвала без рекомендации — FEEDBACK_QUALITY_PRAISE / FEEDBACK_COMM_PRAISE. Предложение познакомить с конкретным человеком в агентском пакете — PROSPECT_INTRODUCTION_OFFERED. Новый контакт у того же клиента — CONTACT_NEW_KNOWN_ORG. Рекомендация поставщика нам — нет сигнала.', ARRAY['рекомендовали вас', 'порекомендовал вас коллегам', 'передал ваш контакт', 'знакомлю вас с', 'вас нам посоветовали', 'могу дать контакт', 'свяжитесь с', 'рассказал о вас партнёрам']::text[], '{"business":["рекомендовали вашу компанию нашим партнёрам","передали ваши контакты в","позвольте представить вам","знакомлю вас с коммерческим директором","к вам обратится наш партнёр, он в курсе","нам вас рекомендовала компания"],"chat":["«дал ваш номер знакомому ресторатору» (дистрибуция)","«скинула ваш контакт подруге, у неё бар» (дистрибуция)","вас советуют","наберите Ивану, он ждёт звонка","добавила вас в чат с"],"terms":["рекомендация","реферал","интро","тёплый контакт"],"patterns":["«рекомендовал(а) вас» + кому","«передал ваш контакт» + кому","«знакомлю вас с» + человек","«вас нам рекомендовал(а)» + кто"]}'::jsonb, '[{"text":"«работаем с вами с удовольствием»","code":"FEEDBACK_QUALITY_PRAISE"},{"text":"«теперь по закупкам пишите Анне»","code":"CONTACT_NEW_KNOWN_ORG"},{"text":"«могу познакомить с директором сети, если интересно»","code":"PROSPECT_INTRODUCTION_OFFERED"}]'::jsonb, '«Рекомендовали вас нашим друзьям из ресторана на Патриарших, передала ваш контакт их управляющему — он напишет на этой неделе.»', '«Спасибо, всё отлично, будем работать дальше» → похвала без рекомендации.', 'Укажи, кому клиент нас рекомендовал и есть ли контакт; шаги — поблагодарить клиента, связаться с рекомендованным контактом.', 5, 'fixed', 'chance', false, 'event', 'medium', false, false, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule. Usual: none for the referring client; the referred company is a new lead (its own request creates its own deal).', NULL, NULL),
  ('FEEDBACK_QUALITY_PRAISE', 'base', 'E', 'account', 'Похвала качеству', 'Клиент хвалит качество нашего товара, работы или результата. Действие не требуется.', 'Похвала менеджеру или общению — FEEDBACK_COMM_PRAISE. Похвала цене — FEEDBACK_PRICE_PRAISE. Вежливое «спасибо, получили» — нет сигнала. Похвала не закрывает чужую жалобу и не означает заказ.', ARRAY['гостям очень понравилось', 'отличное качество', 'всё на высшем уровне', 'очень довольны результатом', 'вино прекрасно зашло', 'претензий нет, всё идеально', 'превзошли ожидания', 'прекрасная работа']::text[], '{"business":["благодарим за качественно выполненную работу","результат полностью соответствует ожиданиям","отмечаем высокое качество продукции","руководство высоко оценило результат"],"chat":["«гостям очень понравилось» (дистрибуция)","«вино на ура» (дистрибуция)","огонь!","супер, всё чётко","шикарно получилось","топ"],"terms":["качество","результат","без замечаний"],"patterns":["очень понравилось / понравился / понравилась","«отличное / прекрасное» + качество / результат","благодарим за качественно"]}'::jsonb, '[{"text":"«спасибо, получили»","code":null},{"text":"«Анна всегда быстро отвечает, спасибо»","code":"FEEDBACK_COMM_PRAISE"},{"text":"«гостям понравилось, давайте ещё 10 коробок»","code":"ORDER_REQUESTED"}]'::jsonb, '«Хотим сказать спасибо за подборку на банкет — гостям очень понравилось, особенно Бароло.»', '«Спасибо, документы получили» → вежливость, не похвала.', 'Отметь, что именно понравилось клиенту; шаг — использовать как повод для следующего предложения или отзыва.', 3, 'fixed', 'fyi', false, 'event', 'medium', false, false, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Closes: — (praise never closes a complaint, Maslov §5.5)
Deal effect: per org rule. Usual: none.', NULL, NULL),
  ('FEEDBACK_COMM_PRAISE', 'base', 'E', 'account', 'Похвала работе менеджера и коммуникации', 'Клиент хвалит работу нашего менеджера, скорость ответа, сопровождение и общение. Действие не требуется.', 'Похвала товару или результату — FEEDBACK_QUALITY_PRAISE. Обычное «спасибо за быстрый ответ» в конце деловой переписки — нет сигнала, если нет оценки работы. Похвала не закрывает жалобу.', ARRAY['спасибо за оперативность', 'всегда на связи', 'приятно с вами работать', 'отличное сопровождение', 'ваш менеджер — молодец', 'быстро решили вопрос', 'чёткая коммуникация', 'благодарим за внимательное отношение']::text[], '{"business":["выражаем благодарность вашему менеджеру за профессиональное сопровождение","отмечаем оперативность и внимательность","с вами комфортно работать","благодарим за слаженную работу команды"],"chat":["вы лучшие, всегда на связи","спасибо, что так быстро","Мария — золото","с вами легко"],"terms":["сервис","сопровождение","клиентский сервис","персональный менеджер"],"patterns":["«спасибо / благодарим за» + «оперативность / сопровождение / внимание»","приятно / комфортно работать"]}'::jsonb, '[{"text":"«спасибо за ответ» (формула вежливости)","code":null},{"text":"«вино отличное»","code":"FEEDBACK_QUALITY_PRAISE"},{"text":"«наконец-то ответили»","code":"COMPLAINT_COMM"}]'::jsonb, '«Отдельное спасибо вашему менеджеру — за выходные помог собрать срочный заказ, с вами очень комфортно работать.»', '«Спасибо за ответ, хорошего дня» → вежливость, не оценка.', 'Отметь, кого и за что похвалил клиент; шаг — передать благодарность сотруднику и руководителю.', 2, 'fixed', 'fyi', false, 'event', 'medium', false, false, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule. Usual: none.', NULL, NULL),
  ('FEEDBACK_PRICE_PRAISE', 'base', 'E', 'account', 'Клиент подтвердил, что условия справедливые', 'Клиент говорит, что наши цены или условия справедливые, выгодные, устраивают. Действие не требуется.', 'Согласие с КП как решение купить — SALES_BOOKING_RECEIVED. Нейтральное «цены получили» — нет сигнала. Ирония («ну и цены у вас, конечно») — COMPLAINT_PRICE.', ARRAY['цены адекватные', 'условия устраивают', 'хорошее соотношение цены и качества', 'цены честные', 'выгоднее, чем у других', 'по цене всё ок', 'справедливые условия', 'довольны ценами']::text[], '{"business":["условия поставки нас полностью устраивают","отмечаем конкурентный уровень цен","ваше предложение выгоднее альтернатив","соотношение цены и качества оптимальное"],"chat":["по ценам норм","цены огонь","дешевле, чем у других, берём вас","за эти деньги — супер"],"terms":["цена-качество","конкурентные цены","рыночный уровень"],"patterns":["«устраивают» + «цены / условия»","«выгоднее, чем» + у других"]}'::jsonb, '[{"text":"«ну и цены у вас»","code":"COMPLAINT_PRICE"},{"text":"«согласовали КП, запускайте»","code":"SALES_BOOKING_RECEIVED"},{"text":"«прайс получили»","code":null}]'::jsonb, '«Сравнили с двумя другими поставщиками — у вас самые адекватные условия, так что продолжаем работать.»', '«Прайс получили, изучим» → нет оценки.', 'Отметь, что клиент считает условия выгодными; шаг — сохранить как аргумент при будущих переговорах о цене.', 2, 'fixed', 'fyi', false, 'event', 'medium', false, false, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule. Usual: none; may be cited as evidence that the IN4COM risk «Конкурент предлагает дешевле» is cleared («клиент подтверждает наше предложение»).', NULL, NULL),
  ('THREAD_UNANSWERED_FOLLOWUP', 'base', 'E', 'complaint', 'Повторные напоминания клиента остались без ответа', 'Клиент написал нам по одной теме два раза и больше, а мы не ответили. Вычисляется процессом; припаркован вместе с логикой тредов.', 'Если в напоминании есть упрёк, модель ставит COMPLAINT_COMM сама; этот код — только подсчёт повторов. Наши повторные письма клиенту — не этот код.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, 'Клиент написал 10.11 и 11.11 «напомню про мой вопрос по отгрузке», на 12.11 ответа от нас нет.', '', 'Укажи, сколько раз и с какого дня клиент ждёт ответа; шаг — ответить сегодня по существу.', 3, 'fixed', 'risk', false, 'derived', 'medium', false, false, false, 'process', 'parked', NULL, 'account', '{}'::text[], NULL, NULL, '{"ru":"RU: в теме (Topics: topic, sub-state waiting_on_us) ≥ 2 входящих сообщений клиента после нашего последнего ответа, и последнее входящее старше рабочего окна организации; учитываются все каналы. EN: on the topic (sub-state waiting_on_us) at least 2 inbound client messages after our last reply, the last one older than the org working window; all channels counted."}'::jsonb, 'Closed by: our reply on the thread
Deal effect: per org rule. Usual: none.', NULL, NULL),
  ('MEETING_CANCEL', 'base', 'F', 'meeting', 'Клиент отменил встречу без новой даты', 'Клиент отменяет назначенную встречу и не предлагает новую дату.', 'Перенос на конкретную новую дату — не этот код (если дата далеко — MEETING_DELAYED). Отмена с нашей стороны — не сигнал. Автоматический ответ календаря «Отклонено» без слов клиента — обрабатывает детерминированный фильтр; код ставить, только если ясно, что встреча отменена. Отмена дегустации в дистрибуции — этот код, если это встреча с клиентом.', ARRAY['встречу отменяем', 'вынуждены отменить встречу', 'давайте пока без встречи', 'встреча не состоится', 'отменим, потом вернёмся', 'не получится встретиться, позже напишу', 'снимаем встречу', 'пока не до встречи']::text[], '{"business":["к сожалению, вынуждены отменить запланированную встречу","встреча 14.11 не состоится, о новой дате сообщим дополнительно","просим отменить совещание","в текущей ситуации встречу проводить нецелесообразно"],"chat":["завтра не получится, давайте потом","отбой по встрече","сорри, встречу снимаю","пока не до этого, вернусь позже","давайте без встречи, напишу"],"terms":["отмена встречи","созвон отменяется","слот освобождаю"],"patterns":["«отменяем / отменить / не состоится» + встреча","«о новой дате сообщим» (без даты)"]}'::jsonb, '[{"text":"«давайте перенесём на четверг в 15:00»","code":null},{"text":"«предлагаю встретиться в феврале»","code":"MEETING_DELAYED"},{"text":"«Отклонено: Встреча по ассортименту» (автоответ календаря)","code":null}]'::jsonb, '«Завтрашнюю встречу вынуждены отменить, у нас сейчас реорганизация — о новой дате сообщим позже.»', '«Завтра не успеваем, давайте перенесём на пятницу на 11:00» → перенос с новой датой.', 'Укажи, какая встреча отменена и названную причину; шаги — уточнить причину, предложить конкретные варианты дат.', 7, 'fixed', 'risk', false, 'event', 'medium', false, false, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Closed by: — (a new agreed date makes it context)
Deal effect: per org rule. IN4COM: postponement event for the risk «Решение откладывается» (fires from the 2nd distinct postponement of the same decision with no new date and next step, Q24-3). Agency: risk «Снижение вовлечённости» (Maslov risk 21).', NULL, NULL),
  ('MEETING_URGENT', 'base', 'F', 'meeting', 'Клиент просит необычно скорую встречу (интерес)', 'Клиент хочет встретиться необычно скоро — сегодня, завтра, на этой неделе — из интереса: новая возможность, срочный проект, хочет быстро обсудить сотрудничество.', 'Срочная встреча из-за проблемы, ошибки или конфликта — MEETING_URGENT_ISSUE. Обычное приглашение на встречу через 1–3 недели — нет сигнала. В дистрибуции просьба о дегустации или обучении персонала — TASTING_REQUESTED (если ещё и срочно — оба кода).', ARRAY['можем встретиться сегодня?', 'давайте завтра созвонимся', 'срочно нужно обсудить новый проект', 'на этой неделе обязательно встретиться', 'подъедете сегодня?', 'нужно увидеться как можно скорее', 'есть интересная тема, давайте быстро обсудим', 'можем завтра с утра?']::text[], '{"business":["предлагаем провести встречу в ближайшие дни","хотели бы оперативно обсудить расширение сотрудничества","просим о встрече на этой неделе в связи с открытием","готовы встретиться завтра в любое удобное время"],"chat":["можете сегодня заскочить?","давайте завтра кофе","го созвон через час","надо срочно пообщаться, есть тема","до пятницы встретимся?"],"terms":["созвон","зум","ВКС","встреча на объекте","срочно","ASAP"],"patterns":["«встретиться / созвониться» + «сегодня / завтра / на этой неделе / как можно скорее»","повод — интерес, новая задача"]}'::jsonb, '[{"text":"«срочно нужна встреча, у нас пропал товар с полки»","code":"MEETING_URGENT_ISSUE"},{"text":"«давайте в конце месяца пересечёмся»","code":null},{"text":"«нужна дегустация для персонала до открытия»","code":"TASTING_REQUESTED"}]'::jsonb, '«Открываем новую точку раньше плана — можете завтра подъехать и обсудить винную карту?»', '«Завтра срочно нужна встреча: третья поставка подряд с ошибками» → проблема, MEETING_URGENT_ISSUE.', 'Укажи повод и желаемый срок встречи; шаги — подтвердить время сегодня, подготовить материалы под повод.', 6, 'fixed', 'chance', false, 'event', 'quick', false, true, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Relevance window: until the requested meeting date (usually 1–5 days)
Deal effect: per org rule. Usual: none.', NULL, NULL),
  ('MEETING_URGENT_ISSUE', 'base', 'F', 'meeting', 'Срочная встреча из-за нерешённой проблемы', 'Клиент хочет встретиться необычно скоро потому, что что-то не работает, не пришло или пошло не так. Повод — проблема, а не интерес.', 'Срочная встреча из интереса — MEETING_URGENT. Жалоба без просьбы о встрече — только COMPLAINT_*. Плановая встреча по итогам квартала — нет сигнала.', ARRAY['нужно срочно встретиться и разобраться', 'давайте сегодня созвонимся по проблеме', 'ситуация критическая, нужна встреча', 'приезжайте, будем разбираться', 'срочно собираемся по поставкам', 'нужен разговор с руководителем сегодня', 'так дальше нельзя, давайте встретимся', 'надо обсудить, что происходит']::text[], '{"business":["просим о срочной встрече в связи с систематическими срывами поставок","предлагаем незамедлительно провести совещание для урегулирования ситуации","требуется встреча с ответственными лицами до конца недели","прошу организовать встречу с вашим руководством в ближайшее время"],"chat":["приезжайте, будем разбираться","надо срочно созвониться, у нас ЧП","сегодня нужен созвон, всё сломалось","давайте встретимся, пока я не пошла к директору"],"terms":["разбор","совещание","ЧП","инцидент","срочно"],"patterns":["«срочно / сегодня / немедленно» + «встретиться / созвониться» + «разобраться / по проблеме»"]}'::jsonb, '[{"text":"«давайте быстро встретимся, есть новый проект»","code":"MEETING_URGENT"},{"text":"«опять задержка» без просьбы о встрече","code":"COMPLAINT_TIMING"},{"text":"«встреча по итогам года в декабре»","code":null}]'::jsonb, '«У нас третью неделю не сходятся остатки по вашим поставкам — предлагаю завтра встретиться и разобраться на месте.»', '«Есть идея по новому меню, давайте завтра обсудим» → интерес, MEETING_URGENT.', 'Укажи проблему и срок встречи; шаги — подтвердить встречу, собрать факты по проблеме, прийти с планом решения.', 7, 'fixed', 'risk', false, 'event', 'quick', false, false, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Relevance window: until the requested meeting date
Relations: — in v204. Usually together with a `COMPLAINT_*` code.
Deal effect: per org rule. Usual: none; the underlying complaint carries the risk.', NULL, NULL),
  ('MEETING_NEW_STAKEHOLDER', 'base', 'F', 'meeting', 'На встрече новый участник со стороны клиента', 'Клиент приглашает на встречу или приводит на неё человека со своей стороны, которого раньше не было в общении (руководитель, закупщик, финансист, шеф-повар).', 'Новый человек в переписке без встречи — CONTACT_NEW_KNOWN_ORG или CONTACT_NEW_DECISION_MAKER. Участник с нашей стороны — нет сигнала. Новый адрес в копии без роли и без встречи — нет сигнала.', ARRAY['на встрече будет также наш директор', 'подключаю к встрече', 'пригласила на встречу финансового директора', 'с нашей стороны добавится', 'приду с коллегой из закупок', 'к созвону присоединится', 'будет новый управляющий', 'добавила в приглашение']::text[], '{"business":["на встрече со стороны компании также будет присутствовать коммерческий директор","добавила в приглашение руководителя отдела закупок","к обсуждению присоединится наш финансовый директор","прошу учесть, что на встрече будет новый управляющий"],"chat":["«возьму с собой шефа» (дистрибуция: шеф-повар)","«будет наш новый бар-менеджер» (дистрибуция)","подтяну на созвон директора","с нами ещё Олег из закупок"],"terms":["участники встречи","приглашение","ЛПР","ФД","КД","закупщик"],"patterns":["«на встрече будет / присоединится / подключу» + новый человек с ролью"]}'::jsonb, '[{"text":"«теперь по заказам пишите Анне»","code":"CONTACT_NEW_KNOWN_ORG"},{"text":"«с нашей стороны будет руководитель направления» (наше письмо)","code":null},{"text":"новый адрес в копии без встречи","code":null}]'::jsonb, '«На встрече в четверг с нашей стороны будет также новый управляющий сетью — хочет лично познакомиться с поставщиками.»', '«Встреча в четверг в том же составе» → новых участников нет.', 'Укажи нового участника и его роль; шаги — уточнить его интересы, подготовить материалы под его роль.', 5, 'fixed', 'chance', false, 'event', 'medium', false, false, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Relevance window: until the meeting date
Deal effect: per org rule. Usual: in-stage context (people on the deal), no stage move (Maslov §3.1).', NULL, NULL),
  ('MEETING_DELAYED', 'base', 'F', 'meeting', 'Клиент предлагает встречу необычно далеко', 'Клиент предлагает встречу на дату, которая необычно далеко (больше 4 недель от письма). Модель ставит код, когда клиент предлагает встречу и заполнен proposedMeetingDate; далеко ли это, решает система.', 'Модель не оценивает «далеко ли»: при предложенной встрече она заполняет дату, сервер отбрасывает код, если дата ближе окна. Отмена без даты — MEETING_CANCEL. Встречу далеко предлагаем мы — не сигнал. Встреча по условию без даты («после бюджетного комитета») — не этот код (агентский PROSPECT_FOLLOWUP_AGREED).', ARRAY['давайте встретимся в январе', 'вернёмся к разговору после праздников', 'не раньше следующего квартала', 'ближе к весне', 'после 15 января', 'в следующем месяце не получится, давайте в феврале', 'предлагаю перенести на начало года', 'окно есть только в конце декабря']::text[], '{"business":["предлагаем провести встречу в первой половине января","готовы обсудить после утверждения бюджета в феврале","ближайшая возможность — вторая половина декабря","прошу перенести встречу на следующий квартал"],"chat":["давайте после новогодних","до весны вряд ли","в декабре завал, давайте в январе","напишите мне в феврале, встретимся"],"terms":["Q1","в 1 кв.","после НГ","после праздников"],"patterns":["«встретиться / обсудить / вернуться» + месяц или квартал далеко от даты письма","«не раньше» + дата"]}'::jsonb, '[{"text":"«давайте в следующий вторник»","code":null},{"text":"«вернёмся после бюджетного комитета» без даты","code":null},{"text":"«встречу отменяем, о дате сообщим»","code":"MEETING_CANCEL"}]'::jsonb, '«Сейчас сезон, раньше не получится — предлагаю встретиться и обсудить ассортимент после 20 января.»', '«Давайте встретимся в среду на следующей неделе» → дата близко, сервер код отбросит.', 'Укажи предложенную дату и причину; шаги — попробовать договориться о коротком созвоне раньше, держать контакт до встречи.', 4, 'fixed', 'risk', false, 'event', 'medium', false, true, true, 'both', 'active', NULL, 'account', '{}'::text[], '{"fact":"proposedMeetingDate","test":"beyond","settingKey":"cards.meetingDelayedMinDays","days":28}'::jsonb, NULL, NULL, 'Date gate: { fact: `proposedMeetingDate`, test: more than N days after the item, setting: `cards.meetingDelayedMinDays`, window: 28 }
Deal effect: per org rule. IN4COM: postponement event for the risk «Решение откладывается» (2nd distinct postponement, Q24-3).', NULL, NULL),
  ('MEETING_SLOW', 'base', 'F', 'meeting', 'Согласование встречи затягивается', 'По теме несколько отмен или переносов встречи, а дата так и не найдена. Вычисляется процессом; припаркован вместе с логикой тредов.', 'Одна отмена — MEETING_CANCEL. Одна далёкая дата — MEETING_DELAYED. Переносы с нашей стороны не считаются.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, 'Клиент дважды переносил встречу (05.11 и 12.11) и 19.11 написал «давайте позже», новой даты нет.', '', 'Укажи, сколько раз переносили и с какого числа нет даты; шаг — предложить два конкретных слота или короткий созвон.', 5, 'fixed', 'risk', false, 'derived', 'medium', false, false, false, 'process', 'parked', NULL, 'account', '{}'::text[], NULL, NULL, '{"ru":"RU: в теме ≥ 2 отмен или переносов встречи со стороны клиента (MEETING_CANCEL, переносы с новой датой, которые потом снова сорваны) и нет согласованной будущей даты; учитываются все каналы и календарь. EN: on the topic at least 2 client-side cancellations or reschedules and no agreed future date; all channels and the calendar counted."}'::jsonb, 'Closed by: an agreed meeting date on the topic
Deal effect: per org rule. Usual: none; may count toward «Решение откладывается» only through the postponement rule (Q24-3).', NULL, NULL)
ON CONFLICT DO NOTHING;
