INSERT INTO "signal_category" ("code", "pack_code", "block_code", "family", "label_ru", "definition_ru", "boundary_ru", "cues_prompt_ru", "synonyms_ru", "anti_cues_ru", "example_ru", "counter_example_ru", "card_note_ru", "weight", "score_rule", "class", "class_by_relation", "kind", "effort", "carries_amount", "asks_us", "inbound_only", "emitted_by", "stage", "display_profile", "recipient_role", "closes_codes", "date_gate", "relevance_days", "trigger_rule", "note_ru", "retired_at", "successor_code") VALUES
  ('MEETING_KEY_MISSING', 'base', 'F', 'meeting', 'На регулярной встрече нет ключевого участника', 'Известный основной контакт клиента больше не в списке участников регулярной встречи. Нужен источник календаря; припаркован.', 'Человек сообщил об уходе — CONTACT_LEAVING. Человек в отпуске с автоответом — CONTACT_OOO. Разовое отсутствие на одной встрече без повтора — нет сигнала.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, 'Ежемесячная встреча с сетью: закупщица была на всех встречах до октября, в ноябре и декабре её нет в приглашении.', '', 'Укажи, кто пропал из встреч и с какого времени; шаг — уточнить у клиента, кто теперь отвечает за вопрос.', 5, 'fixed', 'risk', false, 'derived', 'medium', false, false, false, 'process', 'parked', NULL, 'account', '{}'::text[], NULL, NULL, '{"ru":"RU: у клиента есть регулярная встреча в календаре; основной контакт (по CRM) был участником прошлых встреч и отсутствует в списке участников последних двух встреч подряд; нет CONTACT_OOO на эти даты. EN: a recurring calendar meeting exists; the CRM main contact attended before and is missing from the last two consecutive attendee lists; no CONTACT_OOO for those dates."}'::jsonb, 'Closed by: the main contact attends again
Deal effect: per org rule. Usual: none.', NULL, NULL),
  ('CONTACT_LEAVING', 'base', 'G', 'contact', 'Контакт уходит из компании', 'Контакт сообщает, что уходит из компании клиента (прощальное письмо, «последний рабочий день»), или клиент объявляет об этом.', 'Отпуск, больничный, командировка с возвратом — CONTACT_OOO. Смена роли внутри той же компании — не уход (может быть CONTACT_NEW_DECISION_MAKER для нового человека). Автоответ «больше не работает, пишите на» без прощального письма — этот код (это и есть объявление). Наш сотрудник уходит — блок J, не этот код.', ARRAY['я больше не работаю в компании', 'последний рабочий день', 'покидаю компанию', 'ухожу из компании', 'по всем вопросам теперь обращайтесь к', 'перехожу в другую компанию', 'больше не сотрудник', 'новый сомелье']::text[], '{"business":["сообщаю, что с 15.11 я завершаю работу в компании","это мой последний рабочий день","благодарю за сотрудничество, дальше ваш вопрос ведёт","Иванова И. И. больше не является сотрудником компании","уволилась, письма не читаются"],"chat":["я ухожу, всем спасибо","я больше тут не работаю","теперь пишите Свете, я ушла","«у нас новый сомелье, старый ушёл» (дистрибуция)","«новый закупщик вместо меня» (дистрибуция)"],"terms":["увольнение","последний день","передача дел","преемник"],"patterns":["больше не работаю / не является сотрудником","«последний рабочий день» + дата","«по всем вопросам обращайтесь к» + новый человек (вместе с уходом)"]}'::jsonb, '[{"text":"«в отпуске до 20.11, по срочным — к коллеге»","code":"CONTACT_OOO"},{"text":"«перешла в отдел маркетинга, закупки теперь ведёт Олег»","code":"CONTACT_NEW_DECISION_MAKER"},{"text":"«наш менеджер уходит» (письмо коллеги)","code":null}]'::jsonb, '«Коллеги, 22 ноября мой последний рабочий день в компании, дела по закупкам вина передаю Ольге Смирновой.»', '«Я в отпуске до 25 ноября, по срочным вопросам — Ольга Смирнова» → временное отсутствие, CONTACT_OOO.', 'Укажи, кто уходит, когда и кому передаёт дела; шаги — поблагодарить, познакомиться с преемником, подтвердить текущие договорённости.', 7, 'fixed', 'risk', false, 'event', 'medium', false, false, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Date gate: — (the last working day goes to `facts.deadlines`, owner = them)
Relevance window: until the last working day, then default
Relations: — in v204. Agency: the old company side is judged with `ACCOUNT_SPONSOR_SUPPORT_LOST`; the move itself is `PROSPECT_CONTACT_MOVED` (Q24-2).
Deal effect: per org rule. IN4COM: risk trigger **«Смена закупщика / сомелье»** — only when the person is linked to the deal (`deal_contact`) and no new contact is confirmed. Agency: «Потеря ключевого контакта» (Q24-2).', NULL, NULL),
  ('CONTACT_NEW_DECISION_MAKER', 'base', 'G', 'contact', 'Появился новый человек, принимающий решения (ЛПР)', 'В общении впервые появляется человек со стороны клиента, который принимает решения или утверждает закупку: новый директор, руководитель закупок, управляющий, шеф-сомелье, бренд-менеджер сети.', 'Новый рядовой контакт (менеджер, бухгалтер, кладовщик) — CONTACT_NEW_KNOWN_ORG. Новый участник только на встрече — MEETING_NEW_STAKEHOLDER (может быть вместе). Смена руководства из новостей без появления человека в переписке — блок H. Уход прежнего ЛПР — CONTACT_LEAVING.', ARRAY['я новый директор по закупкам', 'новый закупщик', 'новый сомелье', 'теперь решения по ассортименту принимаю я', 'вступил в должность', 'назначена руководителем', 'будет утверждать закупки', 'новый управляющий']::text[], '{"business":["представляюсь: с 01.11 я назначен коммерческим директором","теперь вопросы закупки алкоголя курирую я","прошу направлять предложения на моё имя","новый руководитель отдела закупок — Петров П. П.","согласование договоров теперь у финансового директора"],"chat":["«привет, я новый шеф-сомелье» (дистрибуция)","«теперь карту согласовываю я» (дистрибуция)","я тут новый управляющий, давайте знакомиться","закупки теперь на мне"],"terms":["ЛПР","ГД","КД","ФД","закупщик","байер","категорийный менеджер","шеф-сомелье","бар-менеджер"],"patterns":["«я новый / назначен(а)» + руководящая роль","«теперь решения / согласование» + «за мной / у меня»"]}'::jsonb, '[{"text":"«по накладным теперь пишите Анне из бухгалтерии»","code":"CONTACT_NEW_KNOWN_ORG"},{"text":"«у компании новый CEO» (новость)","code":null},{"text":"«на встрече будет наш новый директор»","code":"MEETING_NEW_STAKEHOLDER"}]'::jsonb, '«Добрый день! Я новый директор по закупкам сети, с декабря все вопросы по винному ассортименту согласовываются через меня.»', '«Теперь накладные и акты присылайте нашему новому бухгалтеру» → не ЛПР, CONTACT_NEW_KNOWN_ORG.', 'Укажи нового ЛПР и его зону решений; шаги — назначить знакомство, рассказать о текущих условиях, узнать его приоритеты.', 6, 'fixed', 'chance', false, 'event', 'medium', false, false, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Relations: — in v204. Agency: risk «Смена руководства клиента» (Maslov risk 5).
Deal effect: per org rule. IN4COM: risk trigger **«Смена закупщика / сомелье»** (person linked to the deal; clears when the new person confirms the current terms); otherwise in-stage context (people).', NULL, NULL),
  ('CONTACT_NEW_KNOWN_ORG', 'base', 'G', 'contact', 'Новый контакт у действующего клиента', 'У существующего клиента появляется новый контактный человек: его представляют или он сам пишет впервые (менеджер, бухгалтер, логист, новый сотрудник закупок).', 'Новый человек с правом решения — CONTACT_NEW_DECISION_MAKER. Человек из новой компании (не клиента) — не этот код. Временный заместитель из автоответа — CONTACT_OOO. Технические адреса (noreply, рассылки) — нет сигнала.', ARRAY['теперь по заказам пишите', 'познакомьтесь, это наш новый менеджер', 'добавляю в переписку коллегу', 'я новый сотрудник отдела закупок', 'буду вести ваши поставки', 'по документам теперь отвечает', 'пишу вам впервые', 'новый закупщик']::text[], '{"business":["прошу направлять заявки на адрес нового сотрудника","представляю нового менеджера по работе с поставщиками","с сегодняшнего дня ваш контакт по логистике — Сидорова А. В.","добавляю в копию нашего бухгалтера"],"chat":["добавила в чат Катю, она теперь заказы делает","«я новенькая, буду заказывать вино» (дистрибуция)","пишите теперь мне по накладным"],"terms":["контактное лицо","ответственный","новый сотрудник","в копии"],"patterns":["«теперь по» + вопрос + «пишите / обращайтесь к» + человек","«знакомьтесь / представляю» + новый сотрудник"]}'::jsonb, '[{"text":"«я новый коммерческий директор»","code":"CONTACT_NEW_DECISION_MAKER"},{"text":"«в отпуске, замещает Ирина»","code":"CONTACT_OOO"},{"text":"новый адрес в копии без представления","code":null}]'::jsonb, '«Знакомьтесь, это Екатерина, наш новый менеджер по закупкам — заявки на поставку теперь будет присылать она.»', '«Я в отпуске, по срочным вопросам — Екатерина» → временный заместитель, CONTACT_OOO.', 'Укажи нового контакта и его участок; шаги — добавить контакт в CRM, поприветствовать, отправить нужные контакты с нашей стороны.', 4, 'fixed', 'chance', false, 'event', 'medium', false, false, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule. Usual: in-stage context (people).', NULL, NULL),
  ('CONTACT_OOO', 'base', 'G', 'contact', 'Контакт отсутствует и указал заместителя', 'Автоответ или сообщение контакта о временном отсутствии (отпуск, больничный, командировка), обычно с датой возвращения и заместителем.', 'Уход из компании — CONTACT_LEAVING. Новый постоянный контакт — CONTACT_NEW_KNOWN_ORG. Наш сотрудник в отпуске — не этот код. Автоответ «письмо получено, ответим в течение дня» без отсутствия — нет сигнала.', ARRAY['нахожусь в отпуске до', 'буду на связи с', 'по срочным вопросам обращайтесь к', 'нет в офисе', 'на больничном', 'в командировке до', 'автоответ', 'вернусь']::text[], '{"business":["я нахожусь в отпуске с 10.11 по 24.11, доступ к почте ограничен","по срочным вопросам прошу обращаться к","в настоящее время отсутствую в офисе","на период моего отсутствия меня замещает","Автоматический ответ: Нет на месте"],"chat":["я в отпуске до понедельника, пишите Оле","на больничном, отвечу позже","я в командировке, по заказам — к Диме","до 20-го не на связи"],"terms":["автоответ","OOO","Out of Office","замещает","и. о.","ВРИО"],"patterns":["«в отпуске / на больничном / в командировке» + «до» + дата","«по срочным вопросам» + «к» + человек","тема «Автоответ», «Автоматический ответ», «Нет на месте»"]}'::jsonb, '[{"text":"«я больше не работаю в компании»","code":"CONTACT_LEAVING"},{"text":"«ваше обращение зарегистрировано, ответим в течение 24 часов»","code":null},{"text":"«наш менеджер в отпуске» (наше письмо)","code":null}]'::jsonb, '«Я в отпуске до 24 ноября, по срочным вопросам закупок обращайтесь к Ольге Смирновой, o.smirnova@restoran.ru.»', '«Спасибо за письмо, ваше обращение принято в работу» → автоответ без отсутствия.', 'Укажи дату возврата и заместителя; шаг — срочные вопросы вести через заместителя, остальные — после возврата.', 4, 'fixed', 'risk', false, 'event', 'medium', false, false, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Emitted by: both (mostly the deterministic out-of-office detector, spec §5.2 gate 6; the LLM only for free-text notices)
Closed by: — (expires on the return date)
Date gate: — (return date and deputy go to facts)
Relevance window: until the return date
Deal effect: per org rule. Usual: none.', NULL, NULL),
  ('SIGNAL_INSOLVENCY', 'base', 'H', 'market', 'Кризис или неплатёжеспособность компании', 'В отношении компании начата процедура банкротства (наблюдение, конкурсное производство, внешнее управление, реструктуризация долгов), принято решение о её ликвидации, или компания сама сообщает о прекращении платежей, блокировке счетов, неспособности рассчитаться с поставщиками. Сюда же относится опубликованное на Федресурсе уведомление кредитора о намерении подать заявление о банкротстве этой компании.', 'Негативная публикация без признаков неплатёжеспособности → SIGNAL_NEGATIVE_PRESS. Просрочка одного счёта или обещание оплатить позже → INVOICE_OVERDUE / PAYMENT_PROMISE. Просьба об отсрочке или рассрочке → PAYMENT_TERMS_REQUEST (distribution). Новость о том, что покупатель выкупает или спасает бизнес банкрота → SIGNAL_MERGER для покупателя, банкротство — только контекст. Реорганизация в форме присоединения или слияния → SIGNAL_MERGER. Закрытие отдельных точек без признаков неплатёжеспособности → SIGNAL_DOWNSIZING. Банкротство компании, которая не наш клиент и не связана с ним, — нет сигнала.', ARRAY['введена процедура наблюдения', 'признан(а) банкротом', 'открыто конкурсное производство', 'заявление о признании банкротом', 'находится в стадии ликвидации', 'приостановлены операции по счетам', 'временно прекращаем платежи', 'реструктуризация задолженности']::text[], '{"business":["вынуждены временно приостановить расчёты с поставщиками","наши расчётные счета заблокированы","в отношении общества введена процедура наблюдения","назначен временный управляющий, все вопросы по оплате направляйте ему","компания находится в процедуре банкротства","принято решение о добровольной ликвидации общества","требования кредиторов принимаются в порядке, установленном законом о банкротстве","не имеем возможности погасить задолженность в полном объёме"],"news":["арбитражный суд ввёл процедуру наблюдения","признано несостоятельным (банкротом)","открыто конкурсное производство сроком на шесть месяцев","введено внешнее управление","утверждён конкурсный управляющий","опубликовано уведомление о намерении обратиться в суд с заявлением о банкротстве","юридическое лицо находится в процессе ликвидации","ФНС приостановила операции по счетам компании","кредиторы подали иск о банкротстве","сеть объявила о реструктуризации долга перед банками"],"chat":["у них блок по счетам","они банкротятся","слышал, «Северный ветер» подали на банкротство","там уже конкурсный управляющий сидит","денег нет, платить не будут","контора ликвидируется"],"terms":["127-ФЗ","Федресурс","ЕФРСБ","КАД","«ВУ» (временный управляющий)","«КУ» (конкурсный управляющий)","«РТК» (реестр требований кредиторов)","мораторий","санация","субсидиарка"],"patterns":["«в отношении [компании] введена / открыта [процедура]», «[компания] признана банкротом», «подано заявление о банкротстве [компании]», «[компания] находится в стадии ликвидации»"]}'::jsonb, '[{"text":"«группа выкупила рестораны у конкурсного управляющего и сохранит их»","code":"SIGNAL_MERGER"},{"text":"«оплатим на следующей неделе, задержка с платежом»","code":"INVOICE_OVERDUE"},{"text":"«просим отсрочку 60 дней»","code":"PAYMENT_TERMS_REQUEST"},{"text":"«закрываем две точки в ТЦ»","code":"SIGNAL_DOWNSIZING"},{"text":"«реорганизация в форме присоединения к АО»","code":"SIGNAL_MERGER"},{"text":"«в ЕГРЮЛ запись о недостоверности адреса»","code":null},{"text":"«выручка упала на 20 %»","code":"SIGNAL_RESULTS_NEGATIVE"}]'::jsonb, '«Сообщаем, что определением Арбитражного суда г. Москвы от 05.11.2026 в отношении ООО «Северный ветер» введена процедура наблюдения, временным управляющим утверждён Иванов И. И.»', '«Ресторанная группа «Гастроном Плюс» выкупила бизнес «Северного ветра» у конкурсного управляющего и сохранит все рестораны» → это SIGNAL_MERGER для покупателя; банкротство здесь контекст.', 'Пишите от роли: ответственному за клиента вместе с финансовой службой — остановить отгрузки с отсрочкой, сверить дебиторскую задолженность и решить, заявлять ли требование кредитора; новых условий клиенту не обещать.', 9, 'fixed', 'risk', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Emitted by: both (parser on mail / chat; `press` profile on web search, phase 11)
Relations: leads over `SIGNAL_NEGATIVE_PRESS`; outranked by `SIGNAL_MERGER` (a rescue or takeover out of the insolvency)
Deal effect: per org rule; usual: risk trigger «Клиент в процедуре банкротства / ликвидации» on every open deal of this client (no stage move)', NULL, NULL),
  ('SIGNAL_DOWNSIZING', 'base', 'H', 'market', 'Закрытие площадок или сокращение штата', 'Компания закрывает свои точки, магазины, рестораны, филиалы или производство, уходит из региона или сокращает персонал. Речь о действующей компании, которая сжимает бизнес.', 'Процедура банкротства или ликвидации → SIGNAL_INSOLVENCY. Клиент убирает наши позиции из меню или ассортимента → DELISTING_RISK (distribution). Временное закрытие на ремонт, санитарный день или сезонная пауза с датой открытия — нет сигнала. Закрытие за рубежом, вне регионов из профиля организации, — нет сигнала. Перевод точки по новому адресу → SIGNAL_EXPANSION только если открывается новая площадка; иначе нет сигнала.', ARRAY['закрывает рестораны', 'закрытие точки', 'сокращение штата', 'оптимизация персонала', 'уходит из региона', 'сворачивает сеть', 'закрываемся с 1-го числа', 'массовые увольнения']::text[], '{"business":["с 01.12 ресторан на Тверской прекращает работу","мы закрываем два магазина из пяти","в связи с оптимизацией сети точка закрывается","просим не планировать поставки на адрес Покровка, 12 после 30.11","у нас сокращение, отдел закупок урезали вдвое","прекращаем деятельность в Санкт-Петербурге"],"news":["сеть закроет 15 магазинов до конца года","ресторанная группа сократит 300 сотрудников","компания уходит из регионов","оптимизирует розничную сеть","закрыла завод в Калужской области","сокращает штат на 10 %"],"chat":["мы закрываемся","бар закрываем, аренду не потянули","точку на Белорусской закрыли","у них всех закупщиков сократили","сворачиваются потихоньку"],"terms":["оптимизация","реструктуризация сети","«закрытие ТТ» (торговой точки)","сокращение ФОТ"],"patterns":["«[компания] закрывает / закроет [N точек]», «прекращает работу [точка / регион]», «сокращает [N сотрудников / %]»"]}'::jsonb, '[{"text":"«закрыты на ремонт до 15.01»","code":null},{"text":"«вводим процедуру банкротства»","code":"SIGNAL_INSOLVENCY"},{"text":"«убираем ваше вино из карты»","code":"DELISTING_RISK"},{"text":"«переезжаем в новое помещение, откроемся 01.02»","code":"SIGNAL_EXPANSION"},{"text":"«закрываем магазины в Казахстане»","code":null}]'::jsonb, '«Коллеги, с 1 декабря закрываем ресторан на Покровке, поставки туда больше не планируйте.»', '«Ресторан закрыт на санитарный день, принять поставку не сможем, перенесите на завтра» → это не сокращение бизнеса.', 'Назовите, что закрывается и с какой даты; шаг — связаться с закупщиком клиента, узнать, какие точки продолжают работу и что будет с текущими заказами и долгом.', 6, 'fixed', 'risk', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Emitted by: both; in the `press` profile only when the company is our client
Deal effect: per org rule; usual: risk trigger on open deals tied to the closed venues / sites (no stage move)', NULL, NULL),
  ('SIGNAL_AGENCY_CHANGE', 'base', 'H', 'market', 'Смена рекламного или PR-агентства', 'Рекламодатель пересматривает или переводит свой рекламный, медийный или PR-бюджет: объявляет тендер на агентство, расстаётся с текущим агентством или называет новое агентство по итогам тендера. Если в тексте названо агентство-победитель, дополнительно ставится SIGNAL_ACCOUNT_WIN.', 'Новая кампания того же агентства → SIGNAL_CAMPAIGN_PLANNED / SIGNAL_AD_ACTIVITY. Первое назначение агентства без тендера и без прежнего агентства → только SIGNAL_ACCOUNT_WIN. Агентство-конкурент потеряло рекламодателя, который не наш клиент → COMPETITOR_LOST_CLIENT. Смена агентства по трекингу или веб-аналитике → SIGNAL_TRACKING_VENDOR_CHANGE. Клиент меняет поставщика товаров (вина, напитков) — это не агентство: SIGNAL_COMPETITOR или нет сигнала.', ARRAY['объявил тендер на креативное обслуживание', 'тендер на медиаобслуживание', 'ищет новое агентство', 'прекращает сотрудничество с агентством', 'сменил агентство', 'по итогам тендера выбрал', 'бюджет переходит к', 'пересматривает пул агентств']::text[], '{"business":["мы объявляем тендер на рекламное обслуживание на 2027 год","с текущим агентством контракт не продлеваем","приглашаем к участию в тендере на SMM","пересматриваем пул подрядчиков по коммуникациям","агентство «Альфа Медиа» больше не ведёт наш бренд"],"news":["бренд объявил креативный тендер","тендер на медийное обслуживание выиграло агентство","бюджет бренда перешёл к агентству","компания провела тендер и сменила PR-агентство","бренд расстался с агентством после пяти лет сотрудничества","рекламодатель пересматривает пул агентств"],"chat":["они агентство меняют","у них тендер на креатив","старое агентство слили","ищут новое агентство под digital"],"terms":["тендер","пул агентств","«AOR» (agency of record)","медиабюджет","креатив","SMM","PR-подрядчик","RFP"],"patterns":["«[бренд] объявил тендер на [вид обслуживания]», «[бренд] сменил [агентство X] на [агентство Y]», «[агентство] больше не обслуживает [бренд]»"]}'::jsonb, '[{"text":"«агентство «Альфа Медиа» запускает новую кампанию бренда»","code":"SIGNAL_CAMPAIGN_PLANNED"},{"text":"«бренд впервые выбрал агентство»","code":"SIGNAL_ACCOUNT_WIN"},{"text":"«сменили подрядчика по Яндекс Метрике и тегам»","code":"SIGNAL_TRACKING_VENDOR_CHANGE"},{"text":"«будем брать вино у другого дистрибьютора»","code":"SIGNAL_COMPETITOR"}]'::jsonb, '«Бренд «Гастроном Плюс» объявил тендер на креативное и медийное обслуживание: контракт с агентством «Альфа Медиа» заканчивается в декабре.»', '«Агентство «Альфа Медиа» представило новую сезонную кампанию бренда «Гастроном Плюс»» → это кампания действующего агентства, не смена.', 'Пишите для той стороны, которая наш клиент: рекламодателю — узнать у контакта по маркетингу, меняет ли смена агентства наш план; агентству-клиенту — что смена значит для нашего сотрудничества; действие всегда наше, не шаг рекламодателя из статьи.', 6, 'fixed', 'risk', true, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Relations: leads over `SIGNAL_AD_ACTIVITY`; both with `SIGNAL_ACCOUNT_WIN`; when the losing agency is our competitor and the advertiser is not our client → `COMPETITOR_LOST_CLIENT` instead
Deal effect: per org rule; usual: none (agency pack: risk trigger when the advertiser is our client)', NULL, NULL),
  ('SIGNAL_NEGATIVE_PRESS', 'base', 'H', 'market', 'Репутационный кризис компании', 'О компании выходят критические публикации, волна негатива в соцсетях, сообщения об отзыве продукции или о предупреждении надзорного органа. Компания при этом продолжает работать.', 'Банкротство, ликвидация, блокировка счетов → SIGNAL_INSOLVENCY. Опубликованные финансовые потери с цифрой и периодом → SIGNAL_RESULTS_NEGATIVE. Закрытие точек → SIGNAL_DOWNSIZING. Жалоба клиента на наш товар или сервис → блок E (COMPLAINT_*). Негатив о конкуренте → COMPETITOR_NEGATIVE_PRESS, о партнёре → PARTNER_NEGATIVE_PRESS.', ARRAY['скандал', 'волна негатива', 'отзыв партии', 'Роспотребнадзор выявил нарушения', 'проверка выявила', 'бойкот', 'обвиняют в', 'предписание надзорного органа']::text[], '{"business":["у нас сейчас непростая ситуация в соцсетях","по сети пошла волна отзывов после отравления","мы получили предписание Роспотребнадзора","партия отозвана из продажи по решению надзора"],"news":["ресторан оказался в центре скандала","Роспотребнадзор приостановил работу заведения","сеть обвинили в продаже контрафакта","покупатели объявили бойкот","бренд отзывает партию продукции","в сети разгорелся скандал после поста посетителя","прокуратура начала проверку"],"chat":["у них жесть в отзывах","их сейчас в телеге полощут","хайп из-за отравления","Роспотреб к ним пришёл"],"terms":["Роспотребнадзор","«РАР» (Росалкогольтабакконтроль)","предписание","отзыв продукции","контрафакт","фальсификат","административное дело"],"patterns":["«[компания] оказалась в центре [скандала]», «[надзор] выявил нарушения у [компании]», «[компания] отзывает [продукцию]»"]}'::jsonb, '[{"text":"«введено конкурсное производство»","code":"SIGNAL_INSOLVENCY"},{"text":"«убыток за 9 месяцев вырос на 30 %»","code":"SIGNAL_RESULTS_NEGATIVE"},{"text":"«гость пожаловался, что ваше вино с пробкой»","code":"COMPLAINT_QUALITY"},{"text":"«конкурент попал в скандал»","code":"COMPETITOR_NEGATIVE_PRESS"}]'::jsonb, '«Роспотребнадзор приостановил работу бара «Винотека 24» на Арбате на 30 суток после проверки.»', '«Бар «Винотека 24» закрывается, аренду не продлили» → это SIGNAL_DOWNSIZING, не репутационный кризис.', 'Без использования кризиса в продажах: предложить ответственному за клиента связаться с контактом клиента по роли, узнать, как кризис влияет на закупки и что клиент планирует, и только потом обсуждать поставки.', 6, 'fixed', 'chance', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Relations: `SIGNAL_INSOLVENCY` leads over it
Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_NEW_MARKETING_LEAD', 'base', 'H', 'market', 'Новый руководитель маркетинга или бренда', 'В компании новый руководитель маркетинга, бренда или коммуникаций — человек, который решает о бюджете в нашей области. Для дистрибьютора к этой роли относятся также руководитель категории напитков, бренд-шеф бара или главный сомелье сети, если в тексте он решает о закупках.', 'Новый генеральный, финансовый, коммерческий директор → SIGNAL_C_LEVEL_CHANGE. Новый человек пишет нам сам как контакт → CONTACT_NEW_DECISION_MAKER (блок G). Назначение больше 6 месяцев назад («работает с ноября прошлого года») — нет сигнала. Уход руководителя маркетинга без названного преемника, который пишет нам сам → CONTACT_LEAVING.', ARRAY['назначен директором по маркетингу', 'новый CMO', 'возглавил маркетинг', 'новый бренд-директор', 'назначена руководителем направления коммуникаций', 'пришёл новый маркетолог', 'новый шеф-сомелье сети', 'перешёл на позицию директора по маркетингу']::text[], '{"business":["сообщаем, что с 01.11 директором по маркетингу назначена Анна Смирнова","теперь маркетинг курирует новый руководитель","по вопросам продвижения обращайтесь к новому бренд-менеджеру"],"news":["директором по маркетингу компании назначен","новым CMO сети стала","возглавила департамент маркетинга и коммуникаций","на позицию бренд-директора пришёл","ресторанная группа назначила нового директора по маркетингу","главным сомелье группы стал"],"chat":["у них новый маркетолог","маркетинг теперь ведёт новая девушка","пришёл новый CMO, всё пересматривает","поменялся шеф-сомелье"],"terms":["CMO","бренд-директор","директор по маркетингу","руководитель PR","шеф-сомелье","бренд-шеф бара"],"patterns":["«[ФИО] назначен(а) [директором по маркетингу]», «на должность [CMO] пришёл / пришла», «[ФИО] возглавил(а) [маркетинг]»"]}'::jsonb, '[{"text":"«назначен новый генеральный директор»","code":"SIGNAL_C_LEVEL_CHANGE"},{"text":"«я новый закупщик, теперь заказы через меня»","code":"CONTACT_NEW_DECISION_MAKER"},{"text":"«руководит маркетингом с 2024 года»","code":null},{"text":"«уважаемые партнёры, я покидаю компанию»","code":"CONTACT_LEAVING"}]'::jsonb, '«Директором по маркетингу ресторанной группы «Северный ветер» назначена Анна Смирнова, ранее работавшая в сети «Винотека 24».»', '«Анна Смирнова, директор по маркетингу «Северного ветра» с 2023 года, рассказала о планах на сезон» → назначение старое, сигнала нет.', 'Называйте роль, не имя («новый директор по маркетингу клиента»); для активного клиента — риск: договориться о ранней встрече и узнать планы; для неклиента — шанс представиться до выбора партнёров.', 5, 'fixed', 'chance', true, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Date gate: — (prompt rule: the change took effect no more than 6 months before the item date; a vague date counts as 3–6 months; no date = new)
Relations: leads over `SIGNAL_C_LEVEL_CHANGE` (for a marketing-head change)
Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_MERGER', 'base', 'H', 'market', 'Приобретение или слияние компаний', 'Меняется контроль над компанией: покупка, слияние, присоединение, переход контрольного пакета или доли больше 50 %. Сюда же — выкуп бренда или бизнеса из банкротства (спасение): код ставится покупателю, банкротство остаётся контекстом.', 'Доля без смены контроля, инвестиционный раунд → SIGNAL_FUNDING. Совместный проект, дистрибуторское соглашение без смены владельца → SIGNAL_PARTNERSHIP. Собственное банкротство компании, где покупатель только упомянут как возможный → SIGNAL_INSOLVENCY. Покупка оборудования, складов, транспорта → SIGNAL_OPERATIONS_INVESTMENT.', ARRAY['приобрела', 'выкупила', 'закрыла сделку по покупке', 'слияние', 'присоединение', 'контрольный пакет', 'стала владельцем', 'ФАС одобрила сделку']::text[], '{"business":["сообщаем, что с 01.12 общество вошло в состав группы «Гастроном Плюс»","у нас сменился собственник","в связи с реорганизацией в форме присоединения просим перезаключить договор","все договоры переходят к новому юрлицу"],"news":["группа приобрела сеть ресторанов","выкупила 100 % долей","получила контроль над","ФАС одобрила ходатайство о покупке","компании объявили о слиянии","реорганизация в форме присоединения","новым владельцем стал","выкупила бренд у конкурсного управляющего","сделка по спасению сети закрыта"],"chat":["их купили","теперь они под «Гастроном Плюс»","собственник поменялся","их поглотили"],"terms":["M&A","ФАС","контрольный пакет","мажоритарий","присоединение","правопреемник","новое юрлицо"],"patterns":["«[покупатель] приобрёл / выкупил [компанию / долю N %]», «[компания] вошла в состав [группы]», «сделка по покупке [компании] закрыта»"]}'::jsonb, '[{"text":"«фонд вложил 500 млн за миноритарную долю»","code":"SIGNAL_FUNDING"},{"text":"«подписали соглашение о совместном продвижении»","code":"SIGNAL_PARTNERSHIP"},{"text":"«введена процедура наблюдения, ищем инвестора»","code":"SIGNAL_INSOLVENCY"},{"text":"«купили новый склад в Подольске»","code":"SIGNAL_OPERATIONS_INVESTMENT"}]'::jsonb, '«Холдинг «Гастроном Плюс» закрыл сделку по покупке 100 % сети винных баров «Винотека 24».»', '«Холдинг «Гастроном Плюс» и «Винотека 24» запускают совместную программу лояльности» → это партнёрство, контроль не меняется.', 'Пишите со стороны нашего клиента и назовите другую сторону; клиента купили — узнать у контакта, меняются ли закупки, поставщики и договор; клиент купил — шанс зайти в новый бизнес; один материал о покупателе и купленном — одна карточка.', 5, 'fixed', 'risk', true, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Relations: outranks `SIGNAL_INSOLVENCY`; leads over `SIGNAL_PARTNERSHIP`; leads over `SIGNAL_FUNDING`
Deal effect: per org rule; usual: risk trigger «Смена собственника клиента» on open deals when our client is bought', NULL, NULL),
  ('SIGNAL_COMPETITOR', 'base', 'H', 'competitor', 'Активность конкурента у клиента', 'У нашего клиента появляется конкурент: клиент говорит, что работает или начинает работать с другим поставщиком, рассматривает его продукцию, конкурент проводит у клиента дегустацию или презентацию. Без связи с конкретным клиентом это не сигнал.', 'Жалоба на цену со ссылкой на более дешёвое предложение → COMPLAINT_PRICE. Клиент выводит наши позиции → DELISTING_RISK (distribution). Новость о конкуренте без связи с нашим клиентом → блок L (COMPETITOR_*). Отказ от нашего предложения с выбором другого поставщика → SALES_OFFER_DECLINED (если отказ явный, этот код можно поставить вторым).', ARRAY['работаем с другим поставщиком', 'нам предложил другой дистрибьютор', 'взяли у другого поставщика', 'рассматриваем предложение конкурента', 'у нас была дегустация от', 'перешли на другого импортёра', 'часть позиций берём у', 'к нам приходил представитель']::text[], '{"business":["по Бургундии мы теперь работаем с другим поставщиком","нам поступило предложение от другого дистрибьютора, рассматриваем","часть позиций переводим к другому импортёру","на следующей неделе у нас дегустация от «Винного Альянса»","сравниваем ваше портфолио с альтернативным"],"chat":["нам «Винный Альянс» тоже предлагал","игристое теперь берём у других","к нам ихний торговый приходил","конкуренты зашли с дегустацией"],"terms":["другой дистрибьютор","импортёр","альтернативное предложение","торговый представитель","дегустация","портфолио"],"patterns":["«работаем / начали работать с [другим поставщиком]», «[конкурент] предложил нам [позиции / условия]», «переводим [позиции] к [конкуренту]»"]}'::jsonb, '[{"text":"«у другого поставщика на 15 % дешевле, дайте скидку»","code":"COMPLAINT_PRICE"},{"text":"«убираем ваши вина из карты»","code":"DELISTING_RISK"},{"text":"««Винный Альянс» открыл склад в Казани» (без связи с клиентом)","code":"COMPETITOR_EXPANSION"},{"text":"«спасибо, выбрали другого поставщика»","code":"SALES_OFFER_DECLINED"}]'::jsonb, '«Белые вина Луары с января будем брать у «Винного Альянса», они дали лучшую логистику.»', '««Винный Альянс» стал официальным импортёром нового бренда» → новость о конкуренте без связи с нашим клиентом, это блок L.', 'Пишите о клиенте, у которого появился конкурент, а не о самом конкуренте; шаг — узнать у закупщика, какие позиции и почему уходят, и что мы можем предложить до следующей закупки.', 5, 'fixed', 'risk', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Emitted by: both; in the `press` profile only when the company is our client
Deal effect: per org rule; usual: risk trigger «Конкурент у клиента» on an open deal of this client', NULL, NULL),
  ('SIGNAL_SPEND_UP', 'base', 'H', 'market', 'Рост релевантных расходов', 'Расходы клиента в категории, важной для нас, заметно растут — независимо от его бюджета у нас (агентство: рекламные расходы по данным мониторинга; дистрибьютор: закупки категории, если есть внешний источник).', 'Рост закупок у нас → ACCOUNT_REVENUE_GROWTH_YOY. Клиент сам объявляет об увеличении бюджета у нас → SALES_BUDGET_INCREASE. Перераспределение между каналами при прежней сумме → SIGNAL_CHANNEL_SHIFT. Одна крупная кампания → SIGNAL_AD_ACTIVITY.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, '«Рекламные расходы «Гастроном Плюс» в III квартале 2026: 48 млн ₽ против 35 млн ₽ годом ранее (+37 %).»', '«Клиент купил у нас на 30 % больше, чем в прошлом году» → это ACCOUNT_REVENUE_GROWTH_YOY.', 'Назовите категорию и рост в процентах; шаг — узнать у контакта клиента, что стоит за ростом и есть ли место для нас.', 5, 'fixed', 'chance', false, 'event', 'medium', false, false, false, 'process', 'onHold', NULL, 'relationship', '{}'::text[], NULL, NULL, '{"ru":"Данные — внешний поток расходов клиента по категории (агентство: рекламный мониторинг; дистрибьютор: источника пока нет). Окно — последний полный квартал. База — тот же квартал прошлого года. Минимум данных — 4 квартала истории и сумма базы не ниже порога организации. Порог — рост ≥ 20 %. Запуск — ежемесячно. Повтор — не раньше 90 дней на клиента и код; смена направления сразу даёт новую карточку. Мало данных — сигнала нет.","en":"Data — an external feed of the client''s spend per category (agency: ad monitoring; distributor: no source yet). Window — last full quarter. Baseline — same quarter one year earlier. Minimum data — 4 quarters of history and a baseline above the org minimum. Threshold — growth ≥ 20 %. Run — monthly. Cooldown — 90 days per client + code; a change of direction makes a new card at once. Too little data — no instance."}'::jsonb, 'Display profile: from weight (D4); trend ceiling D4
Profile (summary): D4 (trend ceiling)
Date gate: — (trend rule below)
Relevance window: trend cooldown 90 days per client + code (`cards.trendCooldownDays`); a change of direction makes a new card at once
Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_SPEND_DOWN', 'base', 'H', 'market', 'Снижение релевантных расходов', 'Расходы клиента в категории, важной для нас, заметно падают — независимо от его бюджета у нас.', 'Снижение закупок у нас → ACCOUNT_REVENUE_DECLINE_YOY. Клиент сам объявляет о сокращении бюджета у нас → SALES_BUDGET_CUT. Перенос бюджета между каналами при прежней сумме → SIGNAL_CHANNEL_SHIFT.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, '«Рекламные расходы «Винотека 24» в III квартале 2026: 6 млн ₽ против 11 млн ₽ годом ранее (−45 %).»', '«Клиент перенёс бюджет с наружной рекламы в digital, общая сумма та же» → это SIGNAL_CHANNEL_SHIFT.', 'Назовите категорию и падение в процентах; шаг — до следующего плана узнать у контакта клиента причину снижения.', 5, 'fixed', 'risk', false, 'event', 'medium', false, false, false, 'process', 'onHold', NULL, 'relationship', '{}'::text[], NULL, NULL, '{"ru":"Те же данные, окно и база, что у `SIGNAL_SPEND_UP`. Порог — снижение ≥ 20 %. Минимум данных — 4 квартала истории. Запуск — ежемесячно. Повтор — не раньше 90 дней на клиента и код. Если в том же периоде у клиента сработал `SIGNAL_CHANNEL_SHIFT`, ведёт он.","en":"Same data, window and baseline as `SIGNAL_SPEND_UP`. Threshold — decline ≥ 20 %. Minimum data — 4 quarters. Run — monthly. Cooldown — 90 days per client + code. When `SIGNAL_CHANNEL_SHIFT` fires for the same client and period, it leads."}'::jsonb, 'Display profile: from weight (D4); trend ceiling D4
Profile (summary): D4 (trend ceiling)
Date gate: — (trend rule below)
Relevance window: trend cooldown 90 days per client + code; a change of direction makes a new card at once
Relations: `SIGNAL_CHANNEL_SHIFT` leads over it (when the total stays the same)
Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_NEW_TOP_SPENDER', 'base', 'H', 'market', 'Появился новый крупный рекламодатель', 'На рынке появляется компания с большими расходами в нашей категории, которая ещё не наш клиент.', 'Уже наш клиент → SIGNAL_SPEND_UP. Новое юрлицо без данных о расходах → SIGNAL_NEW_COMPANY. Разовая заметная кампания без данных о расходах → SIGNAL_AD_ACTIVITY.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, '«Сеть «Гастроном Плюс» впервые вошла в топ-50 рекламодателей категории «Продукты и напитки» (12 млн ₽ за октябрь 2026).»', '«Наш клиент «Винотека 24» поднялся с 40-го на 20-е место» → клиент уже наш, это SIGNAL_SPEND_UP.', 'Карточка о новом потенциальном клиенте: назовите категорию и объём; шаг — первый контакт через роль по маркетингу или закупкам.', 5, 'fixed', 'chance', false, 'event', 'medium', false, false, false, 'process', 'onHold', NULL, 'relationship', '{}'::text[], NULL, NULL, '{"ru":"Данные — внешний рейтинг расходов по категории. Условие — компания впервые входит в топ-N категории (N — настройка организации, предложение 50) и её нет в CRM как клиента. Минимум данных — 2 периода рейтинга. Запуск — ежемесячно. Повтор — не раньше 90 дней на компанию.","en":"Data — an external spend ranking per category. Condition — the company enters the category top-N for the first time (N is an org setting, proposal 50) and is not a client in the CRM. Minimum data — 2 ranking periods. Run — monthly. Cooldown — 90 days per company."}'::jsonb, 'Relevance window: cooldown 90 days per company + code
Deal effect: per org rule; usual: none (a prospect, not a deal)', NULL, NULL),
  ('SIGNAL_PRODUCT_NEWS', 'base', 'H', 'market', 'Запуск или обновление продукта', 'Компания выводит на рынок новый продукт, услугу, линейку, обновлённую версию или переиздание того, что она ПРОДАЁТ. Для HoReCa — новое меню, новая винная карта или новый формат заведения как продукт для гостей.', 'Компания покупает что-то для своей работы (оборудование, транспорт, ИТ) → SIGNAL_OPERATIONS_INVESTMENT. Спецификация, паспорт продукта, сертификат, прайс или каталог, присланные с заказом или запросом, — нет сигнала. Новая позиция в НАШЕМ каталоге → INTERNAL_PRODUCT_STATUS_UPDATE. Новая позиция у поставщика, который предлагает её нам → SUPPLIER_PRICE_CHANGE или нет сигнала. Клиент обновляет винную карту и рассматривает наши позиции → LISTING_OPPORTUNITY (distribution).', ARRAY['запускает новую линейку', 'представила новый продукт', 'вывела на рынок', 'новинка', 'обновлённое меню', 'новый формат', 'перезапуск', 'расширение ассортимента']::text[], '{"business":["в декабре запускаем новое сезонное меню","открываем направление кейтеринга для корпоративных клиентов","выводим собственную марку игристого","перезапускаем бренд кофеен в новом формате"],"news":["компания представила новую линейку","бренд выпустил лимитированную серию","сеть запустила собственную торговую марку","ресторан обновил меню","компания вывела на рынок новинку","стартовали продажи новой модели","расширила ассортимент"],"chat":["у них новинка вышла","запускают СТМ","меню полностью переделали","новую линейку выкатили"],"terms":["«СТМ» (собственная торговая марка)","линейка","лимитка","релонч","новинка","сезонное меню"],"patterns":["«[компания] запускает / представила [продукт]», «в продаже появится [продукт] с [даты]», «расширяет линейку [чем]»"]}'::jsonb, '[{"text":"«закупили новые кофемашины»","code":"SIGNAL_OPERATIONS_INVESTMENT"},{"text":"«во вложении спецификация и сертификат»","code":null},{"text":"«обновляем винную карту, пришлите предложения»","code":"LISTING_OPPORTUNITY"},{"text":"«сменили логотип и название»","code":"SIGNAL_REBRANDING"}]'::jsonb, '«Сеть «Винотека 24» с 1 декабря запускает собственную марку игристого вина в 40 магазинах.»', '«Направляем паспорт качества и декларацию соответствия к поставке» → документы к существующему товару, не новинка.', 'Назовите продукт и дату запуска; шаг — связаться с контактом клиента по роли и узнать, что нужно к запуску (ассортимент, объёмы, сроки), и только потом предлагать.', 5, 'fixed', 'chance', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Relations: `SIGNAL_REBRANDING` leads over it (when the brand is what changed); with `SIGNAL_CAMPAIGN_PLANNED` both when the launch campaign is named
Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_EXPANSION', 'base', 'H', 'market', 'Расширение бизнеса или новая площадка', 'Компания открывает новую точку, ресторан, магазин, филиал, склад для клиентов или выходит на новый рынок в регионах из профиля организации, либо набирает персонал под новую площадку. Источник — новости, реестры или упоминание третьей стороной.', 'Клиент сам пишет нам, что открывает новую точку → NEW_VENUE_OPENING (distribution); этот код тогда не ставится. Расширение за рубежом или вне регионов профиля — нет сигнала. Общие слова о росте без названной площадки («планируем расти») → SIGNAL_STRATEGY_CONTEXT. Новый склад или цех только для своей работы → SIGNAL_OPERATIONS_INVESTMENT. Слияние или покупка сети → SIGNAL_MERGER.', ARRAY['открытие нового ресторана', 'открывает магазин', 'новая точка', 'новый филиал', 'выходит в регион', 'открылся по адресу', 'расширяет сеть', 'набирает персонал в новый']::text[], '{"news":["ресторанная группа откроет пять заведений в 2027 году","сеть вышла в Санкт-Петербург","в ТЦ открылся новый магазин сети","на Патриарших открылся винный бар","компания открыла филиал в Казани","сеть расширилась до 30 магазинов","открытие запланировано на март"],"business_third_party":["слышали, что «Северный ветер» открывает второй ресторан на Белорусской","у «Винотеки 24» новый магазин в Химках"],"chat":["они ещё точку открывают","новый бар у них на Покровке","заходят в Питер","набирают команду на открытие"],"terms":["«новая ТТ» (торговая точка)","открытие","софт-опенинг","гранд-опенинг","франшиза","выход в регион"],"patterns":["«[компания] открывает / откроет [точку] в [месте]», «выходит на рынок [региона]», «расширяет сеть до [N]»"]}'::jsonb, '[{"text":"«мы открываем второй ресторан, нужна поставка» (пишет сам клиент)","code":"NEW_VENUE_OPENING"},{"text":"«открываем магазины в Казахстане»","code":null},{"text":"«хотим расти в следующем году»","code":"SIGNAL_STRATEGY_CONTEXT"},{"text":"«построили новый распределительный центр»","code":"SIGNAL_OPERATIONS_INVESTMENT"}]'::jsonb, '«Ресторанная группа «Северный ветер» в феврале откроет винный бар на Патриарших прудах.»', '«Ресторанная группа «Северный ветер» открывает ресторан в Дубае» → площадка вне регионов профиля, сигнала нет.', 'Назовите площадку и дату открытия; шаг — узнать у закупщика или управляющего клиента, кто формирует винную карту новой точки и когда, и предложить подборку после этого.', 4, 'fixed', 'chance', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Date gate: — (place check: only regions of the org profile)
Deal effect: per org rule; usual: none (the distribution code `NEW_VENUE_OPENING` is the deal entry when the client confirms it)', NULL, NULL),
  ('SIGNAL_FUNDING', 'base', 'H', 'market', 'Компания привлекла финансирование', 'Компания получает инвестиции, новый раунд, кредитную линию на развитие или нового миноритарного инвестора без смены контроля.', 'Переход контроля (больше 50 %, покупка) → SIGNAL_MERGER. Размещение акций на бирже → SIGNAL_IPO. Реструктуризация долга в кризисе → SIGNAL_INSOLVENCY. Господдержка или кредит на оборудование для своей работы → SIGNAL_OPERATIONS_INVESTMENT.', ARRAY['привлекла инвестиции', 'раунд финансирования', 'инвестор получил долю', 'вложил в компанию', 'закрыла раунд', 'получила кредитную линию на развитие', 'миноритарная доля', 'выпустила облигации']::text[], '{"news":["сеть привлекла 300 млн ₽ на развитие","фонд вошёл в капитал компании с долей 20 %","стартап закрыл раунд A","банк открыл кредитную линию на открытие новых точек","компания разместила облигации на 1 млрд ₽"],"business":["у нас вошёл новый инвестор, планируем расширяться","получили финансирование на развитие сети"],"chat":["им денег дали","зашёл инвестор","подняли раунд"],"terms":["раунд","pre-seed","seed","раунд A","миноритарий","облигации","ВДО","кредитная линия"],"patterns":["«[компания] привлекла [сумму] от [инвестора]», «[инвестор] получил [долю N %]», «закрыла раунд [название]»"]}'::jsonb, '[{"text":"«холдинг купил 100 % сети»","code":"SIGNAL_MERGER"},{"text":"«компания провела IPO»","code":"SIGNAL_IPO"},{"text":"«банк согласовал реструктуризацию долга»","code":"SIGNAL_INSOLVENCY"},{"text":"«взяли лизинг на автопарк»","code":"SIGNAL_OPERATIONS_INVESTMENT"}]'::jsonb, '«Сеть винных баров «Винотека 24» привлекла 250 млн ₽ от частного фонда за 25 % на открытие новых заведений.»', '«Холдинг «Гастроном Плюс» выкупил 75 % «Винотеки 24»» → смена контроля, это SIGNAL_MERGER.', 'Не предполагайте, что деньги пойдут на закупки у нас; шаг — узнать у контакта клиента, какие планы стоят за финансированием, пока они не распределены.', 4, 'fixed', 'chance', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Relations: `SIGNAL_MERGER` leads over it (when control changes)
Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_C_LEVEL_CHANGE', 'base', 'H', 'market', 'Смена высшего руководства', 'Меняется руководство вне маркетинга: генеральный директор, финансовый, операционный, коммерческий, технический директор, директор по персоналу, руководитель продаж, управляющий направлением (например, ресторанным), члены совета директоров или правления.', 'Новый руководитель маркетинга, бренда, коммуникаций → SIGNAL_NEW_MARKETING_LEAD. Новый закупщик или сомелье, который пишет нам сам → CONTACT_NEW_DECISION_MAKER. Смена произошла больше 6 месяцев назад — нет сигнала. Смена директора у нашего поставщика → PARTNER_PERSONNEL или нет сигнала; у конкурента → COMPETITOR_PERSONNEL.', ARRAY['назначен генеральным директором', 'новый генеральный директор', 'покинул пост', 'сменился руководитель', 'назначен финансовым директором', 'возглавил компанию', 'новый состав совета директоров', 'управляющим партнёром стал']::text[], '{"news":["генеральным директором компании назначен","в ЕГРЮЛ внесены сведения о новом руководителе","покинул пост генерального директора","новым коммерческим директором стал","совет директоров избрал председателем","операционным директором ресторанной группы назначен"],"business":["сообщаем о смене генерального директора, документы во вложении","с 01.12 договоры подписывает новый генеральный директор","доверенность выдана новым руководителем"],"chat":["у них гендир поменялся","новый коммерческий пришёл","финдиректора сменили, теперь всё через него"],"terms":["гендир","ГД","CEO","CFO","COO","коммерческий директор","совет директоров","ЕГРЮЛ"],"patterns":["«[ФИО] назначен(а) [должность]», «[ФИО] покинул(а) пост [должность]», «смена [генерального директора] в [компании]»"]}'::jsonb, '[{"text":"«новый директор по маркетингу»","code":"SIGNAL_NEW_MARKETING_LEAD"},{"text":"«я новый закупщик»","code":"CONTACT_NEW_DECISION_MAKER"},{"text":"«генеральный директор с 2022 года»","code":null},{"text":"«у «Винного Альянса» новый гендир»","code":"COMPETITOR_PERSONNEL"}]'::jsonb, '«Генеральным директором ООО «Северный ветер» с 15 октября назначен Петров П. П., сведения внесены в ЕГРЮЛ.»', '«Генеральный директор «Северного ветра» Петров П. П., который руководит компанией с 2021 года, дал интервью» → старое назначение, сигнала нет.', 'Информационная карточка: заголовок — только факт («клиент — новый генеральный директор»), без контакта с новым человеком; шаг — держать к следующему разговору и тогда спросить, меняет ли это наше сотрудничество.', 4, 'fixed', 'fyi', true, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Date gate: — (prompt rule: the change took effect no more than 6 months before the item date)
Relations: `SIGNAL_NEW_MARKETING_LEAD` leads over it (for a marketing-head change)
Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_REBRANDING', 'base', 'H', 'market', 'Ребрендинг или смена названия', 'Компания меняет название, логотип, фирменный стиль или концепцию бренда, либо запускает новый или полностью обновлённый сайт (в том числе переезд на новую платформу), о чём ей нужно сообщить клиентам.', 'Смена юрлица или реквизитов без нового бренда (новый ИНН, новый банк) — нет сигнала, это работа бухгалтерии. Новый продукт под тем же брендом → SIGNAL_PRODUCT_NEWS. Смена названия после покупки другой компанией → SIGNAL_MERGER (ребрендинг — контекст). Мелкая правка сайта или новый раздел — нет сигнала.', ARRAY['ребрендинг', 'новое название', 'новый логотип', 'обновлённый фирменный стиль', 'сменила вывеску', 'запустила новый сайт', 'перезапуск бренда', 'теперь называется']::text[], '{"business":["сообщаем, что с 01.12 ресторан работает под новым названием","прошу обновить наименование в документах и в карточке клиента","у нас обновился логотип, пришлём новые макеты для меню","мы запустили новый сайт с онлайн-бронированием"],"news":["сеть провела ребрендинг","бренд представил новый логотип","компания сменила название на","заведение откроется после ребрендинга под новой вывеской","обновили айдентику","перезапустили сайт на новой платформе"],"chat":["они переименовались","новую вывеску повесили","логотип поменяли","сайт переделали"],"terms":["ребрендинг","рестайлинг","айдентика","фирменный стиль","брендбук","новый сайт","редизайн"],"patterns":["«[компания] теперь называется [название]», «[бренд] представил новый [логотип / стиль]», «работает под новым названием с [даты]»"]}'::jsonb, '[{"text":"«поменялись реквизиты, новый расчётный счёт»","code":null},{"text":"«выпустили новую линейку»","code":"SIGNAL_PRODUCT_NEWS"},{"text":"«после покупки сеть будет работать под брендом покупателя»","code":"SIGNAL_MERGER"},{"text":"«добавили на сайт раздел с вакансиями»","code":null}]'::jsonb, '«С 1 декабря винный бар «Винотека 24» на Арбате будет работать под новым названием «Терруар» и с новой концепцией.»', '«Просим учесть новые банковские реквизиты ООО «Винотека 24» в счетах» → смена реквизитов, не ребрендинг.', 'Назовите конкретное изменение (название, логотип, сайт); шаг — до запуска узнать у контакта клиента, что меняется в концепции и меню, и обновить карточку клиента.', 4, 'fixed', 'chance', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Relations: leads over `SIGNAL_PRODUCT_NEWS` (when the brand is what changed)
Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_STRATEGY_ANNOUNCEMENT', 'base', 'H', 'market', 'Объявлена новая стратегия', 'Компания объявляет стратегическое решение с названным последствием для маркетинга, коммуникаций, рекламы или бюджета (для дистрибьютора — для закупок и ассортимента): новая стратегия бренда, перепозиционирование, рост или сокращение маркетингового бюджета, пересмотр всех поставщиков. Конкретного действия ещё нет.', 'Заявление о стратегии без названного последствия (производство, структура, интервью о рынке) → SIGNAL_STRATEGY_CONTEXT. Перенос бюджета между каналами при той же сумме → SIGNAL_CHANNEL_SHIFT. Клиент сокращает бюджет у нас → SALES_BUDGET_CUT. Конкретное событие, для которого есть свой H-код (новая точка, новый продукт, ребрендинг), → этот код.', ARRAY['новая стратегия бренда', 'перепозиционирование', 'увеличивает маркетинговый бюджет', 'сокращает рекламный бюджет', 'пересматривает пул поставщиков', 'делает ставку на премиальный сегмент', 'меняет ассортиментную политику', 'стратегия до 2030 года']::text[], '{"news":["компания утвердила новую стратегию развития бренда","сеть объявила о перепозиционировании в премиум","маркетинговый бюджет вырастет на 30 %","ретейлер пересмотрит ассортиментную матрицу","сеть объявила о сокращении числа поставщиков","компания делает ставку на собственные торговые марки"],"business":["в следующем году мы меняем ассортиментную политику","будем пересматривать всех поставщиков в категории вина","руководство решило уйти в премиальный сегмент"],"chat":["они уходят в премиум","будут чистить поставщиков","режут маркетинг","новая стратегия, всё переигрывают"],"terms":["стратегия","перепозиционирование","ассортиментная матрица","пул поставщиков","СТМ","маркетинговый бюджет"],"patterns":["«[компания] объявила / утвердила [стратегию]», «делает ставку на [что]», «пересматривает [бюджет / поставщиков / матрицу]»"]}'::jsonb, '[{"text":"«гендиректор рассказал о планах развития производства»","code":"SIGNAL_STRATEGY_CONTEXT"},{"text":"«переносим бюджет из ТВ в digital»","code":"SIGNAL_CHANNEL_SHIFT"},{"text":"«на следующий год сокращаем закупки у вас на треть»","code":"SALES_BUDGET_CUT"},{"text":"«открываем пять новых магазинов»","code":"SIGNAL_EXPANSION"}]'::jsonb, '«Сеть «Гастроном Плюс» объявила новую стратегию: доля премиальных вин в ассортименте вырастет до 40 %, поставщиков в категории станет меньше.»', '«Генеральный директор «Гастроном Плюс» в интервью рассказал о логистике и планах по складам» → без последствия для ассортимента или маркетинга, это SIGNAL_STRATEGY_CONTEXT.', 'Назовите последствие, которое указано в материале; если план открывается (новая стратегия, рост бюджета) — шанс войти в него рано; если у активного клиента сокращение или пересмотр поставщиков — риск, закрепить нашу долю до решения.', 4, 'fixed', 'chance', true, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Relations: catch-all: fires only when no more specific H code applies
Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_CHANNEL_SHIFT', 'base', 'H', 'market', 'Перераспределение бюджета между каналами', 'Компания переносит бюджет между каналами рекламы, маркетинга или сбыта при примерно той же общей сумме: из печати в digital, из ТВ в соцсети; для дистрибьютора — из офлайн-розницы в онлайн-продажи или из сети магазинов в HoReCa.', 'Общий бюджет растёт или падает → SIGNAL_STRATEGY_ANNOUNCEMENT или SIGNAL_SPEND_UP / SIGNAL_SPEND_DOWN. Клиент сокращает закупки у нас → SALES_BUDGET_CUT. Запуск одной кампании в новом канале → SIGNAL_CAMPAIGN_PLANNED.', ARRAY['перераспределяет бюджет', 'уходит из ТВ в digital', 'переносит бюджет в онлайн', 'сокращает наружку в пользу', 'основной канал теперь', 'делаем упор на маркетплейсы', 'смещает акцент на', 'из офлайна в онлайн']::text[], '{"news":["бренд переносит половину бюджета из ТВ в digital","ретейлер переориентирует продажи на онлайн-канал","компания отказывается от печатной рекламы в пользу соцсетей","доля e-commerce в продажах сети выросла, офлайн-точки сокращают"],"business":["в следующем году часть бюджета переводим в Telegram и блогеров","основной упор будет на доставку, а не на зал"],"chat":["они всё в онлайн уводят","ТВ режут, идут в блогеров","теперь всё через маркетплейсы"],"terms":["медиамикс","digital","ТВ","наружка","OOH","маркетплейсы","e-com","офлайн"],"patterns":["«переносит бюджет из [канала] в [канал]», «отказывается от [канала] в пользу [канала]», «упор на [канал]»"]}'::jsonb, '[{"text":"«маркетинговый бюджет вырастет на 30 %»","code":"SIGNAL_STRATEGY_ANNOUNCEMENT"},{"text":"«закупки у вас сократим»","code":"SALES_BUDGET_CUT"},{"text":"«в марте запускаем кампанию у блогеров»","code":"SIGNAL_CAMPAIGN_PLANNED"}]'::jsonb, '«В 2027 году «Винотека 24» переносит треть рекламного бюджета из наружной рекламы в Telegram-каналы и блогеров при прежнем общем объёме.»', '«В 2027 году «Винотека 24» удвоит рекламный бюджет» → меняется общая сумма, это SIGNAL_STRATEGY_ANNOUNCEMENT.', 'Скажите, куда уходит бюджет; если в наш канал — шанс узнать новый микс; если у активного клиента из нашего канала — риск, поговорить до утверждения следующего плана.', 4, 'fixed', 'chance', true, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Relations: leads over `SIGNAL_SPEND_DOWN` (when the total stays the same)
Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_PRODUCT_DISCONTINUED', 'base', 'H', 'market', 'Продукт снят с рынка', 'Клиент снимает свой продукт, услугу, формат или бренд с рынка; бюджет и закупки под него исчезают.', 'Клиент убирает НАШИ позиции из меню или ассортимента → DELISTING_RISK (distribution). Мы выводим свою позицию → INTERNAL_PRODUCT_STATUS_UPDATE. Поставщик прекращает выпуск товара, который мы закупаем → SUPPLIER_DELIVERY_DELAY («больше не производится»). Отзыв партии по решению надзора → SIGNAL_NEGATIVE_PRESS. Закрытие точки → SIGNAL_DOWNSIZING.', ARRAY['снимает с производства', 'прекращает выпуск', 'выводит из линейки', 'закрывает направление', 'больше не будет продавать', 'уходит из категории', 'последняя партия', 'закрывает формат']::text[], '{"news":["компания прекращает выпуск бренда","сеть закрывает направление кулинарии","бренд уходит из категории игристых","ретейлер выводит из продажи линейку СТМ","ресторанная группа отказывается от формата фудкортов"],"business":["мы закрываем направление кейтеринга с января","линейку баров при отелях сворачиваем","формат доставки прекращаем"],"chat":["они эту линейку закрыли","кейтеринг больше не делают","бренд свернули"],"terms":["вывод из линейки","снятие с производства","делистинг","закрытие направления","СТМ"],"patterns":["«[компания] прекращает [выпуск / продажу] [продукта]», «закрывает направление [что]», «уходит из [категории]»"]}'::jsonb, '[{"text":"«убираем ваше вино из карты»","code":"DELISTING_RISK"},{"text":"«производитель больше не выпускает этот кюве»","code":"SUPPLIER_DELIVERY_DELAY"},{"text":"«партию отозвали по предписанию»","code":"SIGNAL_NEGATIVE_PRESS"},{"text":"«закрываем ресторан»","code":"SIGNAL_DOWNSIZING"}]'::jsonb, '«Ресторанная группа «Северный ветер» с 1 января закрывает направление выездного кейтеринга.»', '«Мы больше не берём у вас Шабли, выводим из карты» → это наши позиции у клиента, DELISTING_RISK.', 'Назовите, что снимается и с какой даты; шаг — оценить, какие наши поставки шли под это направление, и обсудить с закупщиком, что остаётся.', 4, 'fixed', 'risk', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Emitted by: both; in the `press` profile only when the company is our client
Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_NEW_COMPANY', 'base', 'H', 'market', 'Создана новая компания', 'Зарегистрирована новая компания или открыт новый бизнес, у которого ещё нет партнёров. Для дистрибьютора важны новые рестораны, бары, винотеки, магазины, кейтеринговые компании, получившие или подающие заявку на алкогольную лицензию.', 'Новая точка действующей компании → SIGNAL_EXPANSION. Новое юрлицо после реорганизации или покупки → SIGNAL_MERGER. Регистрация товарного знака или домена без компании → SIGNAL_TRADEMARK. Новое юрлицо нашего же клиента для расчётов (смена ИНН) — нет сигнала.', ARRAY['зарегистрирована новая компания', 'открылся новый ресторан', 'новый проект ресторатора', 'получила лицензию на розничную продажу алкоголя', 'создано ООО', 'стартап', 'новое заведение от команды', 'запуск нового бизнеса']::text[], '{"news":["в ЕГРЮЛ зарегистрировано ООО с видом деятельности «деятельность ресторанов»","ресторатор открывает новый проект","команда бара запускает собственное заведение","выдана лицензия на розничную продажу алкогольной продукции при оказании услуг общепита","на рынок вышел новый игрок"],"business":["мы новая компания, открываемся в марте, ищем поставщика вина","знакомые открывают винный бар, им нужен поставщик"],"chat":["ребята новый бар открывают","у шефа свой проект стартует","новая контора, только зарегались"],"terms":["ЕГРЮЛ","ОКВЭД 56.10","лицензия РАР","ФСРАР","новое ООО","ИП"],"patterns":["«зарегистрировано [ООО] с [видом деятельности]», «[команда / ресторатор] открывает новый проект [название]», «получена лицензия [на продажу алкоголя]»"]}'::jsonb, '[{"text":"«сеть открыла шестой магазин»","code":"SIGNAL_EXPANSION"},{"text":"«после присоединения создано новое юрлицо»","code":"SIGNAL_MERGER"},{"text":"«зарегистрировали товарный знак»","code":"SIGNAL_TRADEMARK"},{"text":"«у нас новое ООО для расчётов, вот реквизиты»","code":null}]'::jsonb, '«Шеф-повар ресторана «Северный ветер» открывает собственный винный бар «Лоза» на Малой Бронной, запуск в марте.»', '«Сеть «Винотека 24» открыла новый магазин в Химках» → это новая точка действующей сети, SIGNAL_EXPANSION.', 'Это всегда потенциальный клиент: шаг — первый контакт с владельцем или управляющим до выбора поставщиков, чтобы стать первым партнёром.', 3, 'fixed', 'chance', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual: none (a prospect, not a deal)', NULL, NULL),
  ('SIGNAL_TRADEMARK', 'base', 'H', 'market', 'Зарегистрирован бренд или домен', 'Компания регистрирует или подаёт заявку на товарный знак или новый домен. Это ранний признак нового бренда до запуска.', 'Бренд уже запущен на рынке → SIGNAL_PRODUCT_NEWS или SIGNAL_REBRANDING. Новая компания → SIGNAL_NEW_COMPANY. Продление существующего знака или домена — нет сигнала. Спор о товарном знаке → SIGNAL_NEGATIVE_PRESS или нет сигнала.', ARRAY['подала заявку на товарный знак', 'зарегистрировала товарный знак', 'Роспатент зарегистрировал', 'новый домен', 'заявка на регистрацию бренда', 'зарегистрировала знак обслуживания', 'права на название', 'свидетельство на товарный знак']::text[], '{"news":["компания подала в Роспатент заявку на товарный знак","Роспатент зарегистрировал товарный знак","ресторатор зарегистрировал бренд для нового проекта","зарегистрирован домен под новый проект","знак обслуживания по 43-му классу МКТУ"],"business":["мы зарегистрировали название нового бара, скоро анонс","под новую марку уже купили домен"],"chat":["они бренд зарегали","знак подали, видимо, новый проект","домен уже купили"],"terms":["Роспатент","ФИПС","МКТУ","товарный знак","ТЗ","знак обслуживания","домен .ru / .рф"],"patterns":["«[компания] подала заявку на [товарный знак]», «зарегистрирован [знак / домен] [название]»"]}'::jsonb, '[{"text":"«новый бренд уже в продаже»","code":"SIGNAL_PRODUCT_NEWS"},{"text":"«продлили регистрацию знака»","code":null},{"text":"«суд запретил использовать название»","code":"SIGNAL_NEGATIVE_PRESS"}]'::jsonb, '«ООО «Северный ветер» подало в Роспатент заявку на товарный знак «Лоза» по 33-му и 43-му классам МКТУ.»', '«Свидетельство на товарный знак «Северный ветер» продлено ещё на 10 лет» → продление, нового бренда нет.', 'Обычно это новый бренд до запуска: шаг — первый контакт, чтобы стать первым поставщиком нового проекта.', 3, 'fixed', 'chance', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual: none', NULL, NULL)
