INSERT INTO "signal_category" ("code", "pack_code", "block_code", "family", "label_ru", "definition_ru", "boundary_ru", "cues_prompt_ru", "synonyms_ru", "anti_cues_ru", "example_ru", "counter_example_ru", "card_note_ru", "weight", "score_rule", "class", "class_by_relation", "kind", "effort", "carries_amount", "asks_us", "inbound_only", "emitted_by", "stage", "display_profile", "recipient_role", "closes_codes", "date_gate", "relevance_days", "trigger_rule", "note_ru", "retired_at", "successor_code") VALUES
  ('SIGNAL_JOB_POSTING', 'base', 'H', 'market', 'Открыта релевантная вакансия', 'Компания ищет человека на роль, важную для нас: маркетинг, бренд, закупки, категорийный менеджмент; для дистрибьютора — закупщик, сомелье, бар-менеджер, категорийный менеджер по алкоголю.', 'Вакансии без связи с нашей областью (повар, курьер, бухгалтер) — нет сигнала. Набор команды под открытие новой точки → SIGNAL_EXPANSION. Человек уже назначен → SIGNAL_NEW_MARKETING_LEAD / SIGNAL_C_LEVEL_CHANGE / CONTACT_NEW_DECISION_MAKER. Вакансия у нас самих — нет сигнала.', ARRAY['ищем сомелье', 'вакансия закупщика', 'требуется бренд-менеджер', 'открыта вакансия категорийного менеджера', 'ищем бар-менеджера', 'в команду маркетинга требуется', 'вакансия на hh.ru', 'нанимаем руководителя закупок']::text[], '{"news":["сеть ищет категорийного менеджера по вину и крепкому алкоголю","ресторанная группа открыла вакансию шеф-сомелье","требуется менеджер по закупкам алкогольной продукции","в отдел маркетинга требуется бренд-менеджер"],"business":["наш закупщик ушёл, сейчас ищем нового","пока ищем сомелье, заказы делает управляющий"],"chat":["они сомелье ищут","вакансия висит на хэдхантере","закупщика нет, ищут"],"terms":["hh.ru","вакансия","«КМ» (категорийный менеджер)","бар-менеджер","шеф-сомелье","байер"],"patterns":["«ищем / требуется [роль]», «открыта вакансия [роль]», «в команду [отдела] нужен [роль]»"]}'::jsonb, '[{"text":"«ищем поваров и официантов»","code":null},{"text":"«набираем команду на открытие нового ресторана»","code":"SIGNAL_EXPANSION"},{"text":"«я новый сомелье, давайте знакомиться»","code":"CONTACT_NEW_DECISION_MAKER"},{"text":"«я ухожу из компании»","code":"CONTACT_LEAVING"}]'::jsonb, '«Ресторанная группа «Северный ветер» ищет шеф-сомелье с опытом формирования винных карт для четырёх ресторанов.»', '«Ресторанная группа «Северный ветер» набирает официантов и барменов на сезон» → роли вне нашей области.', 'У нашего клиента — узнать, кто сейчас решает о закупках и что меняется (если прежний человек ушёл — риск); у неклиента — шанс выйти на нового человека первым.', 3, 'fixed', 'chance', true, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_EVENT', 'base', 'H', 'market', 'Компания участвовала в отраслевом событии', 'Компания участвовала в выставке, конференции, фестивале или отраслевом событии как участник, спикер или партнёр, и событие уже прошло (или дата не указана).', 'Событие ещё впереди → SIGNAL_EVENT_UPCOMING. Компания выступает спонсором → SIGNAL_SPONSORING. Наше собственное участие — нет сигнала. Дегустация или встреча у клиента с нами → блок F или distribution TASTING_REQUESTED.', ARRAY['представила на выставке', 'приняла участие в', 'выступил на конференции', 'стенд компании на', 'по итогам выставки', 'участвовала в фестивале', 'показали на форуме', 'вернулись с выставки']::text[], '{"news":["компания представила новинки на выставке","ресторанная группа приняла участие в гастрономическом фестивале","генеральный директор выступил на отраслевом форуме","по итогам выставки сеть подписала соглашения","бар вошёл в число участников фестиваля"],"business":["мы только вернулись с выставки, было много контактов","на прошлой неделе были на форуме ретейла"],"chat":["они на выставке стояли","видел их на фестивале","были на форуме, выступали"],"terms":["выставка","стенд","форум","фестиваль","конференция","спикер","экспонент"],"patterns":["«[компания] представила [что] на [событии]», «приняла участие в [событии]», «по итогам [события]»"]}'::jsonb, '[{"text":"«в феврале будем на выставке, приходите»","code":"SIGNAL_EVENT_UPCOMING"},{"text":"«выступили генеральным спонсором фестиваля»","code":"SIGNAL_SPONSORING"},{"text":"«мы (наша компания) провели дегустацию»","code":null}]'::jsonb, '«Сеть «Винотека 24» представила на прошедшей выставке свою новую марку игристого и подписала два соглашения с поставщиками.»', '«Сеть «Винотека 24» примет участие в выставке в феврале 2027 года» → событие впереди, это SIGNAL_EVENT_UPCOMING.', 'Информационная карточка: скажите, что компания показала или объявила на событии; шаг — держать к следующему разговору, без контакта и предложения.', 3, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Date gate: — (prompt rule: the event is over or has no date relative to the item date; an event after the item date is `SIGNAL_EVENT_UPCOMING`)
Relations: split by date with `SIGNAL_EVENT_UPCOMING`
Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_IPO', 'base', 'H', 'market', 'Выход компании на биржу', 'Компания проводит или объявляет первичное публичное размещение акций (IPO) или прямой листинг на бирже.', 'Частный раунд, облигации, кредит → SIGNAL_FUNDING. Смена контроля → SIGNAL_MERGER. Публикация отчётности публичной компании → SIGNAL_RESULTS_POSITIVE / SIGNAL_RESULTS_NEGATIVE.', ARRAY['IPO', 'первичное размещение акций', 'выходит на биржу', 'объявила о намерении провести IPO', 'начало торгов акциями', 'прямой листинг', 'Мосбиржа', 'SPO']::text[], '{"news":["компания объявила о намерении провести IPO на Московской бирже","акции сети начали торговаться на бирже","книга заявок закрыта","ретейлер разместил акции","компания провела SPO"],"chat":["они на биржу выходят","айпио у них","акции разместили"],"terms":["IPO","SPO","Мосбиржа","СПБ Биржа","free float","книга заявок","листинг"],"patterns":["«[компания] объявила о [IPO]», «акции [компании] начали торговаться», «разместила [N %] акций»"]}'::jsonb, '[{"text":"«выпустила облигации на 1 млрд ₽»","code":"SIGNAL_FUNDING"},{"text":"«отчёт за III квартал»","code":null},{"text":"«фонд купил 60 % компании»","code":"SIGNAL_MERGER"}]'::jsonb, '«Холдинг «Гастроном Плюс» объявил о намерении провести IPO на Московской бирже в первом квартале 2027 года.»', '«Холдинг «Гастроном Плюс» разместил облигации на 2 млрд ₽» → долговое финансирование, SIGNAL_FUNDING.', 'Информационно с шансом: публичная компания будет больше думать о росте; шаг — держать к разговору и спросить о планах развития сети.', 3, 'fixed', 'chance', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_ANNIVERSARY', 'base', 'H', 'market', 'Юбилей с коммуникационной активностью', 'Компания отмечает юбилей и в материале названа активность вокруг него: кампания, специальные продукты или издания, праздничное событие, акции, реклама. Для HoReCa — юбилейный вечер, праздничное меню, винный ужин.', 'Юбилей просто упомянут, активность не названа → SIGNAL_ANNIVERSARY_PLAIN. Обычная сезонная акция без юбилея → SIGNAL_CAMPAIGN_PLANNED / SIGNAL_AD_ACTIVITY. Клиент просит нас провести дегустацию к юбилею → TASTING_REQUESTED (distribution).', ARRAY['к юбилею запускает', 'юбилейная коллекция', 'юбилейное меню', 'в честь 10-летия', 'праздничный вечер к юбилею', 'юбилейная акция', 'ограниченная серия к годовщине', 'отметит юбилей']::text[], '{"news":["в честь 20-летия сеть запускает юбилейную акцию","к юбилею ресторан подготовил специальное меню и винный ужин","бренд выпустил юбилейную серию","компания отметит 25-летие большим фестивалем","юбилейная кампания стартует в декабре"],"business":["в марте нам 10 лет, планируем вечер для гостей и спецпредложение","к юбилею хотим сделать винную карту с особыми позициями"],"chat":["у них юбилей, будет большая вечеринка","к десятилетию делают акцию","юбилейное меню готовят"],"terms":["юбилей","годовщина","юбилейная серия","лимитка","винный ужин","гала-вечер"],"patterns":["«в честь [N-летия] [компания] [запускает / проводит] [что]», «к юбилею [что]»"]}'::jsonb, '[{"text":"«компании исполнилось 30 лет» (без активности)","code":"SIGNAL_ANNIVERSARY_PLAIN"},{"text":"«новогодняя акция в магазинах»","code":"SIGNAL_CAMPAIGN_PLANNED"},{"text":"«к юбилею просим провести дегустацию для гостей»","code":"TASTING_REQUESTED"}]'::jsonb, '«К 15-летию ресторан «Северный ветер» 20 марта проводит гала-ужин и запускает юбилейную винную карту.»', '«Ресторану «Северный ветер» в марте исполняется 15 лет» → активность не названа, это SIGNAL_ANNIVERSARY_PLAIN.', 'Это повод с датой и бюджетом: шаг — заранее узнать у контакта клиента, что планируется (меню, вечер, акция), и потом предложить подборку; без поздравлений как действия.', 5, 'fixed', 'chance', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Relations: split with `SIGNAL_ANNIVERSARY_PLAIN` (no communication named)
Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_SPONSORING', 'base', 'H', 'market', 'Спонсорский проект', 'Компания выступает спонсором или партнёром мероприятия, команды, фестиваля, премии, благотворительного проекта.', 'Просто участие как экспонент или спикер → SIGNAL_EVENT / SIGNAL_EVENT_UPCOMING. Совместный коммерческий проект с другой компанией → SIGNAL_PARTNERSHIP. Клиент просит НАС быть спонсором или дать продукцию на событие → PROMO_SUPPORT_REQUESTED (distribution).', ARRAY['генеральный спонсор', 'официальный партнёр фестиваля', 'выступила спонсором', 'при поддержке', 'спонсорский контракт', 'партнёр турнира', 'благотворительный проект', 'титульный спонсор']::text[], '{"news":["сеть стала генеральным спонсором гастрономического фестиваля","компания — официальный партнёр городского марафона","бренд подписал спонсорский контракт с клубом","ресторан выступил партнёром благотворительного вечера"],"business":["в этом году мы спонсоры фестиваля, будет наш бар на площадке"],"chat":["они спонсируют фестиваль","их бар будет на марафоне как партнёр"],"terms":["спонсор","генеральный партнёр","титульный спонсор","при поддержке","благотворительность"],"patterns":["«[компания] стала [генеральным / официальным] [спонсором / партнёром] [события]», «при поддержке [компании]»"]}'::jsonb, '[{"text":"«будем стоять на выставке»","code":"SIGNAL_EVENT_UPCOMING"},{"text":"«запустили совместный продукт с пивоварней»","code":"SIGNAL_PARTNERSHIP"},{"text":"«поддержите наш фестиваль вином, нужны бутылки»","code":"PROMO_SUPPORT_REQUESTED"}]'::jsonb, '«Ресторанная группа «Северный ветер» стала официальным партнёром фестиваля уличной еды в Парке Горького.»', '«Ресторанная группа «Северный ветер» будет участником фестиваля уличной еды» → участие без спонсорства, SIGNAL_EVENT_UPCOMING.', 'Не предполагайте коммуникацию вокруг спонсорства; шаг — спросить контакт клиента, будут ли под проект закупки или бар на площадке, и только тогда предлагать.', 3, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_CONTACT_QUIET', 'base', 'H', 'account', 'Снижается интенсивность общения', 'Общение с клиентом заметно затихает: клиент пишет и отвечает реже, чем обычно, при этом явного отказа или конфликта нет.', 'Клиент перестал покупать в своём ритме → ACCOUNT_DORMANT. Нет ответа на конкретное наше предложение → SALES_OFFER_NO_RESPONSE. Автоответ об отпуске → CONTACT_OOO. Праздничный период (январские, майские праздники) и известный отпуск контакта — нет сигнала. Полное отсутствие контакта у бывшего клиента → ACCOUNT_REACTIVATION_DUE.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, '«За 30 дней от клиента 2 входящих сообщения при обычных 9 в месяц; от нас за это время 5 писем.»', '«Контакт клиента в отпуске до 20.11, по срочным вопросам — к заместителю» → это CONTACT_OOO, затихания нет.', 'Информационно: скажите, с какого времени и насколько упало общение; шаг — короткий личный вопрос контакту клиента по роли, без давления и без предложения.', 3, 'fixed', 'fyi', false, 'trend', 'medium', false, false, false, 'both', 'parked', NULL, 'relationship', '{}'::text[], NULL, NULL, '{"ru":"Данные — входящие сообщения от контактов клиента во всех подключённых каналах (почта, Telegram, WhatsApp), привязанные к клиенту; учитываются только сообщения, прошедшие гейты (без автоответов и рассылок). Окно — последние 30 дней. База — среднее за 30 дней по предыдущим 90 дням. Минимум данных — не меньше 8 входящих сообщений за базовые 90 дней и не меньше 60 дней истории общения. Порог — входящих в окне меньше 40 % от базы, и наших исходящих за окно не меньше 2 (мы пишем, клиент молчит). Исключения — открытый `CONTACT_OOO` контакта, производственный календарь (праздничные недели не входят в окно). Запуск — еженедельно, понедельник. Повтор — не раньше 90 дней на клиента и код. Мало данных — сигнала нет.","en":"Data — inbound messages from the client''s contacts in all connected channels (email, Telegram, WhatsApp) linked to the client; only items that passed the gates (no auto-replies, no newsletters). Window — last 30 days. Baseline — 30-day average over the previous 90 days. Minimum data — at least 8 inbound messages in the 90-day baseline and at least 60 days of history. Threshold — inbound in the window below 40 % of the baseline, and at least 2 outbound messages from us in the window. Exclusions — an open `CONTACT_OOO` of the contact; holiday weeks of the Russian production calendar are not counted. Run — weekly, Monday. Cooldown — 90 days per client + code. Too little data — no instance."}'::jsonb, 'Display profile: from weight (W1); trend ceiling D4
Profile (summary): W1 (trend ceiling D4)
Emitted by: both (v204); in this design only the process emits it — see Open points
Closed by: — (any qualifying contact restarts the window)
Date gate: — (trend rule below)
Relevance window: trend cooldown 90 days per client + code (`cards.trendCooldownDays`)
Deal effect: per org rule; usual: none (agency pack: input to the risk «Клиент затих»)', NULL, NULL),
  ('SIGNAL_INDUSTRY_TREND', 'base', 'H', 'market', 'Отраслевая тенденция или регулирование', 'Новое регулирование или отраслевое изменение с понятным последствием для клиентов: для алкогольного рынка — изменение акцизов, минимальных розничных цен, пошлин на импорт, правил ЕГАИС и маркировки, лицензирования, ограничений продажи; общее изменение спроса в отрасли.', 'Событие одной компании → другой H-код. Конкретная проблема клиента в ЕГАИС или с марками → EGAIS_ISSUE / MARKING_ISSUE (distribution). Изменение цен нашего поставщика → SUPPLIER_PRICE_CHANGE. Общая аналитика без последствия для клиентов — нет сигнала.', ARRAY['с 1 января вырастут акцизы', 'минимальная розничная цена', 'повышение ввозных пошлин', 'изменения в ЕГАИС', 'новые требования к маркировке', 'закон о продаже алкоголя', 'ограничение продажи алкоголя', 'рынок вина сократился']::text[], '{"news":["Минфин повысил минимальные розничные цены на вино","с 2027 года акциз на игристые вина вырастет","правительство повысило пошлины на вина из недружественных стран","Росалкогольтабакконтроль меняет порядок фиксации в ЕГАИС","регион ввёл запрет на продажу алкоголя в ночные часы","рынок импортного вина за 9 месяцев сократился на 12 %"],"business":["в связи с ростом пошлин с 01.01 цены на импорт изменятся","у нас в области ограничили часы продажи, закупки сократим"],"chat":["акцизы опять подняли","пошлины на европейское вино задрали","в ЕГАИС опять всё поменяли","МРЦ на вино подняли"],"terms":["акциз","МРЦ","пошлина","ЕГАИС","РАР","ФСМ","Честный знак","171-ФЗ","468-ФЗ (о виноградарстве и виноделии)"],"patterns":["«с [даты] [изменится / вводится] [норма]», «[ведомство] повысило / утвердило [что]», «рынок [категории] [вырос / сократился] на [N %]»"]}'::jsonb, '[{"text":"«не можем подтвердить ТТН в ЕГАИС»","code":"EGAIS_ISSUE"},{"text":"«производитель поднимает цены с 01.12»","code":"SUPPLIER_PRICE_CHANGE"},{"text":"«сеть закрывает магазины из-за ограничений»","code":"SIGNAL_DOWNSIZING"}]'::jsonb, '«С 1 января 2027 года минимальная розничная цена на бутылку игристого вина 0,75 л повышается, сообщил Минфин.»', '«У нас ТТН висит в ЕГАИС третий день, не можем принять» → проблема одного клиента, EGAIS_ISSUE.', 'Заголовок называет отрасль или изменение, а не одного клиента; шаг — проверить, каких наших клиентов это касается, без предложения отдельному клиенту.', 2, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_RESULTS_POSITIVE', 'base', 'H', 'market', 'Положительные результаты компании', 'Компания публикует результаты с ростом: выручка, прибыль, продажи, трафик, число гостей. Нужны число и период сравнения.', 'Рост закупок у нас → ACCOUNT_REVENUE_GROWTH_YOY. Слова «год был удачным» без цифры и периода — нет сигнала. Прогноз или план без факта → SIGNAL_STRATEGY_CONTEXT. Маркетинговый бюджет в отчёте не является кампанией → не SIGNAL_AD_ACTIVITY.', ARRAY['выручка выросла на', 'рост продаж на', 'чистая прибыль увеличилась', 'по итогам квартала', 'LFL-продажи выросли', 'трафик вырос на', 'год к году', 'по МСФО']::text[], '{"news":["выручка сети за 9 месяцев выросла на 18 % год к году","чистая прибыль по МСФО увеличилась вдвое","сопоставимые продажи (LFL) выросли на 7 %","ресторанная группа отчиталась о росте выручки","средний чек вырос на 12 %"],"business":["по итогам года выручка у нас +20 %, расширяем винную карту"],"chat":["у них выручка прёт","плюс 20 % за год","отчитались хорошо"],"terms":["выручка","EBITDA","МСФО","РСБУ","LFL","г/г","кв/кв","средний чек"],"patterns":["«[показатель] вырос на [N %] [к периоду]», «по итогам [периода] [показатель] составил [сумма], [+N %]»"]}'::jsonb, '[{"text":"«клиент купил у нас на 30 % больше»","code":"ACCOUNT_REVENUE_GROWTH_YOY"},{"text":"«год был отличный»","code":null},{"text":"«планируем рост на 20 %»","code":"SIGNAL_STRATEGY_CONTEXT"}]'::jsonb, '«Выручка сети «Винотека 24» за январь–сентябрь 2026 года выросла на 18 % год к году, до 2,4 млрд ₽.»', '«Сеть «Винотека 24» рассчитывает на рост выручки в следующем году» → прогноз без факта.', 'Информационно: назовите показатель, цифру и период; шаг — держать к следующему разговору.', 3, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_RESULTS_NEGATIVE', 'base', 'H', 'market', 'Отрицательные результаты компании', 'Компания публикует результаты со снижением: выручка, прибыль, продажи, трафик, рост убытка. Нужны число и период сравнения.', 'Снижение закупок у нас → ACCOUNT_REVENUE_DECLINE_YOY. Банкротство, блокировка счетов → SIGNAL_INSOLVENCY. Закрытие точек → SIGNAL_DOWNSIZING. Слова «год был тяжёлым» без цифры — нет сигнала.', ARRAY['выручка снизилась на', 'падение продаж на', 'убыток вырос', 'чистая прибыль сократилась', 'LFL-продажи упали', 'трафик снизился', 'год к году', 'по итогам полугодия']::text[], '{"news":["выручка ресторанной группы за полугодие снизилась на 9 %","чистый убыток по РСБУ вырос в 1,5 раза","сопоставимые продажи упали на 4 %","трафик в заведениях сократился на 11 % год к году"],"business":["у нас выручка минус 15 % к прошлому году, поэтому закупки скромнее"],"chat":["у них выручка просела","минус 10 % за год","отчитались в убыток"],"terms":["выручка","убыток","МСФО","РСБУ","LFL","г/г","трафик"],"patterns":["«[показатель] снизился / упал на [N %] [к периоду]», «убыток составил [сумма]»"]}'::jsonb, '[{"text":"«клиент купил у нас меньше, чем в прошлом году»","code":"ACCOUNT_REVENUE_DECLINE_YOY"},{"text":"«введена процедура наблюдения»","code":"SIGNAL_INSOLVENCY"},{"text":"«закроем пять ресторанов»","code":"SIGNAL_DOWNSIZING"},{"text":"«сейчас тяжело»","code":null}]'::jsonb, '«Выручка ресторанной группы «Северный ветер» за первое полугодие 2026 года снизилась на 9 % год к году.»', '«Ресторанная группа «Северный ветер» закрывает два ресторана» → это SIGNAL_DOWNSIZING.', 'Информационно: назовите показатель, цифру и период; шаг — держать к разговору и при следующем контакте спросить, как это влияет на закупки.', 3, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_AWARD', 'base', 'H', 'market', 'Компания получила награду', 'Компания, её заведение, продукт или сотрудник получает премию, награду, звание или место в рейтинге (для HoReCa — ресторанные премии, гиды, рейтинги баров; для вина — медали конкурсов).', 'Награда конкуренту → COMPETITOR_AWARD, партнёру → PARTNER_AWARD. Медаль у вина, которое мы закупаем, в письме поставщика → нет сигнала (или SUPPLIER_PRICE_CHANGE, если пришёл новый прайс). Компания сама вручает премию или спонсирует её → SIGNAL_SPONSORING. Наша собственная награда — нет сигнала.', ARRAY['получил премию', 'вошёл в рейтинг', 'стал лауреатом', 'звезда гида', 'лучший винный бар', 'золотая медаль', 'победитель конкурса', 'отмечен в гиде']::text[], '{"news":["ресторан вошёл в топ-50 ресторанного рейтинга","бар получил премию «Лучший винный бар года»","заведение отмечено в гастрономическом гиде","сомелье ресторана стал победителем национального конкурса","сеть признана лучшим винным ретейлером года"],"business":["нас включили в гид, спасибо за помощь с картой","наш сомелье выиграл конкурс"],"chat":["им звезду дали","попали в топ","взяли премию"],"terms":["премия","рейтинг","гид","лауреат","номинация","медаль","конкурс сомелье"],"patterns":["«[компания] получила [премию / награду]», «вошла в [рейтинг / гид]», «стала лауреатом [премии]»"]}'::jsonb, '[{"text":"««Винный Альянс» стал дистрибьютором года»","code":"COMPETITOR_AWARD"},{"text":"«ресторан учредил премию для молодых шефов»","code":"SIGNAL_SPONSORING"},{"text":"«вино получило 95 баллов, новый прайс во вложении»","code":null}]'::jsonb, '«Винный бар «Терруар» получил премию «Лучшая винная карта года» в номинации «Москва».»', '««Винный Альянс» признан лучшим импортёром года» → награда конкуренту, COMPETITOR_AWARD.', 'Информационно: держать к следующему разговору, без контакта, поздравления как задачи и предложения; если компания использует награду в рекламе — отметить это.', 2, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_PARTNERSHIP', 'base', 'H', 'market', 'Объявлено партнёрство', 'Клиент начинает сотрудничество с третьей стороной без смены контроля: совместная кампания или продукт, совместное предприятие, дистрибуторское или франчайзинговое соглашение, коллаборация.', 'Переход контроля → SIGNAL_MERGER. Клиент начинает работать с другим поставщиком того, что продаём мы → SIGNAL_COMPETITOR. Партнёрство нашего партнёра или поставщика → блок L (PARTNER_*). Спонсорство события → SIGNAL_SPONSORING. Наше собственное партнёрство с клиентом — нет сигнала.', ARRAY['подписали соглашение о сотрудничестве', 'совместный проект', 'коллаборация', 'стратегическое партнёрство', 'совместное предприятие', 'эксклюзивный дистрибьютор', 'франчайзинговое соглашение', 'запускают вместе']::text[], '{"news":["сеть и сервис доставки подписали соглашение о стратегическом партнёрстве","ресторан и винодельня запускают коллаборацию","компании создали совместное предприятие","бренд выходит в регионы по франшизе через партнёра","банк и ресторанная группа запустили совместную программу лояльности"],"business":["мы начинаем проект с сервисом доставки, объёмы вырастут","делаем совместный ужин с винодельней"],"chat":["у них колаба с винодельней","вместе с доставкой что-то запускают","зашли в партнёрство"],"terms":["коллаборация","колаба","СП","соглашение о сотрудничестве","франшиза","кобрендинг"],"patterns":["«[компания] и [компания] подписали [соглашение]», «запускают совместный [проект / продукт]», «стали партнёрами в [области]»"]}'::jsonb, '[{"text":"«холдинг купил 60 % компании»","code":"SIGNAL_MERGER"},{"text":"«вино теперь берём у «Винного Альянса»»","code":"SIGNAL_COMPETITOR"},{"text":"«стали генеральным спонсором фестиваля»","code":"SIGNAL_SPONSORING"}]'::jsonb, '«Сеть «Винотека 24» и сервис доставки «Быстро» подписали соглашение: с декабря вино сети будет доступно в приложении.»', '«Холдинг «Гастроном Плюс» получил контроль над сервисом «Быстро»» → смена контроля, SIGNAL_MERGER.', 'Пишите для нашего клиента, не для партнёра; не предполагайте коммуникацию или объёмы — шаг: спросить контакт клиента, что партнёрство значит для закупок; если ничего — держать к разговору.', 3, 'fixed', 'chance', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Relations: `SIGNAL_MERGER` leads over it (when control changes)
Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_AD_ACTIVITY', 'base', 'H', 'market', 'Кампания идёт или завершается', 'Компания сейчас ведёт платную рекламу или акцию, либо кампания скоро заканчивается: реклама замечена в медиа или библиотеке объявлений, ролик в эфире, действующая промоакция или партнёрская программа. Это признак маркетингового бюджета, а не измеренный расход.', 'Кампания объявлена, но ещё не стартовала → SIGNAL_CAMPAIGN_PLANNED. Годовой маркетинговый бюджет в отчётности → часть SIGNAL_RESULTS_*, не этот код. Конкурент у клиента → SIGNAL_COMPETITOR. Клиент просит у нас промоподдержку → PROMO_SUPPORT_REQUESTED (distribution). Наша собственная акция — нет сигнала.', ARRAY['стартовала кампания', 'идёт акция', 'в эфире ролик', 'действует до', 'акция продлится до', 'реклама в метро', 'запустила промо', 'последняя неделя акции']::text[], '{"news":["сеть запустила рекламную кампанию с участием","в эфире федеральных каналов вышел ролик бренда","в магазинах сети действует акция «Второе вино за полцены» до 30 ноября","реклама бренда появилась на билбордах","сеть продолжает кампанию в Telegram-каналах"],"business":["у нас сейчас идёт акция на игристое, до конца месяца","кампания заканчивается 15-го, потом будем думать дальше"],"chat":["у них сейчас реклама везде","акция идёт до конца месяца","ролик крутят по ТВ"],"terms":["«РК» (рекламная кампания)","промо","акция","ролик","наружка","таргет","посевы","библиотека объявлений"],"patterns":["«[компания] запустила / ведёт [кампанию]», «акция действует до [даты]», «[ролик / реклама] вышел в [медиа]»"]}'::jsonb, '[{"text":"«в марте запускаем новогоднюю кампанию»","code":"SIGNAL_CAMPAIGN_PLANNED"},{"text":"«маркетинговые расходы за год — 3 млрд ₽»","code":null},{"text":"«поддержите акцию бонусом за объём»","code":"PROMO_SUPPORT_REQUESTED"}]'::jsonb, '«В магазинах «Винотеки 24» до 30 ноября действует акция на вина Португалии, реклама идёт в Telegram-каналах.»', '«С 1 декабря «Винотека 24» запустит новогоднюю кампанию» → старт после даты материала, SIGNAL_CAMPAIGN_PLANNED.', 'Назовите, о чём кампания; для этой кампании, возможно, поздно, но это повод для контакта: спросить о следующих активностях и закупках под них; без предложения под текущую.', 4, 'fixed', 'chance', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Date gate: — (prompt rule: running now or ending soon relative to the item date; a start after the item date is `SIGNAL_CAMPAIGN_PLANNED`)
Relations: `SIGNAL_AGENCY_CHANGE` leads over it; split by date with `SIGNAL_CAMPAIGN_PLANNED`
Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_ACCOUNT_WIN', 'base', 'H', 'market', 'Агентство выиграло нового клиента', 'Агентство (рекламное, медийное, PR) выигрывает бюджет или тендер рекламодателя, и в тексте названо агентство-победитель. Код ставится и агентству, и рекламодателю — это одно событие с двух сторон. Если победа заменяет прежнее агентство или завершает тендер, дополнительно ставится SIGNAL_AGENCY_CHANGE.', 'Победитель — наш конкурент → COMPETITOR_NEW_CLIENT. Заказ, размещённый у нас → SALES_BOOKING_RECEIVED / ORDER_REQUESTED. Своя кампания рекламодателя → SIGNAL_CAMPAIGN_PLANNED / SIGNAL_AD_ACTIVITY. Дистрибьютор получил новую сеть или контракт на поставку (это не агентство) → COMPETITOR_NEW_CLIENT, PARTNER_NEW_CLIENT или нет сигнала.', ARRAY['выиграло тендер на обслуживание', 'бюджет бренда достался', 'будет вести бренд', 'новый клиент агентства', 'по итогам тендера выбран', 'стало ведущим агентством', 'получило бюджет', 'займётся продвижением бренда']::text[], '{"news":["агентство выиграло креативный тендер бренда","медийный бюджет сети достался агентству","агентство будет вести коммуникации бренда в 2027 году","бренд выбрал агентство по итогам тендера","агентство пополнило клиентский портфель"],"business":["мы выиграли тендер «Гастроном Плюс», с января ведём их digital","сообщаем, что наше агентство теперь отвечает за продвижение бренда"],"chat":["они взяли бюджет «Гастроном Плюс»","тендер выиграли","теперь ведут этот бренд"],"terms":["тендер","бюджет","AOR","лид-агентство","медиабаинг","креатив","PR"],"patterns":["«[агентство] выиграло [тендер / бюджет] [бренда]», «[бренд] выбрал [агентство]», «[агентство] будет вести [бренд] с [даты]»"]}'::jsonb, '[{"text":"«бюджет бренда выиграл «Альфа Медиа» (наш конкурент)»","code":"COMPETITOR_NEW_CLIENT"},{"text":"«бренд запускает кампанию»","code":"SIGNAL_CAMPAIGN_PLANNED"},{"text":"«сеть подписала с нами договор поставки»","code":"SALES_BOOKING_RECEIVED"}]'::jsonb, '«Агентство «Бета Коммуникации» выиграло тендер и с января 2027 года будет вести digital-продвижение сети «Гастроном Плюс»; бюджет — 60 млн ₽ в год.»', '«Сеть «Гастроном Плюс» запускает новогоднюю кампанию с агентством «Бета Коммуникации», которое ведёт её третий год» → кампания действующего агентства.', 'Пишите для стороны, которая наш клиент, и назовите вторую; агентство-клиент — узнать планы выигранного бюджета; рекламодатель-клиент — спросить, меняет ли новое агентство что-то для нас.', 5, 'fixed', 'chance', false, 'event', 'medium', true, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Relations: both with `SIGNAL_AGENCY_CHANGE`; when the winner is our competitor → `COMPETITOR_NEW_CLIENT` instead
Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_OPERATIONS_INVESTMENT', 'base', 'H', 'market', 'Инвестиции во внутреннюю деятельность', 'Компания покупает товары или услуги для своей работы — транспорт, склады, оборудование, ИТ, здания, энергию — без нового продукта, новой площадки для клиентов и без маркетингового бюджета. Одно событие с двух сторон: покупатель инвестирует, поставщик получает заказ; код ставится любой стороне, которая наш клиент.', 'Новый продукт или ассортимент → SIGNAL_PRODUCT_NEWS. Новая точка для клиентов → SIGNAL_EXPANSION. Партнёрство → SIGNAL_PARTNERSHIP. Покупка у НАС → заказ (ORDER_REQUESTED, SALES_BOOKING_RECEIVED). Инвестиции в связи с покупкой компании → SIGNAL_MERGER.', ARRAY['инвестирует в', 'закупила оборудование', 'построит распределительный центр', 'обновила автопарк', 'модернизирует', 'внедряет систему', 'новый склад', 'получила крупный заказ на поставку']::text[], '{"news":["сеть построит распределительный центр в Подмосковье","компания обновила автопарк рефрижераторов","ресторанная группа внедряет новую кассовую систему","ретейлер инвестирует 2 млрд ₽ в логистику","поставщик оборудования получил крупный заказ от сети"],"business":["мы переезжаем на новый склад, с декабря новый адрес приёмки","ставим новую систему учёта, возможны задержки в подтверждении заказов"],"chat":["склад новый строят","машины обновили","кассы меняют"],"terms":["«РЦ» (распределительный центр)","автопарк","ERP","WMS","капекс","модернизация"],"patterns":["«[компания] инвестирует [сумму] в [что]», «запускает / построит [объект]», «получила заказ на поставку [чего] для [компании]»"]}'::jsonb, '[{"text":"«запускаем собственную марку вина»","code":"SIGNAL_PRODUCT_NEWS"},{"text":"«открываем новый магазин»","code":"SIGNAL_EXPANSION"},{"text":"«закажите нам 50 коробок»","code":"ORDER_REQUESTED"}]'::jsonb, '«Сеть «Гастроном Плюс» вложит 1,5 млрд ₽ в новый распределительный центр в Домодедове, запуск в 2027 году.»', '«Сеть «Гастроном Плюс» открывает три новых магазина в Подмосковье» → площадки для покупателей, SIGNAL_EXPANSION.', 'Информационно для каждой стороны-клиента: одна строка — покупателю об инвестиции, поставщику о заказе; шаг — держать к разговору (например, спросить, меняется ли адрес и порядок приёмки).', 2, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_STRATEGY_CONTEXT', 'base', 'H', 'market', 'Контекст стратегии для будущего разговора', 'Компания делает стратегическое заявление, делится планом или участвует в обсуждении без названного последствия для маркетинга, бюджета или закупок: производство, площадки, организация, прогноз рынка, интервью о бизнесе. Полезно для следующего разговора, не повод для продажи.', 'Названо последствие для маркетинга, бюджета, ассортимента или поставщиков → SIGNAL_STRATEGY_ANNOUNCEMENT (или SIGNAL_CHANNEL_SHIFT). Спецификация, тендерная документация, КП — не заявление о стратегии. Конкретное событие со своим H-кодом → этот код.', ARRAY['в интервью рассказал', 'планы на ближайшие годы', 'видит будущее рынка', 'рассматривает варианты', 'стратегия развития', 'прогноз на следующий год', 'обсуждает перенос производства', 'оптимизирует структуру без сокращений']::text[], '{"news":["основатель ресторанной группы в интервью рассказал о планах","генеральный директор сети ожидает замедления рынка","компания рассматривает перенос производства","ретейлер обсуждает новую организационную структуру","прогноз компании на 2027 год"],"business":["в следующем году думаем о новых форматах, пока ничего конкретного","руководство обсуждает развитие, решения позже"],"chat":["гендир в подкасте рассказывал про планы","думают, куда расти","пока присматриваются"],"terms":["интервью","стратегия","прогноз","оргструктура","планы развития"],"patterns":["«[руководитель] рассказал о [планах]», «[компания] рассматривает [вариант]», «ожидает [тенденцию] в [периоде]»"]}'::jsonb, '[{"text":"«в следующем году сокращаем число поставщиков вина»","code":"SIGNAL_STRATEGY_ANNOUNCEMENT"},{"text":"«переносим бюджет в digital»","code":"SIGNAL_CHANNEL_SHIFT"},{"text":"«во вложении тендерная документация»","code":"SALES_TENDER_INVITATION"}]'::jsonb, '«Основатель «Северного ветра» в интервью рассказал, что группа рассматривает выход в загородный формат, но решение примут не раньше весны.»', '«Основатель «Северного ветра»: в 2027 году мы сократим число винных поставщиков с восьми до трёх» → названо последствие для закупок, SIGNAL_STRATEGY_ANNOUNCEMENT.', 'Повод для разговора: одна строка — что сказано и почему это может быть важно; шаг — при следующем контакте спросить, что это значит для их закупок; без предложения.', 2, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Relations: split with `SIGNAL_STRATEGY_ANNOUNCEMENT` (a named marketing / budget consequence)
Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_TRACKING_VENDOR_CHANGE', 'base', 'H', 'market', 'Смена поставщика аналитики или трекинга', 'Компания меняет агентство, которое ведёт её веб-аналитику и трекинг кампаний, или заменяет один внешний инструмент трекинга другим того же типа: менеджер тегов, веб-аналитика, сервис согласия на cookie, пиксели, коллтрекинг или сквозная аналитика (например, Google Tag Manager → другой менеджер тегов, Google Analytics → Яндекс Метрика, Calltouch → CoMagic). Сканирование сайта, где один инструмент исчез и появился другой, тоже считается.', 'Смена рекламного, медийного или PR-агентства → SIGNAL_AGENCY_CHANGE. Инструмент добавлен рядом со старым — нет сигнала. Полностью новый сайт → SIGNAL_REBRANDING. Аналитики нет совсем → SIGNAL_TRACKING_GAP.', ARRAY['сменили подрядчика по аналитике', 'перешли на Яндекс Метрику', 'внедрили сквозную аналитику', 'новый коллтрекинг', 'новое агентство по performance', 'перенастроили теги', 'серверный трекинг', 'новая плашка согласия на cookie']::text[], '{"business":["с декабря аналитику ведёт новое агентство","отказались от Google Analytics, теперь только Метрика","перешли с Calltouch на CoMagic","поменяли сервис согласий на cookie по 152-ФЗ"],"news":["бренд сменил performance-агентство","ретейлер внедрил сквозную аналитику Roistat","компания перешла на серверный трекинг"],"chat":["аналитику другим отдали","Метрику перенастраивают","коллтрекинг сменили"],"terms":["GTM","Яндекс Метрика","VK Пиксель","Top.Mail.ru","Roistat","Calltouch","CoMagic","сквозная аналитика","cookie-плашка","152-ФЗ"],"patterns":["«перешли с [инструмента] на [инструмент]», «[агентство] теперь ведёт [аналитику / трекинг]»"]}'::jsonb, '[{"text":"«сменили рекламное агентство»","code":"SIGNAL_AGENCY_CHANGE"},{"text":"«добавили VK Пиксель к Метрике»","code":null},{"text":"«запустили новый сайт»","code":"SIGNAL_REBRANDING"},{"text":"«на сайте нет никакой аналитики»","code":"SIGNAL_TRACKING_GAP"}]'::jsonb, '«С ноября сквозную аналитику «Винотеки 24» ведёт новое агентство, коллтрекинг переведён с Calltouch на CoMagic.»', '«На сайт «Винотеки 24» дополнительно поставили VK Пиксель» → инструмент добавлен, замены нет.', 'Называйте инструменты, если они названы, иначе — категорию; сканирование может ошибаться, не утверждайте смену как факт; неклиент — шанс предложить аудит, активный клиент — риск, узнать причину смены.', 5, 'fixed', 'chance', true, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Emitted by: both (text or website scan)
Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_TRACKING_GAP', 'base', 'H', 'market', 'Пробел в аналитике сайта', 'На сайте компании нет веб-аналитики (ни Яндекс Метрики, ни другой системы) и / или нет инструмента согласия на обработку cookie и персональных данных; это видно на двух сканированиях подряд. Повод предложить настройку аналитики.', 'Один инструмент заменён другим → SIGNAL_TRACKING_VENDOR_CHANGE. Сайт недоступен или в разработке — нет сигнала. Одно сканирование без повтора — нет сигнала. Сообщение в тексте письма о том, что аналитики нет, — этот код из текста не ставится.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, '«Сканирование сайта vinoteka24.example 03.11 и 10.11: систем веб-аналитики не найдено, плашки согласия на cookie нет.»', '«Сканирование 10.11: Google Analytics не найден, найдена Яндекс Метрика» → инструмент заменён, это SIGNAL_TRACKING_VENDOR_CHANGE.', 'Назовите, чего не нашло сканирование; шаг — сначала проверить сайт самому, потом узнать у контакта клиента, как они измеряют результаты; без упрёка.', 4, 'fixed', 'chance', false, 'event', 'medium', false, false, false, 'process', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, '{"ru":"Данные — автоматическое сканирование главной страницы и одной внутренней страницы сайта компании из карточки клиента. Условие — на двух сканированиях подряд с интервалом не меньше 7 дней не найдено ни одной системы веб-аналитики (Яндекс Метрика, Google Analytics, Top.Mail.ru / VK Пиксель, Matomo) и / или нет плашки согласия на cookie. Минимум данных — сайт отвечает кодом 200 на обоих сканированиях. Запуск — еженедельно. Повтор — не раньше 90 дней на компанию и код. Сайт с аналитикой, которая грузится только после согласия, сканер может пропустить — карточка просит проверить вручную.","en":"Data — an automatic scan of the home page and one inner page of the company website from the client card. Condition — two scans in a row at least 7 days apart find no web-analytics system (Yandex Metrica, Google Analytics, Top.Mail.ru / VK Pixel, Matomo) and / or no cookie-consent banner. Minimum data — the site returns HTTP 200 on both scans. Run — weekly. Cooldown — 90 days per company + code. Analytics that loads only after consent can be missed; the card asks for a manual check."}'::jsonb, 'Emitted by: process (deterministic website scan; never read from text)
Closed by: — (a later scan that finds the tools stops repeats)
Relevance window: one instance per company and gap; cooldown 90 days per company + code
Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_CAMPAIGN_PLANNED', 'base', 'H', 'market', 'Запланирована кампания', 'Компания объявляет или планирует кампанию, промоакцию, запуск с продвижением или медиаплан, которые ещё не начались: дата старта позже даты материала, кампания в производстве, тендер на кампанию. Бюджет ещё не размещён. Для HoReCa и розницы — сезонная винная акция, новогодняя или праздничная промо, винный фестиваль в сети.', 'Кампания уже идёт или заканчивается → SIGNAL_AD_ACTIVITY. Только новый продукт без кампании → SIGNAL_PRODUCT_NEWS. Клиент просит нас поддержать акцию (бонус, POS, промо) → PROMO_SUPPORT_REQUESTED (distribution). Конкурент у клиента → SIGNAL_COMPETITOR.', ARRAY['планирует кампанию', 'стартует в декабре', 'готовим акцию к', 'с 1 марта запустим', 'скоро стартует', 'в производстве ролик', 'медиаплан на', 'тендер на кампанию']::text[], '{"news":["сеть с 1 декабря запустит новогоднюю кампанию","бренд готовит масштабную кампанию к запуску","ретейлер объявил тендер на проведение весенней кампании","ролик уже снимают, выход в феврале"],"business":["в декабре у нас будет большая акция на игристое, планируем объёмы","готовим весенний винный фестиваль во всех магазинах, старт 1 апреля","к 8 Марта делаем промо"],"chat":["к Новому году готовят акцию","скоро запуск кампании","съёмки ролика на следующей неделе"],"terms":["РК","медиаплан","промо","запуск","старт","сезонная акция","ко дню"],"patterns":["«[компания] запустит [кампанию] с [даты]», «готовим [акцию] к [поводу]», «старт [кампании] запланирован на [дату]»"]}'::jsonb, '[{"text":"«акция идёт до конца месяца»","code":"SIGNAL_AD_ACTIVITY"},{"text":"«выпускаем новую марку» (без кампании)","code":"SIGNAL_PRODUCT_NEWS"},{"text":"«под акцию нужен ретро-бонус от вас»","code":"PROMO_SUPPORT_REQUESTED"}]'::jsonb, '«С 1 декабря во всех 40 магазинах «Винотеки 24» стартует новогодняя акция на шампанское и игристые вина.»', '«В магазинах «Винотеки 24» сейчас идёт акция на игристое, последняя неделя» → кампания уже идёт, SIGNAL_AD_ACTIVITY.', 'Бюджет ещё не размещён: шаг — связаться с контактом клиента, узнать сроки, объёмы и позиции под кампанию, и только потом предложить подборку; назовите кампанию и дату старта.', 5, 'fixed', 'chance', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Date gate: — (prompt rule: the start is after the item date, or the campaign is in production / about to start)
Relations: split by date with `SIGNAL_AD_ACTIVITY`; both with `SIGNAL_PRODUCT_NEWS` when the launch campaign is named
Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_ANNIVERSARY_PLAIN', 'base', 'H', 'market', 'Юбилей без коммуникационной активности', 'Материал только сообщает о юбилее компании или заведения; кампания, специальные продукты, событие или акция к юбилею не названы.', 'Названа активность к юбилею (вечер, меню, акция, серия) → SIGNAL_ANNIVERSARY. Дата основания в справке о компании без повода — нет сигнала. Юбилей сотрудника — нет сигнала.', ARRAY['исполнилось 10 лет', 'отмечает юбилей', 'празднует годовщину', 'работает с 2006 года', '20 лет на рынке', 'юбилей компании', 'годовщина открытия', 'десятилетие']::text[], '{"news":["ресторану «Северный ветер» исполнилось 15 лет","сеть отмечает 20-летие","компании четверть века","бар празднует пятую годовщину"],"business":["в этом месяце нам 10 лет","у нас юбилей, спасибо, что вы с нами"],"chat":["им десятка","у них юбилей","пятнадцать лет уже"],"terms":["юбилей","годовщина","N лет на рынке"],"patterns":["«[компании] исполнилось [N лет]», «[компания] отмечает [N-летие]»"]}'::jsonb, '[{"text":"«к юбилею готовим гала-ужин и спецкарту»","code":"SIGNAL_ANNIVERSARY"},{"text":"«компания основана в 2006 году» (справка)","code":null},{"text":"«у нашего сомелье 10 лет в профессии»","code":null}]'::jsonb, '«В ноябре ресторану «Северный ветер» исполняется 15 лет.»', '«В ноябре ресторану «Северный ветер» исполняется 15 лет, к дате готовят юбилейное меню и винный вечер» → активность названа, SIGNAL_ANNIVERSARY.', 'Информационно: держать к следующему разговору и тогда спросить, планируется ли что-то к дате; без контакта, поздравления как задачи и предложения.', 2, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Relations: split with `SIGNAL_ANNIVERSARY` (communication named)
Deal effect: per org rule; usual: none', NULL, NULL),
  ('SIGNAL_EVENT_UPCOMING', 'base', 'H', 'market', 'Предстоит участие компании в событии', 'Компания будет участвовать в выставке, конференции, фестивале или отраслевом событии как экспонент, спикер или партнёр, и событие проходит после даты материала. Повод встретиться.', 'Событие прошло или дата не указана → SIGNAL_EVENT. Компания — спонсор → SIGNAL_SPONSORING. Клиент приглашает нас на встречу или дегустацию к себе → блок F (MEETING_*) или TASTING_REQUESTED. Наше участие — нет сигнала.', ARRAY['примет участие в выставке', 'будет на форуме', 'приглашаем на наш стенд', 'выступит на конференции', 'стенд №', 'ждём вас на', 'участвуем в фестивале в', 'в программе форума']::text[], '{"news":["сеть представит новинки на выставке в феврале","основатель ресторанной группы выступит на гастрономическом форуме","бар примет участие в винном фестивале 12–14 декабря","компания объявила об участии в отраслевой выставке"],"business":["в феврале будем на выставке, стенд B-12, заходите","я выступаю на форуме ретейла 3 декабря, увидимся там?"],"chat":["они в феврале на выставке будут","на фесте у них свой бар будет","едут на форум"],"terms":["выставка","стенд","экспонент","спикер","форум","фестиваль","деловая программа"],"patterns":["«[компания] примет участие в [событии] [дата]», «приглашаем на стенд [номер]», «[руководитель] выступит на [событии]»"]}'::jsonb, '[{"text":"«по итогам выставки подписали соглашения»","code":"SIGNAL_EVENT"},{"text":"«станем генеральным спонсором фестиваля»","code":"SIGNAL_SPONSORING"},{"text":"«приезжайте к нам в ресторан на дегустацию в четверг»","code":"TASTING_REQUESTED"}]'::jsonb, '«Ресторанная группа «Северный ветер» представит новый проект на гастрономическом фестивале 12–14 декабря в Москве.»', '«Ресторанная группа «Северный ветер» представила новый проект на прошедшем фестивале» → событие прошло, SIGNAL_EVENT.', 'Назовите событие и дату; шаг — до события договориться с контактом клиента о встрече на площадке и там узнать потребности; без предложения до встречи.', 3, 'fixed', 'chance', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'relationship', '{}'::text[], NULL, NULL, NULL, 'Date gate: — (prompt rule: the event date is after the item date)
Relevance window: until the event date
Relations: split by date with `SIGNAL_EVENT`
Deal effect: per org rule; usual: none', NULL, NULL),
  ('MAILERDEMON_RECEIVED', 'base', 'I', 'contact', 'Письмо не доставлено', 'Почтовая система возвращает уведомление о том, что наше письмо клиенту не доставлено: адрес не существует, ящик переполнен, домен не найден, письмо отклонено. Оценка берётся у открытой карточки недоставленного письма; если её нет — 5.', 'Автоответ об отпуске → CONTACT_OOO. Письмо доставлено, но клиент не ответил → SALES_OFFER_NO_RESPONSE или нет сигнала. Временная задержка доставки с повторной попыткой («доставка отложена») — нет сигнала, пока нет окончательного отказа. Недоставка рассылки, не адресованной клиенту лично, — нет сигнала. Клиент пишет, что сменил адрес → CONTACT_NEW_KNOWN_ORG / обновление контакта, не этот код.', ARRAY['Недоставленное сообщение', 'Не удалось доставить сообщение', 'Сообщение не доставлено', 'Ошибка доставки', 'Возвращённое письмо', 'адрес не существует', 'Mail Delivery Subsystem', 'Undelivered Mail Returned to Sender']::text[], '{"system_ru":["Недоставленное сообщение","Не удалось доставить сообщение следующим получателям","Сообщение не доставлено","Ошибка доставки почты","Возвращённое письмо","Почтовый ящик получателя не существует","Ящик получателя переполнен","Сообщение отклонено сервером получателя","Адрес электронной почты не найден"],"system_en":["Undelivered Mail Returned to Sender","Delivery Status Notification (Failure)","Mail delivery failed: returning message to sender","Address not found","550 5.1.1 User unknown","Mailbox full","Recipient address rejected"],"senders":["MAILER-DAEMON","Mail Delivery Subsystem","postmaster","mailer-daemon@yandex.ru","mailer-daemon@corp.mail.ru"],"terms":["DSN","баунс","550","5.1.1","5.2.2","NDR"],"patterns":["тема с «Недоставленное» / «Undeliverable» / «Delivery Status Notification» и вложение с исходным письмом (message/rfc822 или message/delivery-status)"]}'::jsonb, '[{"text":"«Автоответ: нахожусь в отпуске до 20.11»","code":"CONTACT_OOO"},{"text":"«Delivery Status Notification (Delay): повторная попытка»","code":null},{"text":"«я больше не работаю в компании, пишите на новый адрес»","code":"CONTACT_LEAVING"},{"text":"«отписаться от рассылки»","code":null}]'::jsonb, '«Не удалось доставить сообщение следующим получателям: zakupki@severveter.example — 550 5.1.1 Почтовый ящик не существует.»', '«Автоматический ответ: я в отпуске до 20 ноября, по срочным вопросам пишите Ольге» → это CONTACT_OOO.', 'Назовите адрес и тему недоставленного письма; шаг — отправителю: найти рабочий адрес или другой канал (телефон, мессенджер) и отправить письмо повторно, особенно если это КП, счёт или подтверждение заказа.', 5, 'inherited', 'risk', false, 'event', 'quick', false, false, true, 'both', 'active', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Display profile: inherited from the open card of the bounced mail; fallback 5 → D4 (Maslov D4)
Profile (summary): inherited; fallback D4
Emitted by: both (v204); in this design the deterministic bounce detector (spec §5.2 gate 5) emits it without the LLM, with `facts.bouncedMessageIds`
Closed by: — (a later successful send to a corrected address ends the topic manually)
Relations: attaches to the topic of the bounced mail
Deal effect: per org rule; usual: none', NULL, NULL),
  ('TEAM_HANDOVER', 'base', 'J', 'team', 'Передача аккаунта между коллегами', 'Коллега сообщает, что клиент (аккаунт, сеть, регион) переходит от одного менеджера к другому: увольнение, отпуск по уходу, перераспределение клиентов, новая зона ответственности. Само по себе не негативное событие.', 'Временная замена на время отпуска или болезни → TEAM_CAPACITY. Смена контактного лица на стороне клиента → CONTACT_LEAVING / CONTACT_NEW_KNOWN_ORG. Письмо клиенту «теперь вашим менеджером будет Андрей» от нас наружу — внешний элемент, блок J на нём отбрасывается.', ARRAY['передаю клиента', 'передаю тебе аккаунт', 'с понедельника сеть ведёт', 'теперь за клиентом закреплён', 'забираешь моих клиентов', 'перераспределили клиентов', 'зона ответственности меняется', 'введи в курс по клиенту']::text[], '{"business":["прошу принять клиента в работу","с 01.12 ответственным менеджером по клиенту назначается","в связи с моим уходом передаю клиентов","передача дел по клиенту","акт передачи клиентской базы","закрепить клиента за","смена ответственного менеджера"],"chat":["забирай Ромашку","теперь ты ведёшь Азбуку","я ухожу, мои рестораны делим так","кидаю тебе контакты по сети","введу тебя в курс по клиенту","с понедельника это твой клиент"],"terms":["КАМ","аккаунт","ответственный","ЛПР клиента","клиентская база"],"patterns":["«передаю / передаём» + клиента / аккаунт / сеть","«теперь ведёт / отвечает» + имя коллеги","«закреплён за» + коллега"]}'::jsonb, '[{"text":"«подмени меня на время отпуска»","code":"TEAM_CAPACITY"},{"text":"«наш сомелье у клиента сменился»","code":"CONTACT_NEW_DECISION_MAKER"},{"text":"«Ирина больше не работает в ресторане»","code":"CONTACT_LEAVING"}]'::jsonb, '«Коллеги, с 1 декабря сеть "Винотека на Садовой" передаю Андрею, все договорённости по скидке и отсрочке в карточке клиента.»', '«Андрей, подстрахуй меня по "Винотеке" на две недели, я в отпуске» → временная замена, это TEAM_CAPACITY.', 'Назвать клиента и нового ответственного по роли; шаг — новому менеджеру представиться клиенту и сверить открытые вопросы (заказы, счета, договорённости).', 7, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'gated', NULL, 'team', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual effect: none (the deal owner changes in the CRM by hand, not by the signal)', NULL, NULL),
  ('TEAM_ESCALATION', 'base', 'J', 'team', 'Внутренняя эскалация по клиенту', 'Коллега внутри компании поднимает проблему по клиенту на уровень выше (руководителю, другому отделу), часто без ведома ответственного менеджера: клиент недоволен, грозит уйти, есть конфликт.', 'Клиент сам пишет нашему руководителю или ставит его в копию → COMPLAINT_ESCALATED. Обычная внутренняя просьба помочь с заказом без проблемы клиента → нет сигнала.', ARRAY['эскалирую', 'клиент очень недоволен', 'нужна твоя помощь с клиентом', 'грозятся уйти к другому поставщику', 'надо срочно разобраться с', 'подключи руководителя', 'ситуация выходит из-под контроля', 'звонил директор ресторана, ругался']::text[], '{"business":["довожу до вашего сведения ситуацию с клиентом","прошу подключиться к вопросу","выношу вопрос на уровень коммерческого директора","требуется решение руководства","клиент выражает серьёзное недовольство"],"chat":["там с Ромашкой полный трэш","клиент рвёт и мечет","Саша, глянь срочно, у нас пожар по сети","они говорят, что уйдут","подключись, я не вытягиваю"],"terms":["эскалация","ЛПР","коммерческий","«КД» (коммерческий директор)"],"patterns":["«эскалирую / поднимаю вопрос» + клиент","«клиент недоволен» + «внутр.»","«нужно решение» + руководитель"]}'::jsonb, '[{"text":"письмо клиента с копией нашему директору","code":"COMPLAINT_ESCALATED"},{"text":"«клиент спросил про отсрочку, что ответить?»","code":null}]'::jsonb, '«Олег Викторович, эскалирую: у "Гастробара 12" третья недовозка за месяц, управляющий сказал, что со следующего месяца переходят к другому поставщику.»', '«Олег Викторович, клиент просит отгрузку в субботу, согласуем?» → рабочий вопрос без конфликта, нет сигнала.', 'Назвать клиента и суть проблемы; шаг — ответственному менеджеру связаться с коллегой, который эскалировал, и согласовать один ответ клиенту.', 6, 'fixed', 'risk', false, 'event', 'medium', false, false, false, 'both', 'gated', NULL, 'team', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual effect: risk trigger (client dissatisfied)', NULL, NULL),
  ('TEAM_INSIDER', 'base', 'J', 'team', 'Коллега поделился важным контекстом клиента', 'Коллега во внутренней переписке сообщает о клиенте то, чего нет в переписке с клиентом: планы, слухи с рынка, смену собственника, договорённости с конкурентом. По сути нейтрально.', 'Событие, которое видно из письма самого клиента, кодируется кодом этого события (например, CONTACT_LEAVING). Новость из СМИ → коды блока H. Проблема клиента, которую коллега эскалирует → TEAM_ESCALATION.', ARRAY['между нами', 'по моей информации', 'слышал от знакомого', 'неофициально', 'имей в виду, что', 'они собираются', 'мне шепнули', 'на рынке говорят']::text[], '{"business":["для информации: по нашим данным","неофициально стало известно","учтите при переговорах","конфиденциально, не для клиента"],"chat":["чисто между нами","слышал на дегустации, что они","мне шепнули","на рынке говорят","знакомый сомелье сказал","имей в виду"],"terms":["инсайд","по секрету","НДА не нарушаю"],"patterns":["«по моей информации» + клиент + план","«они собираются / планируют» + действие"]}'::jsonb, '[{"text":"«клиент написал, что уходит сомелье»","code":"CONTACT_LEAVING"},{"text":"статья о закрытии ресторана","code":"SIGNAL_DOWNSIZING"}]'::jsonb, '«Имей в виду: по моей информации, "Бистро Лаванда" в январе меняет собственника и будет пересматривать всех поставщиков.»', '«Бистро Лаванда прислали заказ на пятницу» → рабочее сообщение, нет сигнала.', 'Кратко передать контекст и источник (по роли); шаг — держать в виду к следующему разговору с клиентом, не ссылаться на источник.', 5, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'gated', NULL, 'team', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual effect: none', NULL, NULL),
  ('TEAM_DEAL_LOST', 'base', 'J', 'team', 'Коллега сообщил о проигрыше', 'Коллега сообщает, что мы проиграли сделку, тендер или ввод в ассортимент у похожего клиента, и называет причину (цена, условия оплаты, ассортимент, конкурент).', 'Отказ, полученный от самого клиента → SALES_OFFER_DECLINED. Победа → TEAM_DEAL_WON. Сообщение без связи с клиентским сегментом, без причины и без клиента → нет сигнала.', ARRAY['проиграли тендер', 'не взяли нас', 'выбрали другого поставщика', 'цена выше на', 'не прошли по условиям оплаты', 'ушли к конкуренту', 'отказали в листинге', 'причина отказа']::text[], '{"business":["по итогам тендера победил другой участник","наше предложение не принято","причина — цена выше рынка на","клиент выбрал поставщика с отсрочкой 60 дней","в ввод в ассортимент отказано"],"chat":["слили сеть","пролетели с тендером","проиграли тендер, цена выше на 7 %","Винный Альянс дал дешевле","не взяли нас, говорят, нет нужных позиций"],"terms":["тендер","листинг","ввод","НМЦК","отсрочка"],"patterns":["«проиграли / не взяли / отказали» + причина"]}'::jsonb, '[{"text":"«клиент пишет: ваше предложение нам не подходит»","code":"SALES_OFFER_DECLINED"},{"text":"«выиграли тендер у отеля»","code":"TEAM_DEAL_WON"}]'::jsonb, '«Коллеги, проиграли тендер гостиничной группы: цена выше на 7 %, победил дистрибьютор с отсрочкой 45 дней.»', '«Тендер гостиничной группы перенесли на январь» → нет проигрыша, нет сигнала.', 'Назвать сегмент, причину и конкурента по роли; шаг — проверить, не грозит ли та же причина нашим похожим клиентам.', 5, 'fixed', 'risk', false, 'event', 'medium', false, false, false, 'both', 'gated', NULL, 'team', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual effect: none (the lost deal is about a similar client, not the one on the card)', NULL, NULL)
ON CONFLICT DO NOTHING;
--> statement-breakpoint
INSERT INTO "signal_category" ("code", "pack_code", "block_code", "family", "label_ru", "definition_ru", "boundary_ru", "cues_prompt_ru", "synonyms_ru", "anti_cues_ru", "example_ru", "counter_example_ru", "card_note_ru", "weight", "score_rule", "class", "class_by_relation", "kind", "effort", "carries_amount", "asks_us", "inbound_only", "emitted_by", "stage", "display_profile", "recipient_role", "closes_codes", "date_gate", "relevance_days", "trigger_rule", "note_ru", "retired_at", "successor_code") VALUES
  ('TEAM_CAPACITY', 'base', 'J', 'team', 'Нехватка ресурсов или необходимость замены', 'Коллега сообщает, что он или другой сотрудник будет недоступен (отпуск, больничный, командировка, перегрузка), и просит замену или объявляет, кто подменяет.', 'Постоянная передача клиентов → TEAM_HANDOVER. Автоответ клиента «я в отпуске» → CONTACT_OOO. Наш собственный автоответ → нет сигнала (автоматическое письмо).', ARRAY['подменишь', 'на больничном до', 'в отпуске с', 'меня не будет', 'кто подстрахует', 'не успеваю', 'завал', 'нужна замена']::text[], '{"business":["на период моего отсутствия вопросы решает","прошу назначить замещающего","буду в командировке с 10 по 14","не хватает ресурса на отгрузки","склад перегружен"],"chat":["подменишь меня по Ромашке?","я на больничном до среды","кто возьмёт мои заявки?","я не успеваю, помогите","у нас завал"],"terms":["замещающий","и.о.","больничный","отпуск"],"patterns":["«меня не будет / я в отпуске / на больничном» + срок","«подменишь / подстрахуешь» + клиент"]}'::jsonb, '[{"text":"«передаю клиента насовсем»","code":"TEAM_HANDOVER"},{"text":"«Автоответ: нахожусь в отпуске» от клиента","code":"CONTACT_OOO"}]'::jsonb, '«Я на больничном до 20.11, Марина, подменишь по моим ресторанам? Заказы на пятницу уже в системе.»', '«Марина, с декабря ты ведёшь мои рестораны насовсем» → TEAM_HANDOVER.', 'Назвать, кто недоступен, до какой даты и кто подменяет; шаг — убедиться, что открытые заказы и вопросы клиентов не останутся без ответа.', 4, 'fixed', 'risk', false, 'event', 'medium', false, false, false, 'both', 'gated', NULL, 'team', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual effect: none', NULL, NULL),
  ('TEAM_DEAL_WON', 'base', 'J', 'team', 'Коллега сообщил о победе', 'Коллега сообщает о выигранной сделке, тендере или вводе в ассортимент у похожего клиента — повод повторить подход у своих клиентов.', 'Заказ или подтверждение от самого клиента → SALES_BOOKING_RECEIVED / ORDER_REQUESTED. Проигрыш → TEAM_DEAL_LOST.', ARRAY['выиграли тендер', 'зашли в сеть', 'взяли в карту', 'подписали договор поставки', 'нас выбрали', 'закрыли сделку', 'ввели в ассортимент', 'дожали']::text[], '{"business":["по итогам тендера наше предложение признано лучшим","подписан договор поставки с","наши позиции введены в ассортимент","согласован листинг"],"chat":["ура, зашли в сеть!","нас взяли в винную карту","дожали отель","закрыли сделку с Ромашкой","победа по тендеру"],"terms":["листинг","ввод","СТМ","тендер"],"patterns":["«выиграли / взяли / зашли / подписали» + клиент + условия"]}'::jsonb, '[{"text":"«клиент прислал заказ на 20 коробок»","code":"ORDER_REQUESTED"},{"text":"«тендер ещё идёт»","code":null}]'::jsonb, '«Коллеги, зашли в карту "Гриль-бара Север" с тремя позициями игристого — помогла дегустация для персонала.»', '«Север просит образцы игристого» → SAMPLES_REQUESTED, это не победа.', 'Назвать клиента-пример, сегмент и что сработало; шаг — проверить, каким нашим похожим клиентам подходит тот же подход.', 3, 'fixed', 'chance', false, 'event', 'medium', false, false, false, 'both', 'gated', NULL, 'team', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual effect: none (the won deal is about a similar client)', NULL, NULL),
  ('ACCOUNT_REVENUE_STAGNATION', 'base', 'K', 'account', 'Стагнация выручки по клиенту', 'Выручка по клиенту за несколько лет не растёт: хотя бы в одном из последних трёх полных календарных лет она упала на заданный порог или больше, и последние 12 месяцев не выше лучшего из этих лет.', 'Текущее падение последних 12 месяцев к прошлому году → ACCOUNT_REVENUE_DECLINE_YOY (он ведёт). Клиент совсем перестал заказывать → ACCOUNT_DORMANT. Разовое падение одного года на фоне общего роста — не стагнация.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, '«выручка 2023: 2,1 млн ₽; 2024: 1,9 млн ₽ (−10 %); 2025: 2,0 млн ₽; последние 12 мес.: 1,95 млн ₽»', '«выручка 2024: 1,5 млн ₽; 2025: 1,9 млн ₽ (+27 %)» → рост, не стагнация.', 'Напиши, что клиент годами не растёт у нас, и предложи менеджеру при следующем контакте узнать планы клиента и чем мы можем помочь расти, без ценового предложения первым шагом.', 5, 'fixed', 'risk', false, 'trend', 'medium', false, false, false, 'process', 'onHold', NULL, 'account', '{}'::text[], NULL, NULL, '{"ru":"Данные — подтверждённые и завершённые заказы клиента по годам. Окно — три последних полных календарных года + скользящие 12 полных месяцев. База — выручка предыдущего года для каждого из трёх лет. Минимум данных — заказы в каждом из четырёх последних календарных лет и выручка лучшего года не ниже `cards.revenueTrendMinRub` (предложение: 100 000 ₽). Порог — падение год к году не меньше `cards.revenueStagnationThresholdPct` (предложение: 5 %) хотя бы в одном из трёх лет, и выручка последних 12 месяцев не выше лучшего года больше чем на `cards.revenueGrowthThresholdPct` (10 %). Запуск — ежемесячно, 3-го числа, 07:00. Повтор — не раньше `cards.trendCooldownDays` (90 дней) по клиенту и коду. Если в том же запуске срабатывает `ACCOUNT_REVENUE_DECLINE_YOY`, этот код идёт в карточку только как контекст. - Evidence format: «выручка 2024: 1,8 млн ₽; 2025: 1,6 млн ₽ (−11 %); последние 12 мес.: 1,7 млн ₽».","en":"Data = the client''s confirmed + finalized orders per calendar year. Window = the last 3 full calendar years + the rolling last 12 full months. Baseline = the previous year for each of the 3 years. Minimum data = orders in each of the last 4 calendar years and best-year revenue ≥ `cards.revenueTrendMinRub` (proposed 100 000 RUB). Threshold = a year-on-year drop ≥ `cards.revenueStagnationThresholdPct` (proposed 5 %) in at least one of the 3 years, and the last 12 months not more than `cards.revenueGrowthThresholdPct` (10 %) above the best year. Run monthly, day 3, 07:00. Cooldown 90 days per client + code."}'::jsonb, 'Display profile: from weight (D4); trend ceiling D4
Profile (summary): D4 (trend ceiling D4)
Closed by: — (expires; a later `ACCOUNT_REVENUE_GROWTH_YOY` is a change of direction)
Relations: `ACCOUNT_REVENUE_DECLINE_YOY` leads over this code (the current loss leads; the stagnation is context)
Deal effect: per org rule; usual: none', NULL, NULL),
  ('ACCOUNT_REVENUE_DECLINE_YOY', 'base', 'K', 'account', 'Снижение выручки по клиенту год к году', 'Клиент покупает у нас заметно меньше: выручка за последние 12 полных месяцев ниже, чем за те же 12 месяцев год назад, на порог или больше. Клиент при этом продолжает заказывать.', 'Клиент не заказывает дольше своего ритма → ACCOUNT_DORMANT (не этот код). Перестал брать отдельную позицию, а общий объём держится → ACCOUNT_PRODUCT_STOPPED. Клиент сам написал, что выводит наши позиции из карты или ассортимента → DELISTING_RISK (пакет distribution). Падение ниже порога или на малой базе — нет сигнала. Отмена конкретного заказа в письме → SALES_BOOKING_CANCELLED (он ведёт).', '{}'::text[], '{}'::jsonb, '[]'::jsonb, '«выручка за 12 мес. (11.2025–10.2026): 840 тыс. ₽; за 11.2024–10.2025: 1,15 млн ₽ (−27 %); заказов 11 против 17»', '«выручка за 12 мес.: 1,02 млн ₽; год назад: 1,10 млн ₽ (−7 %)» → ниже порога 15 %, сигнала нет.', 'Напиши, что клиент покупает у нас меньше, чем год назад (цифры и период), и предложи менеджеру связаться с закупщиком или сомелье клиента (по роли), чтобы узнать причину и планы, пока следующий период открыт; ценовое предложение только после этого.', 5, 'fixed', 'risk', false, 'trend', 'medium', false, false, false, 'process', 'active', NULL, 'account', '{}'::text[], NULL, NULL, '{"ru":"Данные — подтверждённые и завершённые заказы клиента, сумма за вычетом скидки клиента. Окно — последние 12 полных месяцев (скользящие; сезонность, например декабрьский пик, так выравнивается). База — те же 12 месяцев годом раньше. Минимум данных — первый заказ клиента не позже чем за 24 месяца до запуска, в базовом периоде не меньше 3 заказов и выручка базы не ниже `cards.revenueTrendMinRub` (предложение: 100 000 ₽). Порог — падение не меньше `cards.revenueDeclineThresholdPct` (предложение: 15 %) и не меньше `cards.revenueDeclineMinRub` (предложение: 100 000 ₽) в рублях. Не создавать, если в текущем окне нет ни одного заказа или по клиенту открыт `ACCOUNT_DORMANT` — это случай «перестал покупать». Запуск — ежемесячно, 3-го числа, 07:00. Повтор — не раньше `cards.trendCooldownDays` (90 дней) по клиенту и коду; смена направления (рост) создаёт новую карточку сразу. - Evidence format: «выручка за 12 мес. (11.2025–10.2026): 1,2 млн ₽; год назад: 1,6 млн ₽ (−25 %, −400 тыс. ₽); заказов 9 против 14».","en":"Data = the client''s confirmed + finalized orders, net of the client discount. Window = the last 12 full months (rolling; this evens out seasonality such as the December peak). Baseline = the same 12 months one year earlier. Minimum data = first order ≥ 24 months before the run, ≥ 3 orders in the baseline, baseline revenue ≥ `cards.revenueTrendMinRub` (proposed 100 000 RUB). Threshold = decline ≥ `cards.revenueDeclineThresholdPct` (proposed 15 %) AND ≥ `cards.revenueDeclineMinRub` (proposed 100 000 RUB). Skip when the window has no order or `ACCOUNT_DORMANT` is open for the client. Run monthly, day 3, 07:00. Cooldown 90 days per client + code; a change of direction makes a new card at once."}'::jsonb, 'Display profile: from weight (D4); trend ceiling D4
Profile (summary): D4 (trend ceiling D4)
Closed by: — (expires; a later `ACCOUNT_REVENUE_GROWTH_YOY` makes a new card at once)
Relations: leads over `ACCOUNT_REVENUE_STAGNATION`; `SALES_BOOKING_CANCELLED` leads over this code (one cancellation card, the decline is context in it)
Deal effect: per org rule; usual: risk trigger «Клиент покупает меньше» on an open supply-agreement / listing deal of this client; no stage move', NULL, NULL),
  ('ACCOUNT_DORMANT', 'base', 'K', 'account', 'Клиент перестал покупать', 'Клиент раньше регулярно покупал у нас (лучший год не ниже порога), но не сделал заказ в пределах своего обычного ритма, и вперёд ничего не заказано. Пауза длиннее ритма — риск потерять клиента; длиннее двух ритмов — клиент «затих», информационная карточка.', 'Клиент заказывает, но меньше → ACCOUNT_REVENUE_DECLINE_YOY. Не берёт одну позицию, а другие заказывает → ACCOUNT_PRODUCT_STOPPED. Нет вообще никакого контакта с бывшим клиентом или лидом → ACCOUNT_REACTIVATION_DUE. Клиент сам написал «больше не будем брать» → DELISTING_RISK или CONTRACT_TERMINATED. Есть заказ в статусе draft или awaiting_client — сигнала нет.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, '«последний заказ 02.08.2026; обычный ритм 21 день (средний интервал по 18 заказам); пауза 92 дня; лучший год 2025: 960 тыс. ₽»', '«последний заказ 20.10.2026; обычный ритм 30 дней; пауза 22 дня» → пауза короче ритма, сигнала нет.', 'Это возврат клиента, а не жалоба: назови, что и когда клиент заказывал в последний раз, его обычный ритм и лучший год; при риске предложи связаться с закупщиком клиента (по роли) и узнать причину и планы, при «затих» — сохранить к следующему разговору, без ценового предложения первым шагом.', 5, 'fixed', 'risk', false, 'watchdog', 'medium', false, false, false, 'process', 'active', NULL, 'account', '{}'::text[], NULL, NULL, '{"ru":"Данные — даты подтверждённых и завершённых заказов клиента (`order.order_date`). Ритм (v204): 3 и больше заказов — средний интервал между ними; 2 заказа — этот один интервал; 1 заказ — 12 месяцев; ритм не короче `cards.dormantRhythmFloorDays` (v204: 3 месяца = 90 дней). Минимум данных — лучший календарный год клиента у нас не ниже `cards.dormantMinBestYearRub` (предложение: 300 000 ₽; в v204 — 20 000 €). «Вперёд ничего не заказано» — у клиента нет заказа в статусе `draft`, `awaiting_client` или `confirmed` с датой после последнего заказа. Порог — пауза от последнего заказа до даты запуска больше ритма → risk; больше двух ритмов → fyi. Запуск — ежемесячно, 3-го числа, 07:00. Одна карточка на клиента и последний заказ: пока последний заказ тот же, новая карточка не создаётся (кулдаун 90 дней не нужен). Новый заказ закрывает вопрос. - Distributor proposal (open point): rhythm = the MEDIAN gap of the last 12 months (HoReCa orders weekly; one old gap must not stretch the average), floor 21 days instead of 90. - Evidence format: «последний заказ 14.03.2026; обычный ритм 30 дней; пауза 230 дней; лучший год 2025: 1,4 млн ₽».","en":"Data = dates of the client''s confirmed + finalized orders (`order.order_date`). Rhythm (v204): ≥ 3 orders → the average gap; 2 orders → that one gap; 1 order → 12 months; never shorter than `cards.dormantRhythmFloorDays` (v204: 3 months = 90 days). Minimum data = best calendar year with us ≥ `cards.dormantMinBestYearRub` (proposed 300 000 RUB; v204 uses EUR 20 000). Nothing booked ahead = no order in `draft`, `awaiting_client` or `confirmed` dated after the last order. Threshold = pause > rhythm → risk; pause > 2 × rhythm → fyi. Run monthly, day 3, 07:00. One card per client and last order; a new order closes it."}'::jsonb, 'Closed by: a new confirmed or finalized order of this client (the watchdog closes the card on the next run)
Relevance window: until the next order of the client, or card expiry
Relations: — (v204 has no relation for this code); boundary with `ACCOUNT_REVENUE_DECLINE_YOY`: the process does not emit the decline while this card is open
Deal effect: per org rule; usual: risk trigger «Клиент перестал заказывать» on an open supply-agreement / listing deal of this client; no stage move', NULL, NULL),
  ('ACCOUNT_PRODUCT_NEW', 'base', 'K', 'account', 'Клиент впервые купил позицию', 'Клиент впервые за всю историю заказал позицию (товар), которую раньше у нас не брал. Повод предложить сопутствующие или похожие позиции.', 'Первый заказ нового клиента вообще → ACCOUNT_NEW_FOLLOWUP. Клиент снова взял позицию после перерыва — не новая. Новый винтаж той же позиции, если в каталоге это та же позиция — не новая. Клиент в письме просит ввести позиции в карту → LISTING_OPPORTUNITY (пакет distribution).', '{}'::text[], '{}'::jsonb, '[]'::jsonb, '«заказ № 1245 от 05.11.2026: впервые взяли 2 позиции — Шабли Премье Крю 2022 (12 бут.), Кальвадос Pays d''Auge (6 бут.)»', '«заказ № 1250: Просекко DOC, последний раз брали в марте 2026» → позиция не новая.', 'Назови новую позицию и предложи менеджеру при следующем контакте узнать, как она пошла у гостей или покупателей, и показать близкие позиции портфеля.', 4, 'fixed', 'chance', false, 'event', 'medium', false, false, false, 'process', 'onHold', NULL, 'account', '{}'::text[], NULL, 30, '{"ru":"Данные — `order_item` подтверждённых и завершённых заказов клиента. Условие — `product.id` нет ни в одном более раннем заказе клиента; у клиента есть хотя бы один более ранний заказ. Минимум данных — история заказов клиента не короче 6 месяцев. Одна карточка на заказ (все новые позиции заказа — в одной карточке). Запуск — ежедневно, 07:00, по заказам, подтверждённым за сутки. - Evidence format: «заказ № 1245 от 05.11.2026: впервые взяли Шабли Премье Крю 2022 (12 бут.)».","en":"Data = `order_item` of the client''s confirmed + finalized orders. Condition = the `product.id` is in no earlier order of the client, and the client has at least one earlier order. Minimum data = ≥ 6 months of order history. One card per order (all new products of the order in one card). Run daily, 07:00, over orders confirmed in the last day."}'::jsonb, 'Relevance window: 30 days from the order date
Deal effect: per org rule; usual: none', NULL, NULL),
  ('ACCOUNT_PRODUCT_STOPPED', 'base', 'K', 'account', 'Клиент перестал покупать позицию', 'Клиент регулярно брал у нас определённую позицию, но перестал её заказывать, хотя другие позиции продолжает брать.', 'Клиент вообще перестал заказывать → ACCOUNT_DORMANT. Позиция у нас выведена из каталога или её нет у поставщика → не этот код (INTERNAL_PRODUCT_STATUS_UPDATE или SUPPLIER_DELIVERY_DELAY). Клиент сам написал «убираем из карты» → DELISTING_RISK (пакет distribution). Общий объём упал, а позиция берётся → ACCOUNT_REVENUE_DECLINE_YOY.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, '«Риоха Крианса 2020: 9 заказов за 24 мес., ритм 28 дней; последний заказ позиции 12.06.2026 (147 дней назад); последний заказ клиента 28.10.2026»', '«Риоха Крианса 2020: последний заказ 12.06.2026; позиция снята с продажи (статус в каталоге — неактивна)» → причина у нас, не у клиента.', 'Назови позицию, обычный ритм и дату последнего заказа; предложи менеджеру узнать у закупщика или сомелье клиента (по роли), почему позицию больше не берут, и только потом предложить её снова или замену, а не скидку.', 5, 'fixed', 'risk', false, 'trend', 'medium', false, false, false, 'process', 'active', NULL, 'account', '{}'::text[], NULL, NULL, '{"ru":"Данные — `order_item` подтверждённых и завершённых заказов клиента по `product.id`. Ритм позиции — медианный интервал между заказами этой позиции. Минимум данных — позицию брали не меньше чем в `cards.productMinOrders` (предложение: 4) отдельных заказах за последние 24 месяца. Порог — последний заказ позиции старше max(2 × ритм позиции, `cards.productStoppedMinDays` — предложение: 90 дней). Условия — клиент за это время сделал другие заказы (последний заказ клиента в пределах его ритма, иначе это `ACCOUNT_DORMANT`); позиция активна в нашем каталоге (`product.status = ''active''`) и не числится в открытой задержке поставщика. Правило v204 (позиция с минимальной частотой три года подряд и ни разу за последние 12 месяцев) — как запасное, если у позиции меньше 4 заказов. Запуск — ежемесячно, 3-го числа, 07:00. Одна карточка на клиента и позицию; повтор — не раньше `cards.trendCooldownDays` (90 дней). - Evidence format: «Риоха Крианса 2020: брали каждые ~28 дней (9 заказов за 24 мес.), последний раз 12.06.2026; другие позиции клиент заказывал 28.10.2026».","en":"Data = `order_item` of the client''s confirmed + finalized orders per `product.id`. Product rhythm = the median gap between orders of that product. Minimum data = the product in ≥ `cards.productMinOrders` (proposed 4) separate orders in the last 24 months. Threshold = the last order of the product is older than max(2 × product rhythm, `cards.productStoppedMinDays`, proposed 90 days). Conditions = the client placed other orders in that time (last order within the client rhythm, else `ACCOUNT_DORMANT`); the product is active in our catalogue (`product.status = ''active''`) and not under an open supplier delay. The v204 rule (bought at the minimum frequency 3 years running, none in the last 12 months) is the fallback when the product has < 4 orders. Run monthly, day 3, 07:00. One card per client and product; cooldown 90 days."}'::jsonb, 'Display profile: from weight (D4); trend ceiling D4 (v204 kind = trend)
Profile (summary): D4 (trend ceiling D4)
Closed by: a new order of this product by the client
Relevance window: until the next order of the product, or card expiry
Deal effect: per org rule; usual: risk trigger on an open listing deal that contains this product; no stage move', NULL, NULL),
  ('ACCOUNT_REVENUE_GROWTH_YOY', 'base', 'K', 'account', 'Рост выручки по клиенту год к году', 'Клиент покупает у нас заметно больше: выручка за последние 12 полных месяцев выше, чем за те же месяцы год назад, на порог или больше. Повод укрепить отношения и расширить ассортимент.', 'Один крупный заказ в письме → это заказ (ORDER_REQUESTED пакета distribution), не тренд. Рост ниже порога или на малой базе — нет сигнала. Клиент сам сообщил об открытии новой точки → NEW_VENUE_OPENING (пакет distribution).', '{}'::text[], '{}'::jsonb, '[]'::jsonb, '«выручка за 12 мес. (11.2025–10.2026): 2,3 млн ₽; за 11.2024–10.2025: 1,7 млн ₽ (+35 %); заказов 26 против 19»', '«выручка за 12 мес.: 1,05 млн ₽; год назад: 1,00 млн ₽ (+5 %)» → ниже порога 10 %, сигнала нет.', 'Это возможность, а не риск: назови рост в цифрах и предложи менеджеру узнать у клиента (по роли), что даёт рост и что планируется дальше, затем подобрать предложение по расширению ассортимента.', 4, 'fixed', 'chance', false, 'trend', 'medium', false, false, false, 'process', 'active', NULL, 'account', '{}'::text[], NULL, NULL, '{"ru":"Данные, окно, база и минимум данных — как у `ACCOUNT_REVENUE_DECLINE_YOY` (12 полных месяцев против тех же месяцев год назад; первый заказ не позже чем за 24 месяца; не меньше 3 заказов в базе; выручка базы не ниже `cards.revenueTrendMinRub`, предложение: 100 000 ₽). Порог — рост не меньше `cards.revenueGrowthThresholdPct` (v204: 10 %) и не меньше `cards.revenueGrowthMinRub` (предложение: 100 000 ₽). Запуск — ежемесячно, 3-го числа, 07:00. Повтор — не раньше `cards.trendCooldownDays` (90 дней); смена направления (снижение) создаёт новую карточку сразу. - Evidence format: «выручка за 12 мес. (11.2025–10.2026): 2,3 млн ₽; год назад: 1,7 млн ₽ (+35 %, +600 тыс. ₽)».","en":"Data, window, baseline and minimum data = as `ACCOUNT_REVENUE_DECLINE_YOY`. Threshold = growth ≥ `cards.revenueGrowthThresholdPct` (v204: 10 %) AND ≥ `cards.revenueGrowthMinRub` (proposed 100 000 RUB). Run monthly, day 3, 07:00. Cooldown 90 days; a change of direction makes a new card at once."}'::jsonb, 'Display profile: from weight (D4); trend ceiling D4
Profile (summary): D4 (trend ceiling D4)
Closed by: — (expires; a later decline makes a new card at once)
Deal effect: per org rule; usual: none', NULL, NULL),
  ('ACCOUNT_CROSS_SELL_GAP', 'base', 'K', 'account', 'Неиспользованная возможность перекрёстной продажи', 'Клиент берёт у нас только одну группу товаров (например, только вино), хотя по профилю похожих клиентов ему подходят и другие группы (крепкие напитки, игристое). Припарковано в v204: нет основания для рекомендации без отраслевого правила или сравнения клиентов.', 'Клиент сам спросил о другой группе → SALES_NEW_DEMAND или SALES_PRICE_REQUEST. Клиент по лицензии или формату не может брать группу (например, без крепкого алкоголя) — не пробел.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, '«за 12 мес. клиент брал только тихие вина (18 заказов); 72 % клиентов типа HoReCa берут ещё игристое и крепкие напитки»', '', 'Предложи сочетание с другой группой только с понятной пользой для клиента (меню, гости, сезон), а не потому, что это больше выручки для нас.', 4, 'fixed', 'chance', false, 'trend', 'medium', false, false, false, 'process', 'parked', NULL, 'account', '{}'::text[], NULL, NULL, '{"ru":"Данные — `product.category` в заказах клиента за 12 месяцев и в заказах похожих клиентов того же типа (`client.custom_fields.type`). Условие — клиент берёт одну категорию, а не меньше 60 % клиентов того же типа берут две и больше; выручка клиента за 12 месяцев не ниже `cards.revenueTrendMinRub`. Запуск — ежемесячно. Повтор — не раньше 90 дней. Код остаётся припаркованным, пока нет правила сравнения клиентов. - Evidence format: «за 12 мес. только вино (100 % выручки); у 70 % ресторанов того же типа есть и крепкие напитки».","en":"Data = `product.category` in the client''s orders over 12 months and in the orders of clients of the same type. Condition = the client buys one category while ≥ 60 % of same-type clients buy two or more; 12-month revenue ≥ `cards.revenueTrendMinRub`. Run monthly. Cooldown 90 days. Stays parked until a client-comparison rule exists."}'::jsonb, 'Display profile: from weight (D4); trend ceiling D4
Profile (summary): D4 (trend ceiling D4)
Deal effect: per org rule; usual: none', NULL, NULL),
  ('ACCOUNT_MEETING_OVERDUE', 'base', 'K', 'account', 'Давно не было встречи с клиентом', 'С клиентом не было встречи дольше, чем требует частота для его сегмента. Проверка по всем подключённым источникам (календарные приглашения, встречи в переписке, задачи типа «встреча»).', 'Клиент отменил конкретную встречу → MEETING_CANCEL. Нет никакого контакта с бывшим клиентом → ACCOUNT_REACTIVATION_DUE. Переписка и заказы идут, а встречи нет — это этот код, только если у клиента задан сегмент.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, '«сегмент A; последняя встреча 12.07.2026 (дегустация в ресторане); прошло 122 дня; норма — раз в 30 дней»', '', 'Попроси менеджера назначить встречу или визит к клиенту (по роли), не проводить расследование.', 4, 'fixed', 'risk', false, 'trend', 'medium', false, false, false, 'process', 'onHold', NULL, 'account', '{}'::text[], NULL, NULL, '{"ru":"Данные — встречи с клиентом из календарных приглашений (.ics в письмах), событий календаря и задач-встреч; сегмент клиента (поля сегмента в CRM пока нет — поэтому код отложен). Порог — с последней встречи прошло больше `cards.meetingFrequencyADays` / `BDays` / `CDays` (предложение: 30 / 90 / 180 дней). Минимум данных — у клиента задан сегмент и подключён хотя бы один календарный источник. Запуск — еженедельно, понедельник 07:00. Повтор — не раньше 90 дней. - Evidence format: «сегмент A; последняя встреча 12.07.2026 (122 дня назад); норма — раз в 30 дней».","en":"Data = meetings with the client from calendar invites (.ics in mail), calendar events and meeting tasks; the client segment (no segment field exists yet — that is why the code is on hold). Threshold = the last meeting is older than `cards.meetingFrequencyADays` / `BDays` / `CDays` (proposed 30 / 90 / 180 days). Minimum data = a segment is set and at least one calendar source is connected. Run weekly, Monday 07:00. Cooldown 90 days."}'::jsonb, 'Display profile: from weight (D4); trend ceiling D4
Profile (summary): D4 (trend ceiling D4)
Closed by: a registered meeting with the client (calendar invite or meeting record)
Relevance window: until the next meeting, or card expiry
Deal effect: per org rule; usual: none', NULL, NULL),
  ('ACCOUNT_SEGMENT_UPGRADED', 'base', 'K', 'account', 'Повысился сегмент клиента', 'Сегмент клиента в CRM повысился (например, B → A). Припарковано в v204: модель сегментов не проработана; в CRM нет поля сегмента.', 'Рост выручки без смены сегмента → ACCOUNT_REVENUE_GROWTH_YOY. Ручная правка сегмента менеджером без изменения данных — не сигнал.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, '«сегмент B → A (октябрь и ноябрь 2026); выручка за 12 мес.: 3,1 млн ₽, 14-е место из 220 клиентов»', '', 'Напиши, что клиент вырос до верхнего сегмента, и предложи менеджеру пересмотреть уровень сервиса и частоту контактов.', 4, 'fixed', 'chance', false, 'event', 'medium', false, false, false, 'process', 'parked', NULL, 'account', ARRAY['ACCOUNT_SEGMENT_DOWNGRADED']::text[], NULL, NULL, '{"ru":"Данные — сегмент клиента, рассчитанный ежемесячно по выручке за 12 месяцев (предложение: A — верхние 20 % выручки организации, B — следующие 30 %, C — остальные). Условие — сегмент выше прошлого расчёта два месяца подряд. Запуск — ежемесячно, 3-го числа. Одна карточка на смену сегмента. - Evidence format: «сегмент B → A с 11.2026; выручка за 12 мес.: 3,1 млн ₽».","en":"Data = the client segment, computed monthly from 12-month revenue (proposed: A = top 20 % of org revenue, B = next 30 %, C = the rest). Condition = the segment is higher than in the previous computation for 2 months in a row. Run monthly, day 3. One card per segment change."}'::jsonb, 'Closes: `ACCOUNT_SEGMENT_DOWNGRADED` (an open card of the same client)
Deal effect: per org rule; usual: none', NULL, NULL),
  ('ACCOUNT_SEGMENT_DOWNGRADED', 'base', 'K', 'account', 'Снизился сегмент клиента', 'Сегмент клиента в CRM понизился (например, B → C). Припарковано в v204: модель сегментов не проработана; в CRM нет поля сегмента.', 'Падение выручки без смены сегмента → ACCOUNT_REVENUE_DECLINE_YOY. Клиент перестал заказывать → ACCOUNT_DORMANT.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, '«сегмент B → C (октябрь и ноябрь 2026); выручка за 12 мес.: 420 тыс. ₽ против 1,1 млн ₽ год назад»', '', 'Напиши, что клиент опустился в сегменте, и предложи менеджеру узнать причину при следующем контакте с закупщиком клиента (по роли).', 5, 'fixed', 'risk', false, 'event', 'medium', false, false, false, 'process', 'parked', NULL, 'account', ARRAY['ACCOUNT_SEGMENT_UPGRADED']::text[], NULL, NULL, '{"ru":"Как у `ACCOUNT_SEGMENT_UPGRADED`, но сегмент ниже прошлого расчёта два месяца подряд. Если в том же запуске есть `ACCOUNT_REVENUE_DECLINE_YOY` по клиенту — карточка одна, сегмент идёт как контекст. - Evidence format: «сегмент B → C с 11.2026; выручка за 12 мес.: 420 тыс. ₽».","en":"As `ACCOUNT_SEGMENT_UPGRADED`, but the segment is lower than in the previous computation for 2 months in a row. When `ACCOUNT_REVENUE_DECLINE_YOY` fires for the client in the same run, write one card; the segment is context."}'::jsonb, 'Closes: `ACCOUNT_SEGMENT_UPGRADED` (an open card of the same client)
Deal effect: per org rule; usual: none', NULL, NULL),
  ('ACCOUNT_NEW_FOLLOWUP', 'base', 'K', 'account', 'Пора обсудить результат первого заказа', 'Новый клиент получил первый заказ заданное число дней назад, и после этого с ним не было контакта. Пора узнать, как прошла поставка и как продаются позиции, и подвести клиента ко второму заказу.', 'Клиент сам написал о проблеме с поставкой → COMPLAINT_* или DELIVERY_DISCREPANCY. Повторный клиент → не этот код. Новая позиция у постоянного клиента → ACCOUNT_PRODUCT_NEW.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, '«первый заказ № 1188 на 86 тыс. ₽ отгружен 24.10.2026; с тех пор ни письма, ни встречи, ни нового заказа (15 дней)»', '', 'Предложи менеджеру коротко связаться с закупщиком или сомелье клиента (по роли): как прошла поставка, как позиции у гостей, и что нужно к следующему заказу.', 4, 'fixed', 'chance', false, 'event', 'medium', false, false, false, 'process', 'onHold', NULL, 'account', '{}'::text[], NULL, 14, '{"ru":"Данные — первый заказ клиента в статусе `finalized` (отгружен), его дата; источники с привязкой к клиенту после этой даты (письма, сообщения, встречи, задачи) и заказы. Порог — прошло `cards.newClientFollowupDays` (предложение: 14 дней) с первого заказа, нет исходящего контакта и нет второго заказа. Запуск — ежедневно, 07:00. Одна карточка на клиента. - Evidence format: «первый заказ № 1188 отгружен 24.10.2026; с тех пор контакта не было (15 дней)».","en":"Data = the client''s first order in status `finalized` (shipped) and its date; client-linked items after that date (mail, messages, meetings, tasks) and orders. Threshold = `cards.newClientFollowupDays` (proposed 14 days) since the first order, no outbound contact and no second order. Run daily, 07:00. One card per client."}'::jsonb, 'Closed by: any contact with the client after the first order (outbound mail or message, meeting, call task done) or a second order
Relevance window: 14 days after the trigger
Deal effect: per org rule; usual: none', NULL, NULL),
  ('ACCOUNT_REACTIVATION_DUE', 'base', 'K', 'account', 'Пора возобновить контакт с бывшим клиентом', 'С бывшим клиентом (сотрудничество на паузе или завершено, или клиент отказался от нашего последнего предложения) или с лидом не было никакого контакта заданный срок: ни писем, ни сообщений, ни встреч, ни задач, ни заказов, ни предложений, ни карточек. Рутинный повод напомнить о себе.', 'Клиент покупает, но пропустил свой ритм → ACCOUNT_DORMANT. Покупает меньше → ACCOUNT_REVENUE_DECLINE_YOY. Был хоть один контакт в интервале (входящий или исходящий) — интервал начинается заново. Клиент в статусе blocked или deleted — не этот код.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, '«последний контакт 03.04.2026 (наше КП, клиент отказался); 220 дней без писем, встреч и заказов; статус — отказ»', '«последний заказ 02.08.2026; ритм 21 день; пауза 92 дня» → клиент выпал из ритма, это ACCOUNT_DORMANT.', 'Это рутинный повод напомнить о себе, не жалоба и не продажа: назови, с какого времени нет контакта и каким был последний; предложи короткий личный контакт с закупщиком клиента (по роли) с вопросом о планах, а для отказавшего — актуальны ли ещё причины отказа.', 4, 'fixed', 'chance', false, 'watchdog', 'quick', false, false, false, 'process', 'active', NULL, 'account', '{}'::text[], NULL, NULL, '{"ru":"Данные — клиенты организации без открытых заказов: бывшие (последний заказ старше 12 месяцев, или сделка в статусе отказа, или клиент отклонил последнее предложение) и лиды (вкладка «Потенциальные», заказов нет). Контакт — любой `source_item`, привязанный к клиенту или его контактам (входящий или исходящий), заказ в любом статусе, задача, сделка, тема или карточка. Порог — нет контакта `cards.reactivationIntervalDays` (предложение: 180 дней, как пример v204 «6 месяцев»). Условие запасного правила — за этот срок по клиенту не было другой карточки (в том числе `ACCOUNT_DORMANT`). Запуск — еженедельно, понедельник 07:00. Одна карточка на клиента и период тишины; любой контакт начинает интервал заново. - Evidence format: «последний контакт 03.04.2026 (письмо с прайсом); 220 дней без контакта; статус — бывший клиент».","en":"Data = org clients with no open order: former clients (last order older than 12 months, a lost deal, or the client declined our last offer) and leads (tab «Потенциальные», no orders). Contact = any `source_item` linked to the client or its contacts (inbound or outbound), an order in any status, a task, deal, topic or card. Threshold = no contact for `cards.reactivationIntervalDays` (proposed 180 days, the v204 example of 6 months). Fallback condition = no other card for the client in that time (incl. `ACCOUNT_DORMANT`). Run weekly, Monday 07:00. One card per client and silence; any contact restarts the interval."}'::jsonb, 'Closed by: any new contact with the client (mail, message, meeting, task, order, offer)
Relevance window: until the next contact, or card expiry
Relations: — (fallback: it fires only when no other code made a card for the client in the interval)
Deal effect: per org rule; usual: none', NULL, NULL),
  ('COMPETITOR_NEW_CLIENT', 'base', 'L', 'competitor', 'Конкурент выиграл клиента', 'Наш конкурент (другой дистрибьютор или импортёр из списка конкурентов либо прямо названный в тексте конкурентом) получил нового клиента: вошёл в ассортимент сети, в винную карту ресторана, выиграл тендер или стал эксклюзивным поставщиком. Выигранный клиент обычно назван в том же тексте.', 'Победитель не является нашим конкурентом → SIGNAL_ACCOUNT_WIN (или нет сигнала для дистрибьютора). Конкурент появился у НАШЕГО действующего клиента (клиент берёт у него часть позиций, сравнивает цены) → SIGNAL_COMPETITOR; клиент жалуется, что у конкурента дешевле → COMPLAINT_PRICE. Наша собственная победа → TEAM_DEAL_WON / SALES_BOOKING_RECEIVED. Конкурент лишь участвует в тендере, итог неизвестен → нет сигнала.', ARRAY['стал официальным поставщиком', 'выиграл тендер', 'вошёл в ассортимент сети', 'зашёл в винную карту', 'эксклюзивный дистрибьютор', 'заключил договор поставки с', 'теперь поставляет в', 'новый клиент компании']::text[], '{"business":["по итогам тендера победителем признан","заключён договор поставки","определён поставщиком алкогольной продукции","получил право эксклюзивной дистрибуции","стал партнёром сети по винной категории"],"chat":["Винный Альянс зашёл в Азбуку","они забрали сеть","теперь у них весь бар","отель ушёл к Альянсу","слышал, Альянс выиграл тендер у гостиничной группы"],"terms":["тендер","44-ФЗ","223-ФЗ","листинг","ввод в матрицу","эксклюзив","СТМ"],"patterns":["имя конкурента + «выиграл / получил / зашёл / стал поставщиком» + клиент"]}'::jsonb, '[{"text":"«наш клиент берёт игристое у Альянса»","code":"SIGNAL_COMPETITOR"},{"text":"«у Альянса на 10 % дешевле, пересмотрите цену» от клиента","code":"COMPLAINT_PRICE"},{"text":"«Альянс потерял сеть»","code":"COMPETITOR_LOST_CLIENT"},{"text":"«объявлен тендер, участвуют Альянс и мы»","code":null}]'::jsonb, '«По итогам закупки ООО «Винный Альянс» признано поставщиком вина для ресторанов гостиничной группы «Северная корона» на 2027 год.»', '«ООО «Винный Альянс» подало заявку на участие в закупке гостиничной группы» → итога нет, нет сигнала.', 'Назвать конкурента и выигранного клиента и сказать, что действие сейчас не нужно; если выигранный клиент — наш клиент, карточку пишут как риск у этого клиента, а не как этот код.', 3, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'new_biz', '{}'::text[], NULL, NULL, NULL, 'Relations: — (boundary vs `SIGNAL_ACCOUNT_WIN`, `SIGNAL_COMPETITOR`)
Deal effect: per org rule; usual effect: none', NULL, NULL),
  ('COMPETITOR_LOST_CLIENT', 'base', 'L', 'competitor', 'Конкурент потерял клиента', 'Наш конкурент (дистрибьютор или импортёр) потерял клиента или расстался с ним: сеть вывела его позиции, ресторан сменил поставщика, контракт не продлён, тендер объявлен заново. Это повод проверить, есть ли смысл в первом контакте с этим клиентом.', 'Клиент ушёл от НАС → коды риска у нашего клиента (CONTRACT_TERMINATED, DELISTING_RISK). Клиент, не наш клиент, меняет поставщика, но бывший поставщик не наш конкурент → SIGNAL_AGENCY_CHANGE в агентском смысле не применяется; для дистрибьютора нет сигнала. Конкурент сам закрывается или банкротится → SIGNAL_INSOLVENCY (если он в списке клиентов) или COMPETITOR_NEGATIVE_PRESS. Клиент лишь «присматривается к другим поставщикам» без решения → нет сигнала.', ARRAY['сменил поставщика', 'отказался от поставок', 'расторг договор с', 'вывел из ассортимента позиции', 'не продлил контракт', 'тендер объявлен повторно', 'ищет нового дистрибьютора', 'прекратил сотрудничество с']::text[], '{"business":["прекращено сотрудничество с","договор поставки не пролонгирован","объявлена повторная закупка","сеть исключила из матрицы продукцию дистрибьютора","«рассматриваем альтернативных поставщиков вина» (только если сказано, что прежний ушёл)"],"chat":["Ромашка ушла от Альянса","Альянса выкинули из сети","они больше не берут у Альянса","отель ищет нового поставщика, Альянс всё","у Альянса забрали бар"],"terms":["делистинг","вывод из матрицы","повторный тендер","перезапуск закупки"],"patterns":["клиент + «ушёл от / отказался от / расстался с» + конкурент","конкурент + «потерял / лишился» + клиента"]}'::jsonb, '[{"text":"«мы больше не будем брать ваши позиции» от нашего клиента","code":"DELISTING_RISK"},{"text":"«Альянс выиграл тендер»","code":"COMPETITOR_NEW_CLIENT"},{"text":"«наш клиент сравнивает наши цены с Альянсом»","code":"SIGNAL_COMPETITOR"}]'::jsonb, '«Сеть «Городские погреба» с января прекращает сотрудничество с ООО «Винный Альянс» и объявляет новый отбор поставщика импортного вина.»', '«Сеть «Городские погреба» довольна ООО «Винный Альянс» и продлила договор» → потери нет, нет сигнала.', 'Назвать конкурента и клиента, которого он потерял; шаг — коротко проверить, есть ли смысл в первом контакте; не писать, что клиент ищет именно нас.', 4, 'fixed', 'chance', false, 'event', 'medium', false, false, false, 'both', 'active', NULL, 'new_biz', '{}'::text[], NULL, NULL, NULL, 'Relations: — (boundary vs `SIGNAL_AGENCY_CHANGE`, `SIGNAL_COMPETITOR`)
Deal effect: per org rule; usual effect: none (a deal entry needs a real contact with the client)', NULL, NULL),
  ('COMPETITOR_PRODUCT_NEW', 'base', 'L', 'competitor', 'Конкурент запустил продукт', 'Конкурент выводит на рынок новый продукт: новый бренд или производителя в портфеле, новую линейку, собственную торговую марку, новую услугу для HoReCa.', 'Новинка у производителя, которого представляем мы → PARTNER_PRODUCT_NEW. Новинка у нашего клиента → SIGNAL_PRODUCT_NEWS. Изменение цен конкурента → COMPETITOR_RATE_CHANGE.', ARRAY['пополнил портфель', 'эксклюзивно представляет', 'новый бренд в портфеле', 'запустил собственную марку', 'старт продаж', 'новинка от', 'расширил ассортимент']::text[], '{"business":["объявил о старте дистрибуции","получил права на импорт","представляет новую линейку","запуск СТМ"],"chat":["Альянс привёз новых грузин","у них теперь своя марка просекко","они взяли Бароло от нового хозяйства"],"terms":["портфель","СТМ","эксклюзив","линейка"]}'::jsonb, '[{"text":"«наш поставщик выпускает новое игристое»","code":"PARTNER_PRODUCT_NEW"},{"text":"«клиент открыл новый ресторан»","code":"NEW_VENUE_OPENING"}]'::jsonb, '«ООО «Винный Альянс» пополнило портфель: с декабря компания эксклюзивно представляет в России вина хозяйства из Риохи.»', '«ООО «Винный Альянс» подняло цены на Риоху» → COMPETITOR_RATE_CHANGE.', 'Назвать конкурента и новинку; шаг — сохранить для следующего разговора с клиентами, у которых эта категория в закупке.', 3, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'onHold', NULL, 'new_biz', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual effect: none', NULL, NULL),
  ('COMPETITOR_RATE_CHANGE', 'base', 'L', 'competitor', 'Конкурент изменил цены', 'Конкурент меняет опубликованный прайс-лист или общие условия: повышение или снижение цен, новые скидки от объёма, новая отсрочка.', 'Клиент говорит, что у конкурента дешевле, и требует скидку → COMPLAINT_PRICE. Изменение цен нашего поставщика → SUPPLIER_PRICE_CHANGE. Изменение наших цен → INTERNAL_PRICE_CHANGE.', ARRAY['повышает цены с', 'снизил цены на', 'новый прайс у', 'индексация цен', 'акция у дистрибьютора', 'скидка от объёма у', 'отсрочка 60 дней у']::text[], '{"business":["объявил о повышении отпускных цен","индексация прайс-листа","новые условия работы для HoReCa"],"chat":["Альянс опять поднял цены","у них сейчас акция минус 15 на итальянцев","они дают отсрочку 60 дней"],"terms":["прайс","отпускные цены","ретро-бонус","отсрочка"]}'::jsonb, '[{"text":"«у Альянса на 10 % дешевле, снизьте цену» от клиента","code":"COMPLAINT_PRICE"},{"text":"«производитель поднимает цены с 01.01»","code":"SUPPLIER_PRICE_CHANGE"}]'::jsonb, '«ООО «Винный Альянс» с 1 января повышает отпускные цены на импортное вино в среднем на 8 %.»', '«Клиент: у Альянса эта позиция на 200 рублей дешевле» → COMPLAINT_PRICE.', 'Назвать конкурента, направление и размер изменения и дату; шаг — проверить, как это меняет нашу позицию в переговорах с общими клиентами.', 3, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'onHold', NULL, 'new_biz', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual effect: none', NULL, NULL),
  ('COMPETITOR_FUNDING', 'base', 'L', 'competitor', 'Конкурент привлёк финансирование', 'Конкурент получает инвестиции, кредит на развитие, нового акционера или сам становится объектом покупки.', 'Финансирование нашего клиента → SIGNAL_FUNDING; покупка нашего клиента → SIGNAL_MERGER. Расширение без денег (новый склад, филиал) → COMPETITOR_EXPANSION.', ARRAY['привлёк инвестиции', 'новый акционер', 'вошёл в капитал', 'купил долю', 'приобрёл компанию', 'кредитная линия на развитие', 'сделка по покупке дистрибьютора']::text[], '{"business":["завершена сделка по приобретению","инвестфонд вошёл в капитал","получил финансирование на расширение"],"chat":["Альянс купили","у них новый инвестор","в Альянс зашли деньги"],"terms":["доля","капитал","M&A","сделка"]}'::jsonb, '[{"text":"«наш клиент привлёк инвестиции»","code":"SIGNAL_FUNDING"},{"text":"«Альянс открыл склад в Казани»","code":"COMPETITOR_EXPANSION"}]'::jsonb, '«Инвестфонд «Восток Капитал» приобрёл 40 % ООО «Винный Альянс» для развития сети складов.»', '«Винный Альянс открыл склад в Казани» → COMPETITOR_EXPANSION.', 'Назвать конкурента и суть сделки; шаг — сохранить как контекст рынка, действие не нужно.', 3, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'onHold', NULL, 'new_biz', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual effect: none', NULL, NULL),
  ('COMPETITOR_EXPANSION', 'base', 'L', 'competitor', 'Конкурент расширяет бизнес', 'Конкурент расширяется в наших регионах: новый склад, филиал, новый регион доставки, новая команда продаж для HoReCa.', 'Расширение нашего клиента → SIGNAL_EXPANSION. Новый бренд в портфеле → COMPETITOR_PRODUCT_NEW. Расширение за пределами регионов организации → нет сигнала.', ARRAY['открыл склад', 'новый филиал', 'вышел в регион', 'запустил доставку в', 'расширяет команду продаж', 'открывает представительство', 'новый распределительный центр']::text[], '{"business":["объявил об открытии регионального представительства","ввод в эксплуатацию склада","расширение географии поставок"],"chat":["Альянс зашёл в Питер","у них теперь склад в Казани","набирают торговых по HoReCa"],"terms":["РЦ","филиал","география","торговые представители"]}'::jsonb, '[{"text":"«наш клиент открывает второй ресторан»","code":"NEW_VENUE_OPENING"},{"text":"«Альянс получил инвестиции»","code":"COMPETITOR_FUNDING"}]'::jsonb, '«ООО «Винный Альянс» открыло распределительный центр в Екатеринбурге и запускает доставку по Уралу.»', '«ООО «Винный Альянс» открыло офис в Ереване» → вне наших регионов, нет сигнала.', 'Назвать конкурента и новый регион; шаг — проверить наших клиентов в этом регионе и держать в виду к следующим переговорам.', 3, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'onHold', NULL, 'new_biz', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual effect: none', NULL, NULL),
  ('COMPETITOR_PERSONNEL', 'base', 'L', 'competitor', 'У конкурента кадровые изменения', 'У конкурента меняется руководство или ключевые сотрудники: генеральный, коммерческий директор, бренд-менеджер, известный сомелье-консультант.', 'Кадровые изменения у нашего клиента → SIGNAL_C_LEVEL_CHANGE / CONTACT_NEW_DECISION_MAKER. Сотрудник конкурента переходит к нам → TEAM_INSIDER (внутренне) или нет сигнала.', ARRAY['назначен коммерческим директором', 'покинул компанию', 'новый генеральный директор', 'перешёл из', 'возглавил направление HoReCa', 'сменилось руководство']::text[], '{"business":["назначен на должность","освобождён от должности","кадровые перестановки в"],"chat":["у Альянса новый коммерческий","их бренд-шеф ушёл","Петров теперь у Альянса"],"terms":["КД","ГД","бренд-менеджер","HoReCa-директор"]}'::jsonb, '[{"text":"«в ресторане новый сомелье»","code":"CONTACT_NEW_DECISION_MAKER"},{"text":"«у клиента новый гендиректор»","code":"SIGNAL_C_LEVEL_CHANGE"}]'::jsonb, '«Коммерческим директором ООО «Винный Альянс» назначен бывший руководитель продаж крупной ресторанной группы.»', '«Новым генеральным директором нашего клиента «Бистро Лаванда» назначен бывший управляющий сети» → SIGNAL_C_LEVEL_CHANGE.', 'Назвать конкурента и должность (без имени); шаг — сохранить как контекст рынка.', 2, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'onHold', NULL, 'new_biz', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual effect: none', NULL, NULL),
  ('COMPETITOR_AWARD', 'base', 'L', 'competitor', 'Конкурент получил награду', 'Конкурент или вино из его портфеля получает награду, рейтинг или премию (конкурс, отраслевой рейтинг дистрибьюторов).', 'Награда нашего клиента → SIGNAL_AWARD. Награда вина нашего производителя → PARTNER_AWARD.', ARRAY['золотая медаль', 'лучший дистрибьютор года', 'победитель конкурса', 'высший балл', 'вошёл в рейтинг', 'премия', 'гран-при']::text[], '{"business":["удостоен награды","признан лучшим импортёром","по итогам дегустационного конкурса"],"chat":["Альянс взял золото","их Совиньон получил 95 баллов","им дали премию"],"terms":["медаль","балл","рейтинг","гран-при"]}'::jsonb, '[{"text":"«наш ресторан-клиент попал в гид»","code":"SIGNAL_AWARD"},{"text":"«вино нашего производителя получило золото»","code":"PARTNER_AWARD"}]'::jsonb, '«ООО «Винный Альянс» признано лучшим импортёром года по версии отраслевой премии.»', '«Наш клиент «Бистро Лаванда» вошёл в ресторанный гид» → SIGNAL_AWARD.', 'Назвать конкурента и награду; шаг не нужен, только контекст.', 2, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'onHold', NULL, 'new_biz', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual effect: none', NULL, NULL),
  ('COMPETITOR_NEGATIVE_PRESS', 'base', 'L', 'competitor', 'У конкурента репутационный кризис', 'О конкуренте выходит негативная информация: изъятие партии, проблемы с ЕГАИС или лицензией, судебный спор, проверка, массовые жалобы клиентов.', 'Негатив о нашем клиенте → SIGNAL_NEGATIVE_PRESS; банкротство клиента → SIGNAL_INSOLVENCY. Конкурент потерял конкретного клиента → COMPETITOR_LOST_CLIENT. Нельзя использовать этот код как повод очернять конкурента.', ARRAY['изъята партия', 'приостановлена лицензия', 'проверка Росалкогольтабакконтроля', 'контрафакт', 'иск к дистрибьютору', 'срывает поставки', 'жалобы клиентов на']::text[], '{"business":["приостановлено действие лицензии","выявлена продукция без маркировки","возбуждено дело","арбитражный иск"],"chat":["у Альянса забрали лицензию","у них проблемы с ЕГАИС","рестораны жалуются, что Альянс не возит"],"terms":["РАР","ЕГАИС","ФСМ","контрафакт","арбитраж"]}'::jsonb, '[{"text":"«у нашего клиента приостановлена лицензия»","code":"LICENSE_EXPIRING"},{"text":"«Альянс ушёл из сети»","code":"COMPETITOR_LOST_CLIENT"}]'::jsonb, '«Росалкогольтабакконтроль приостановил лицензию ООО «Винный Альянс» на оптовую торговлю алкоголем.»', '«У нашего клиента приостановили лицензию» → LICENSE_EXPIRING (distribution pack).', 'Назвать конкурента и суть события без оценок; шаг — проверить, каких общих клиентов это может затронуть, и быть готовыми к запросам.', 3, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'onHold', NULL, 'new_biz', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual effect: none', NULL, NULL),
  ('PARTNER_NEW_CLIENT', 'base', 'L', 'market', 'Партнёр выиграл клиента', 'Наш партнёр (производитель, которого мы представляем, или логистический / сервисный партнёр) получает нового клиента или крупный контракт.', 'Победа конкурента → COMPETITOR_NEW_CLIENT. Наша собственная победа → TEAM_DEAL_WON. Партнёр сам поставляет нашему клиенту в обход нас → SIGNAL_COMPETITOR.', ARRAY['стал поставщиком', 'заключил контракт с', 'новый клиент', 'выиграл тендер', 'вошёл в сеть', 'подписал соглашение']::text[], '{"business":["заключено соглашение о поставках","определён победителем закупки"],"chat":["наш логист взял ещё сеть","хозяйство зашло в дьюти-фри"],"terms":["контракт","тендер","листинг"]}'::jsonb, '[{"text":"«Винный Альянс выиграл тендер»","code":"COMPETITOR_NEW_CLIENT"}]'::jsonb, '«Наш транспортный партнёр «СеверЛогистик» заключил контракт на доставку для крупной ресторанной группы.»', '«ООО «Винный Альянс» заключил контракт с ресторанной группой» → COMPETITOR_NEW_CLIENT.', 'Назвать партнёра и нового клиента; шаг — проверить, даёт ли это нам повод для совместного предложения.', 3, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'onHold', NULL, 'new_biz', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual effect: none', NULL, NULL),
  ('PARTNER_PRODUCT_NEW', 'base', 'L', 'market', 'Партнёр запустил продукт', 'Производитель, которого мы представляем, или другой партнёр выпускает новый продукт: новое вино, урожай, линейку, кюве, новую услугу.', 'Новый прайс производителя → SUPPLIER_PRICE_CHANGE. Новинка конкурента → COMPETITOR_PRODUCT_NEW. Ввод позиции в НАШ каталог (изменение в CRM) → INTERNAL_PRODUCT_STATUS_UPDATE.', ARRAY['новый урожай', 'новое кюве', 'выпускает новую линейку', 'новинка от хозяйства', 'первый винтаж', 'лимитированный выпуск', 'новое игристое']::text[], '{"business":["рады представить новый винтаж","презентация новой линейки","старт продаж лимитированной серии"],"chat":["хозяйство выпустило оранж","пришёл новый винтаж","у них новое пет-нат"],"terms":["винтаж","кюве","линейка","лимитка"]}'::jsonb, '[{"text":"«с 01.12 новые цены на винтаж 2023»","code":"SUPPLIER_PRICE_CHANGE"}]'::jsonb, '«Хозяйство «Долина Солнца» выпускает первое игристое методом классической шампанизации, старт продаж в феврале.»', '«Хозяйство «Долина Солнца» повышает цены с 1 февраля» → SUPPLIER_PRICE_CHANGE.', 'Назвать партнёра, продукт и дату старта; шаг — решить, предлагать ли новинку клиентам, у которых эта категория в карте.', 3, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'onHold', NULL, 'new_biz', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual effect: none', NULL, NULL)
