INSERT INTO "signal_category" ("code", "pack_code", "block_code", "family", "label_ru", "definition_ru", "boundary_ru", "cues_prompt_ru", "synonyms_ru", "anti_cues_ru", "example_ru", "counter_example_ru", "card_note_ru", "weight", "score_rule", "class", "class_by_relation", "kind", "effort", "carries_amount", "asks_us", "inbound_only", "emitted_by", "stage", "display_profile", "recipient_role", "closes_codes", "date_gate", "relevance_days", "trigger_rule", "note_ru", "retired_at", "successor_code") VALUES
  ('PARTNER_FUNDING', 'base', 'L', 'market', 'Партнёр привлёк финансирование', 'Наш партнёр (производитель, поставщик, логистический партнёр) получает инвестиции, нового владельца или сам покупается другой компанией.', 'Финансирование конкурента → COMPETITOR_FUNDING; клиента → SIGNAL_FUNDING / SIGNAL_MERGER.', ARRAY['новый владелец', 'приобрёл хозяйство', 'вошёл в капитал', 'привлёк инвестиции', 'сменил собственника', 'сделка по покупке']::text[], '{"business":["завершена сделка по приобретению винодельни","смена конечного бенефициара"],"chat":["хозяйство купил холдинг","у винодельни новый хозяин"],"terms":["доля","бенефициар","холдинг"]}'::jsonb, '[{"text":"«Винный Альянс купили»","code":"COMPETITOR_FUNDING"}]'::jsonb, '«Винодельня «Долина Солнца» перешла под контроль агрохолдинга, договоры дистрибуции будут пересмотрены.»', '«Винодельня «Долина Солнца» открыла дегустационный зал» → PARTNER_EXPANSION.', 'Назвать партнёра и суть сделки; шаг — уточнить у партнёра, меняется ли что-то в нашем договоре дистрибуции.', 3, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'onHold', NULL, 'new_biz', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual effect: none', NULL, NULL),
  ('PARTNER_EXPANSION', 'base', 'L', 'market', 'Партнёр расширяет бизнес', 'Партнёр расширяется: новые виноградники, рост производства, новый склад или регион у логистического партнёра, новая команда.', 'Расширение конкурента → COMPETITOR_EXPANSION; клиента → SIGNAL_EXPANSION.', ARRAY['расширяет производство', 'новые виноградники', 'открыл склад', 'новый регион доставки', 'увеличил мощности', 'новый цех розлива']::text[], '{"business":["ввод новых производственных мощностей","расширение площади виноградников"],"chat":["хозяйство посадило ещё 20 га","логист открыл терминал в Новосибе"],"terms":["га","мощности","терминал","розлив"]}'::jsonb, '[{"text":"«Винный Альянс открыл склад»","code":"COMPETITOR_EXPANSION"}]'::jsonb, '«Наш перевозчик «СеверЛогистик» открывает терминал в Новосибирске и берёт грузы по Сибири с января.»', '«Наш клиент открывает ресторан в Новосибирске» → NEW_VENUE_OPENING.', 'Назвать партнёра и что расширяется; шаг — проверить, даёт ли это нам новые объёмы или новую географию.', 3, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'onHold', NULL, 'new_biz', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual effect: none', NULL, NULL),
  ('PARTNER_PERSONNEL', 'base', 'L', 'market', 'У партнёра кадровые изменения', 'У партнёра меняется руководство или ключевой контакт: экспорт-менеджер производителя, энолог, директор логистической компании.', 'Изменения у клиента → SIGNAL_C_LEVEL_CHANGE / CONTACT_LEAVING; у конкурента → COMPETITOR_PERSONNEL.', ARRAY['новый экспорт-менеджер', 'новый энолог', 'назначен директором', 'покидает компанию', 'теперь ваш контакт', 'сменился менеджер по России']::text[], '{"business":["сообщаем о назначении","с 1 декабря по всем вопросам обращайтесь к"],"chat":["у хозяйства новый экспорт-менеджер","Марко ушёл, теперь Лука"],"terms":["экспорт-менеджер","энолог","KAM"]}'::jsonb, '[{"text":"«у клиента новый закупщик»","code":"CONTACT_NEW_DECISION_MAKER"}]'::jsonb, '«С 1 декабря экспорт-менеджером винодельни по России назначен новый сотрудник, прежний покидает компанию.»', '«Наш закупщик в ресторане сменился» → CONTACT_NEW_DECISION_MAKER.', 'Назвать партнёра и должность; шаг — представиться новому контакту и сверить открытые поставки.', 2, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'onHold', NULL, 'new_biz', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual effect: none', NULL, NULL),
  ('PARTNER_AWARD', 'base', 'L', 'market', 'Партнёр получил награду', 'Производитель, которого мы представляем, или его вино получает награду, высокий балл критика или место в рейтинге — аргумент для продаж.', 'Награда конкурента → COMPETITOR_AWARD; клиента → SIGNAL_AWARD.', ARRAY['золотая медаль', '95 баллов', 'лучшее вино', 'вошло в топ', 'победитель конкурса', 'гран-при', 'высшая оценка']::text[], '{"business":["удостоено золотой медали","получило высшую оценку жюри"],"chat":["наше Пино взяло золото","95 баллов у критика"],"terms":["медаль","балл","топ-100"]}'::jsonb, '[{"text":"«вино Альянса получило золото»","code":"COMPETITOR_AWARD"}]'::jsonb, '«Пино нуар хозяйства «Долина Солнца» урожая 2022 года получило золотую медаль на международном конкурсе.»', '«Ресторан клиента получил звезду гида» → SIGNAL_AWARD.', 'Назвать вино и награду; шаг — использовать как аргумент в следующих предложениях клиентам.', 2, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'both', 'onHold', NULL, 'new_biz', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual effect: none', NULL, NULL),
  ('PARTNER_NEGATIVE_PRESS', 'base', 'L', 'market', 'У партнёра репутационный кризис', 'О партнёре выходит негативная информация: отзыв партии, фальсификат, проблемы с сертификацией, санкции, суд. Это риск для самого партнёрства и для наших продаж его продукции.', 'Задержка поставки от партнёра → SUPPLIER_DELIVERY_DELAY. Негатив о конкуренте → COMPETITOR_NEGATIVE_PRESS; о клиенте → SIGNAL_NEGATIVE_PRESS.', ARRAY['отзыв партии', 'фальсификат', 'отозван сертификат', 'попал под санкции', 'запрет ввоза', 'скандал', 'судебный иск к производителю']::text[], '{"business":["Роспотребнадзор приостановил ввоз","выявлено несоответствие","отзыв продукции с рынка"],"chat":["у хозяйства скандал с подделкой","их запретили ввозить","партию отзывают"],"terms":["РПН","декларация соответствия","отзыв","санкции"]}'::jsonb, '[{"text":"«контейнер от производителя задерживается»","code":"SUPPLIER_DELIVERY_DELAY"}]'::jsonb, '«Роспотребнадзор приостановил ввоз продукции винодельни «Долина Солнца» из-за несоответствия маркировки.»', '«Поставка от «Долины Солнца» сдвигается на две недели» → SUPPLIER_DELIVERY_DELAY.', 'Назвать партнёра и суть проблемы; шаг — проверить остатки и открытые заказы с его продукцией и подготовить ответ клиентам.', 4, 'fixed', 'risk', false, 'event', 'medium', false, false, false, 'both', 'onHold', NULL, 'new_biz', '{}'::text[], NULL, NULL, NULL, 'Deal effect: per org rule; usual effect: none', NULL, NULL),
  ('INTERNAL_PRICE_CHANGE', 'base', 'M', 'internal', 'Изменились наши цены', 'Изменилась наша отпускная цена на активную позицию каталога. Менеджер должен знать об этом раньше, чем спросит клиент.', 'Поставщик прислал нам новый прайс → SUPPLIER_PRICE_CHANGE. Клиент просит цены → SALES_PRICE_REQUEST. Индивидуальная скидка клиента (client.custom_fields.discount) — не изменение цены каталога, нет сигнала.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, '«Цена «Просекко DOC Брют, 0,75» снижена с 1 120 ₽ до 990 ₽ (−11,6 %) с 15.11.2026.»', '«Клиенту «Бистро Лаванда» установлена скидка 7 %» → индивидуальная скидка, нет сигнала.', 'Назвать позицию, старую и новую цену и дату; шаг — проверить открытые предложения и заказы с этой позицией и предупредить ключевых клиентов до того, как они спросят.', 3, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'process', 'onHold', NULL, 'team', '{}'::text[], NULL, NULL, '{"ru":"Ежедневно сравнить цену каждой активной позиции `product` с прошлым снимком. Сигнал, если цена изменилась не менее чем на 5 % (настройка `internal.priceChangeThresholdPct`, предложение 5) или изменилась цена позиции, которую клиент заказывал за последние 12 месяцев (любое изменение). Одна карточка на изменение прайса за день: все изменённые позиции в одном списке; адресаты — менеджеры клиентов, которые брали эти позиции. Повтор по той же позиции — не раньше чем через 30 дней, кроме смены направления (рост → снижение). Нет прошлого снимка — нет сигнала. - Evidence (RU, data fact): «Цена «Пино нуар Долина Солнца 2022, 0,75» изменилась с 1 850 ₽ до 2 040 ₽ (+10,3 %) с 01.12.2026; позицию брали 7 клиентов за 12 месяцев.»","en":"Daily, compare the price of each active `product` row with the last snapshot. Emit when the price changed by at least 5 % (setting `internal.priceChangeThresholdPct`, proposed 5), or when any price changed for a SKU that a client ordered in the last 12 months. One card per price-list change per day, with all changed SKUs in one list; recipients are the account managers of clients who bought these SKUs. Cooldown per SKU: 30 days, except a change of direction. No previous snapshot → no signal."}'::jsonb, 'Deal effect: per org rule; usual effect: none', NULL, NULL),
  ('INTERNAL_PRODUCT_STATUS_UPDATE', 'base', 'M', 'internal', 'Изменился статус нашего товара / позиции', 'Наша позиция каталога сменила статус: введена новая позиция, позиция выведена из ассортимента, закончилась на складе или снова появилась в наличии, сменился винтаж.', 'Новинка у производителя, ещё не заведённая в наш каталог → PARTNER_PRODUCT_NEW. Поставщик сообщает о задержке → SUPPLIER_DELIVERY_DELAY. Изменение только цены → INTERNAL_PRICE_CHANGE.', '{}'::text[], '{}'::jsonb, '[]'::jsonb, '«Остаток «Шабли Премьер Крю 2021, 0,75» — 0 бут. с 12.11.2026; за 90 дней позицию заказывали 3 клиента.»', '«Остаток «Шабли» снизился со 120 до 96 бут.» → обычное движение склада, нет сигнала.', 'Назвать позицию и новый статус; шаг — предупредить клиентов, которые её берут, и предложить замену, если позиции нет.', 3, 'fixed', 'fyi', false, 'event', 'medium', false, false, false, 'process', 'onHold', NULL, 'team', '{}'::text[], NULL, NULL, '{"ru":"Ежедневно сравнить статус и остаток каждой позиции `product` с прошлым снимком. Сигнал при одном из событий: позиция добавлена в каталог; позиция стала неактивной (выведена); остаток стал 0 у позиции, которую клиенты заказывали за последние 90 дней; остаток снова больше 0 после нуля; сменился винтаж (год урожая). Одна карточка на позицию и событие; повтор того же события по той же позиции — не раньше чем через 30 дней. Адресаты — менеджеры клиентов, которые брали позицию за 12 месяцев; для новой позиции — команда продаж. - Evidence (RU, data fact): «Позиция «Риоха Крианса 2020, 0,75» выведена из ассортимента 10.11.2026; за 12 месяцев её заказывали 4 клиента.»","en":"Daily, compare status and stock of each `product` row with the last snapshot. Emit on: SKU added; SKU set inactive (withdrawn); stock reaches 0 for a SKU that clients ordered in the last 90 days; stock above 0 again after zero; vintage changed. One card per SKU and event; cooldown for the same event on the same SKU: 30 days. Recipients: account managers of clients who bought the SKU in 12 months; for a new SKU, the sales team."}'::jsonb, 'Deal effect: per org rule; usual effect: none', NULL, NULL),
  ('SUPPLIER_DELIVERY_DELAY', 'base', 'N', 'supplier', 'Поставщик задерживает поставку', 'Наш поставщик (производитель, импортёр, экспедитор) сообщает, что товар, который МЫ заказали, придёт позже, частично или не придёт: перенос даты отгрузки, задержка контейнера, таможни, производства, позиции нет в наличии у производителя. От этого могут зависеть заказы наших клиентов.', 'Клиент жалуется на НАШУ задержку → COMPLAINT_TIMING. Клиент спрашивает, когда мы привезём → DELIVERY_SCHEDULE_REQUEST. Наше письмо поставщику «когда отгрузите?» без ответа о задержке → нет сигнала (inbound only). Поставщик меняет цены → SUPPLIER_PRICE_CHANGE.', ARRAY['контейнер задерживается', 'задержка на таможне', 'поставка от производителя переносится', 'нет в наличии у производителя', 'отгрузка частичная', 'бэкордер', 'новая дата отгрузки', 'не успеваем отгрузить к']::text[], '{"business":["сообщаем о переносе даты отгрузки","ориентировочная дата прибытия сдвигается на","груз задержан на таможенном посту","товар будет поставлен частично","позиция временно недоступна к заказу","производитель не подтверждает объём","задержка розлива","судно прибывает позже плана","акцизные марки не получены, отгрузка откладывается"],"chat":["контейнер встал в Новороссийске","фура задерживается на границе","завод не успевает, сдвиг на неделю","этого вина нет, остаток уйдёт в бэкордер","приедет только половина","таможня держит, ждём выпуска"],"terms":["ETA","ETD","бэкордер","backorder","«ДТ» (декларация на товары)","СВХ","ФСМ","коносамент","частичная отгрузка"],"patterns":["«задерживается / переносится / сдвигается» + поставка / отгрузка / контейнер","«нет в наличии» + у производителя / на складе поставщика","«новая дата» + прибытия / отгрузки"]}'::jsonb, '[{"text":"«где наш заказ? вы обещали в понедельник» от клиента","code":"COMPLAINT_TIMING"},{"text":"«во сколько привезёте в пятницу?» от клиента","code":"DELIVERY_SCHEDULE_REQUEST"},{"text":"«с 1 декабря новые цены» от поставщика","code":"SUPPLIER_PRICE_CHANGE"},{"text":"«контейнер вышел по плану, ETA 20.11»","code":null}]'::jsonb, '«Контейнер с вашим заказом задержан на таможне в Новороссийске, ориентировочная дата прибытия на склад — 28.11 вместо 18.11.»', '«Контейнер вышел из порта по графику, прибытие 18.11» → задержки нет, нет сигнала.', 'Назвать наш заказ, позицию и новую дату; шаг — если клиенты ждут эти позиции, сообщить им новую дату и предложить замену, иначе действие не нужно.', 4, 'fixed', 'fyi', false, 'event', 'quick', false, false, true, 'parser', 'active', NULL, 'logistics', '{}'::text[], NULL, NULL, NULL, 'IN4COM: on (review: 4 → 5 risk?)
Relations: — (boundary vs `COMPLAINT_TIMING`, `DELIVERY_SCHEDULE_REQUEST`)
Deal effect: per org rule; usual effect: risk trigger «Нет товара для поставки» (draft §4) when the SKU is in a listing or tender deal', NULL, NULL),
  ('SUPPLIER_PRICE_CHANGE', 'base', 'N', 'supplier', 'Новый прайс или изменение цен поставщика', 'Поставщик или производитель, у которого мы покупаем или который предлагает нам поставки, присылает новый или изменённый прайс, новые закупочные или дилерские цены, повышение цен на товары, которые мы покупаем или можем купить.', 'Клиент просит НАШИ цены → SALES_PRICE_REQUEST. Изменилась наша отпускная цена → INTERNAL_PRICE_CHANGE. Конкурент изменил свои цены для клиентов → COMPETITOR_RATE_CHANGE. Рекламная рассылка нового поставщика без цен → нет сигнала.', ARRAY['новый прайс', 'повышение цен с 01.12', 'изменение закупочных цен', 'дилерские цены', 'курсовая корректировка', 'индексация цен', 'прайс-лист во вложении', 'цены действуют с']::text[], '{"business":["направляем актуальный прайс-лист","уведомляем об изменении цен с","в связи с ростом акцизов цены увеличиваются на","индексация отпускных цен","новые условия для дистрибьюторов","корректировка цен в связи с курсом евро","цены указаны с учётом НДС и акциза","прайс на урожай 2024"],"chat":["кинул новый прайс","с декабря плюс 7 %","евро вырос, поднимаем","скинули цены на остатки 2021","вот дилерские на новый винтаж"],"terms":["прайс","ПЛ","EXW","FCA","DAP","дилерская цена","закупочная цена","акциз","курсовая разница"],"patterns":["«цены действуют / вступают в силу» + дата","«повышение / снижение / индексация» + цен + процент","«прайс-лист» + во вложении"]}'::jsonb, '[{"text":"«пришлите ваш прайс» от клиента","code":"SALES_PRICE_REQUEST"},{"text":"«мы поднимаем отпускные цены» (наше решение)","code":"INTERNAL_PRICE_CHANGE"},{"text":"«у Альянса новые цены»","code":"COMPETITOR_RATE_CHANGE"},{"text":"«контейнер задерживается»","code":"SUPPLIER_DELIVERY_DELAY"}]'::jsonb, '«Уведомляем, что с 01.12.2026 закупочные цены на всю линейку игристых увеличиваются на 6 % в связи с ростом ставки акциза. Новый прайс во вложении.»', '«Добрый день! Пришлите, пожалуйста, ваш актуальный прайс на игристое» от клиента → SALES_PRICE_REQUEST.', 'Назвать поставщика, с какой даты и что меняется; шаг — проверить, нужно ли менять наши отпускные цены и открытые предложения с этими товарами, иначе действие не нужно.', 3, 'fixed', 'fyi', false, 'event', 'quick', true, false, true, 'parser', 'active', NULL, 'logistics', '{}'::text[], NULL, NULL, NULL, 'Relations: — (boundary vs `SALES_PRICE_REQUEST`, `INTERNAL_PRICE_CHANGE`)
Deal effect: per org rule; usual effect: none', NULL, NULL),
  ('ORDER_REQUESTED', 'distribution', 'DS1', 'order', 'Клиент прислал заказ', 'Клиент (закупщик, сомелье, управляющий, бар-менеджер) присылает заказ на поставку: называет позиции и количество (бутылки, коробки) и просит отгрузить, привезти или выставить счёт. Сюда же относится повтор прошлого заказа («как обычно», «как в прошлый раз») и заявка файлом.', 'Вопрос о цене или наличии без просьбы отгрузить → SALES_PRICE_REQUEST / STOCK_AVAILABILITY_REQUEST. Изменение уже отправленного заказа → ORDER_CHANGE_REQUESTED. Бронь товара, которого ещё нет (новый урожай, будущий контейнер) → PREORDER_REQUESTED (предложено). Наше собственное предложение, наша заявка поставщику, подтверждение заказа от нашего поставщика нам (мы покупатель → блок N). Напоминание по уже отправленному заказу («подтвердите, что заявку получили») — не новый код, а обновление той же темы.', ARRAY['прошу отгрузить', 'заказ на', 'нужно 12 кор.', 'по 6 бут.', 'выставьте счёт на', 'сделайте заявку', 'закажем как обычно', 'закиньте в заказ']::text[], '{"business":["прошу отгрузить","просим поставить","направляем заказ","заявка на поставку","заказ на следующую неделю","прошу выставить счёт на следующие позиции","прошу зарезервировать и отгрузить","просим доставить к пятнице","во вложении заявка","повторите, пожалуйста, прошлый заказ","прошу включить в ближайшую отгрузку","просим привезти по адресу ресторана на Покровке"],"chat":["закиньте в заказ","скиньте счёт на","нам на пятницу","привезите","закажем как обычно","как в прошлый раз, только шабли побольше","давайте 2 кор. просекко и кор. риохи","плиз, на завтра","оформите нам","надо 6 бут. брюта до выходных","запишите на четверг","берём"],"terms":["кор.","бут.","бт","шт.","ящ.","0,75","магнум 1,5","арт.","артикул","код товара","урожай 2021","21-го года","заявка","счёт на оплату","спецификация к заказу"],"patterns":["«прошу / просим + отгрузить / поставить / привезти» + список позиций с количеством","нужно / надо + число + кор. / бут.","«на + день недели / дату» (желаемый срок)","таблица «наименование — количество» во вложении или в теле"]}'::jsonb, '[{"text":"«есть ли шабли 21-го?»","code":"STOCK_AVAILABILITY_REQUEST"},{"text":"«пришлите прайс»","code":"SALES_PRICE_REQUEST"},{"text":"«добавьте ещё кор. к заказу»","code":"ORDER_CHANGE_REQUESTED"},{"text":"«заказ подтверждаем, счёт во вложении» (наше письмо)","code":"ORDER_CONFIRMED"},{"text":"«готовы взять в карту три позиции»","code":"LISTING_OPPORTUNITY"},{"text":"«поставьте нас в лист ожидания на новый урожай»","code":"PREORDER_REQUESTED"}]'::jsonb, '«Добрый день! Прошу отгрузить к пятнице: Шабли 2021 — 12 кор. по 6 бут., Просекко DOC — 3 кор. Счёт на ООО «Ромашка».»', '«Подскажите, почём сейчас Шабли 2021 и сколько его у вас на складе?» → нет просьбы отгрузить; это вопрос о цене и наличии.', 'Пишите «Ответственный менеджер — подтвердить заказ клиента и дату отгрузки»; укажите позиции, количество и срок клиента, если они есть в сообщении.', 5, 'fixed', 'chance', false, 'event', 'quick', true, true, true, 'parser', 'active', NULL, 'account', '{}'::text[], NULL, 14, NULL, 'Display profile: from weight (D4) + deadline escalation: same-day shipment → «Сейчас» (decided R8, 2026-11-13)
Closed by: `ORDER_CONFIRMED` (same topic); made moot by `ORDER_CANCELLED` (Open point 11)
Relevance window: 14 days — an order that is not confirmed in 14 days was processed outside the CRM or is lost; the card must not stay open longer
Relations: outranks `STOCK_AVAILABILITY_REQUEST` and `SALES_PRICE_REQUEST` on the same subject; `ORDER_CANCELLED` outranks it; replaces base `SALES_BOOKING_RECEIVED` (off for IN4COM)
Deal effect: none (Q26). Topic and card only. Later step: «Создать заказ» on the card (replaces the `new_order` card)', NULL, NULL),
  ('ORDER_CHANGE_REQUESTED', 'distribution', 'DS1', 'order', 'Клиент просит изменить заказ', 'Клиент просит изменить уже отправленный заказ: добавить или убрать позицию, поменять количество, заменить вино на другое, перенести дату или адрес отгрузки.', 'Новый отдельный заказ на другие позиции или другую дату → ORDER_REQUESTED. Полная отмена → ORDER_CANCELLED. Перенос отгрузки — это изменение, а не отмена. Просьба подобрать замену позиции, которой нет у нас на складе → SUBSTITUTION_REQUESTED (предложено). Жалоба на уже доставленный товар → блок DS4.', ARRAY['добавьте в заказ', 'уберите позицию', 'замените на', 'перенесите отгрузку', 'вместо 12 сделайте 8', 'докиньте кор.', 'поменяйте адрес доставки', 'скорректируйте заявку']::text[], '{"business":["просим внести изменения в заказ","прошу скорректировать заявку № 154","прошу исключить из заказа позицию","просим увеличить количество","прошу заменить Риоху Крианса на Резерву","прошу перенести отгрузку на понедельник","доставку просим перенести на другой адрес","уточнение к заказу","прошу считать актуальной заявку во вложении"],"chat":["докиньте ещё кор. просекко","уберите брют","вместо 12 сделайте 8","давайте не в пятницу, а в субботу","в заказ ещё 2 бут. магнума","поменяйте на розе","минус одна кор.","закиньте ещё позицию, плиз","привезите не на Тверскую, а на Арбат"],"terms":["корректировка заказа","новая редакция заявки","доп. позиция","перенос отгрузки","изменение адреса доставки"],"patterns":["«добавьте / уберите / замените / перенесите» + ссылка на существующий заказ («в заказ», «к заявке», «в сегодняшнюю отгрузку»)"]}'::jsonb, '[{"text":"«и ещё отдельный заказ на следующую среду»","code":"ORDER_REQUESTED"},{"text":"«отгрузку не делайте, заказ отменяем»","code":"ORDER_CANCELLED"},{"text":"«шабли нет, чем можно заменить?»","code":"SUBSTITUTION_REQUESTED"},{"text":"«привезли не ту позицию»","code":"DELIVERY_DISCREPANCY"}]'::jsonb, '«По заявке 154: Шабли вместо 12 сделайте 8 кор. и добавьте 2 кор. Кремана. Отгрузку перенесите на понедельник.»', '«Получили заказ 154, всё на месте, спасибо» → изменение не просят; нет сигнала.', 'Пишите «Ответственный менеджер — внести изменения в заказ и подтвердить клиенту новый состав и дату»; перечислите, что меняется.', 6, 'fixed', 'risk', false, 'event', 'quick', true, true, true, 'parser', 'active', NULL, 'account', '{}'::text[], NULL, 14, NULL, 'Closed by: `ORDER_CONFIRMED` (same topic)
