INSERT INTO "signal_category" ("code", "pack_code", "block_code", "family", "label_ru", "definition_ru", "boundary_ru", "cues_prompt_ru", "synonyms_ru", "anti_cues_ru", "example_ru", "counter_example_ru", "card_note_ru", "weight", "score_rule", "class", "class_by_relation", "kind", "effort", "carries_amount", "asks_us", "inbound_only", "emitted_by", "stage", "display_profile", "recipient_role", "closes_codes", "date_gate", "relevance_days", "trigger_rule", "note_ru", "retired_at", "successor_code") VALUES
  ('EGAIS_ISSUE_RESOLVED', 'distribution', 'DS5', 'delivery', 'Проблема в ЕГАИС решена', 'Клиент или мы подтверждаем, что проблема в ЕГАИС по поставке решена: ТТН подтверждена, акт принят, остатки сведены, марки сопоставлены.', 'Обещание исправить («переотправим сегодня») не закрывает проблему. Подтверждение ТТН без предшествующей проблемы → нет сигнала (рутина).', ARRAY['ТТН подтвердили', 'в ЕГАИС всё прошло', 'акт приняли', 'остатки сошлись', 'накладная упала', 'вопрос по ЕГАИС закрыт', 'приняли в УТМ', 'всё прошло']::text[], '{"business":["ТТН № 4512 в ЕГАИС подтверждена","акт расхождений принят","остатки в ЕГАИС приведены в соответствие","повторно направленная ТТН получена и подтверждена","вопрос по ЕГАИС урегулирован"],"chat":["упала, подтвердили","всё прошло, спасибо","в егаисе ок","приняли","остатки сошлись","закрыли по егаису"],"terms":["ТТН подтверждена","акт принят","квитанция ЕГАИС","статус «принято»"],"patterns":["«ТТН / акт / накладная + подтвердили / приняли / прошла» после сообщения о проблеме"]}'::jsonb, '[{"text":"«переотправим сегодня» (наше обещание)","code":null},{"text":"«ТТН пришла, подтвердили» без прошлой проблемы","code":null}]'::jsonb, '«Переотправленную ТТН 4512 получили и подтвердили в ЕГАИС, спасибо.»', '«Сейчас переотправим ТТН» → проблема ещё открыта.', 'Обновите карточку темы: «Проблема в ЕГАИС по ТТН <номер> решена»; новую карточку не создавайте.', 0, 'state', NULL, false, 'state', NULL, false, false, false, 'parser', 'active', 'S1', 'logistics', ARRAY['EGAIS_ISSUE']::text[], NULL, NULL, NULL, 'Display profile: S1 — updates the linked card and writes a history record
Closes: `EGAIS_ISSUE`; also `MARKING_ISSUE` on the same topic (extension of the draft, Open point 12)
Relations: attaches to the ЕГАИС topic by ТТН number or the open ЕГАИС topic of the same client
Deal effect: none', NULL, NULL),
  ('MARKING_ISSUE', 'distribution', 'DS5', 'delivery', 'Проблема с марками (ФСМ / акцизные марки)', 'Клиент сообщает о проблеме с федеральной специальной или акцизной маркой на бутылках нашей поставки: марка не считывается, повреждена, отсутствует, дублируется или не числится за накладной, и бутылку нельзя продать.', 'Ошибка в ТТН или остатках ЕГАИС без проблемы с маркой → EGAIS_ISSUE. Повреждённая этикетка (не марка) → COMPLAINT_QUALITY. Бой бутылки → DELIVERY_DISCREPANCY.', ARRAY['акцизная марка', 'ФСМ', 'не считывается марка', 'марка повреждена', 'нет марки', 'марка не числится', 'касса не пробивает', 'ошибка при сканировании марки']::text[], '{"business":["на 4 бутылках не считываются акцизные марки","марки не числятся за ТТН","на кассе выдаёт ошибку проверки марки","обнаружены бутылки без ФСМ","марка повреждена, продажа невозможна","дублирование марок в поставке","просим заменить бутылки с нечитаемыми марками"],"chat":["марка не пробивается","касса ругается на марку","сканер не читает марку","марка порвана","две бутылки без марок","марка чужая какая-то"],"terms":["ФСМ","«АМ» (акцизная марка)","PDF-417","DataMatrix","марка не в ЕГАИС","проверка марки на кассе","«ЧЗ» (Честный знак)","пивная маркировка"],"patterns":["марка + не считывается / не пробивается / повреждена / не числится / отсутствует"]}'::jsonb, '[{"text":"«ТТН не подтверждается»","code":"EGAIS_ISSUE"},{"text":"«этикетка подмокла»","code":"COMPLAINT_QUALITY"},{"text":"«бутылка разбита»","code":"DELIVERY_DISCREPANCY"}]'::jsonb, '«На кассе не пробиваются 6 бутылок Риохи из поставки 12.11 — марка не числится. Что делаем?»', '«Этикетка на двух бутылках порвана, гостям такое не подать» → дефект этикетки, COMPLAINT_QUALITY.', 'Пишите «Логистика — проверить марки по поставке и заменить бутылки или исправить данные»; укажите поставку и число бутылок.', 6, 'fixed', 'risk', false, 'event', 'quick', false, true, true, 'parser', 'active', NULL, 'logistics', '{}'::text[], NULL, NULL, NULL, 'Closed by: `EGAIS_ISSUE_RESOLVED` on the same topic (Open point 12)
Relations: leads over `EGAIS_ISSUE` when the ЕГАИС error is caused by a mark; `both` with `RETURN_REQUESTED` (bottles with bad marks to be taken back)
Deal effect: none', NULL, NULL),
  ('LICENSE_EXPIRING', 'distribution', 'DS5', 'contract', 'Лицензия клиента заканчивается / приостановлена', 'Клиент сообщает, что его лицензия на розничную продажу алкоголя (в том числе при оказании услуг общепита) заканчивается, продлевается, приостановлена или аннулирована, и это влияет на приёмку наших поставок.', 'Наш запрос копии лицензии без сведений о сроке → не сигнал клиента. Лицензия с концом срока дальше 30 дней от даты сообщения → отбрасывается сервером (date gate). Лицензия нашего поставщика или наша → нет сигнала. Просьба клиента прислать наши разрешительные документы → DOCUMENTS_REQUESTED.', ARRAY['лицензия заканчивается', 'продление лицензии', 'лицензия приостановлена', 'аннулировали лицензию', 'новую лицензию ещё не получили', 'срок лицензии до', 'переоформляем лицензию', 'пока без лицензии']::text[], '{"business":["срок действия лицензии на розничную продажу алкогольной продукции истекает 15.12","подали документы на продление лицензии","действие лицензии приостановлено до решения суда","лицензия аннулирована","в связи с переоформлением лицензии просим приостановить отгрузки алкоголя","новую лицензию направим после получения","лицензия переоформляется на новое юрлицо"],"chat":["у нас лицуха кончается","лицензию продлеваем, пока не везите алкоголь","лицензию приостановили","ждём новую лицензию","до 15-го ещё старая действует"],"terms":["лицензия","лицуха","розничная лицензия","лицензия на общепит","ФСРАР","Росалкогольтабакконтроль","РАР","приостановление","аннулирование","переоформление","реестр лицензий"],"patterns":["«лицензия + заканчивается / истекает / приостановлена / аннулирована / переоформляется» + дата или причина"]}'::jsonb, '[{"text":"«пришлите нам вашу лицензию и сертификаты»","code":"DOCUMENTS_REQUESTED"},{"text":"«лицензия действует до 2027 года»","code":null},{"text":"«лицензия поставщика на импорт»","code":null}]'::jsonb, '«Срок нашей лицензии на розничную продажу алкоголя истекает 10.12, документы на продление поданы. Новую пришлём сразу после получения.»', '«Направляем копию действующей лицензии (срок до 2027 г.) для вашего досье» → срок далеко; нет сигнала.', 'Пишите «Ответственный менеджер и финансы — получить новую лицензию клиента до даты окончания и решить, отгружать ли алкоголь до неё»; укажите дату окончания или факт приостановления.', 7, 'fixed', 'risk', false, 'event', 'medium', false, false, true, 'parser', 'active', NULL, 'finance', '{}'::text[], '{"fact":"licenseEndDate","test":"within","settingKey":"distribution.licenseExpiryWindowDays","days":30}'::jsonb, NULL, NULL, 'Emitted by: parser (later both: a process can read a stored licence end date)
Closed by: — (the user marks «Готово» when the new licence is received; Open point 10)
Date gate: { fact: `licenseEndDate`, test: within, setting: `distribution.licenseExpiryWindowDays` = 30, window: 0–30 days after the item date }; bypass: `licenseStatus` = «suspended» or «revoked» passes without a date
Relevance window: until `licenseEndDate` + 30 days; for a suspension: default
Relations: `both` with `DOCUMENTS_REQUESTED` when we ask for the new licence in the same thread (our ask is not a client code)
Deal effect: none (candidate risk, Open point 8)', NULL, NULL),
  ('DOCUMENTS_REQUESTED', 'distribution', 'DS5', 'delivery', 'Запрошены документы (УПД, ТТН, сертификаты, декларации, справки А/Б)', 'Клиент просит прислать документы к поставке или на продукцию: УПД, счёт-фактуру, ТОРГ-12, ТТН, сертификаты, декларации соответствия, удостоверения качества, справки А и Б, копии наших лицензий, оригиналы с подписью.', 'Ошибка в ЕГАИС, из-за которой нужна новая ТТН → EGAIS_ISSUE. Корректировочный документ по расхождению → DELIVERY_DISCREPANCY. Акт сверки → RECONCILIATION_REQUESTED. Прайс или каталог → SALES_PRICE_REQUEST / SALES_CATALOG_REQUESTED. Тендерная документация, которую клиент присылает нам → SALES_TENDER_INVITATION.', ARRAY['пришлите УПД', 'нужны сертификаты', 'декларация соответствия', 'справки А и Б', 'удостоверение качества', 'оригиналы документов', 'ТОРГ-12', 'счёт-фактура']::text[], '{"business":["просим направить УПД по поставке от 05.11","для приёмки требуются декларации соответствия","пришлите, пожалуйста, справки А и Б на партию","нужны удостоверения качества на новые позиции","просим оригиналы документов с подписью и печатью","направьте копию лицензии на оптовую торговлю","пришлите счёт-фактуру и ТОРГ-12","для сети нужен пакет документов на ввод позиций"],"chat":["скиньте УПД","нужны серты на шабли","декларации закиньте","справки бэшки пришлите","где оригиналы?","документы по последней поставке не пришли"],"terms":["УПД","ТОРГ-12","СФ","счёт-фактура","ТТН","серт","сертификат","«ДС» (декларация соответствия)","ЕАЭС","удостоверение качества","справка А","справка Б","оригиналы","ЭДО","Диадок","СБИС"],"patterns":["«пришлите / направьте / нужны + название документа» + поставка или позиция"]}'::jsonb, '[{"text":"«ТТН в ЕГАИС не подтверждается»","code":"EGAIS_ISSUE"},{"text":"«пришлите акт сверки»","code":"RECONCILIATION_REQUESTED"},{"text":"«пришлите прайс»","code":"SALES_PRICE_REQUEST"},{"text":"«нужен корректировочный УПД на бой»","code":"DELIVERY_DISCREPANCY"}]'::jsonb, '«Для приёмки на РЦ нужны декларации соответствия и справки Б на партию Просекко от 12.11. Пришлите, пожалуйста, сегодня.»', '«Документы получили, спасибо» → просьбы нет; нет сигнала.', 'Пишите «Логистика — отправить клиенту запрошенные документы»; перечислите документы и поставку.', 5, 'fixed', 'fyi', false, 'event', 'quick', false, true, true, 'parser', 'active', NULL, 'logistics', '{}'::text[], NULL, NULL, NULL, 'Closed by: our reply with the documents (Open point 11)
Relations: `EGAIS_ISSUE` leads over it; `DELIVERY_DISCREPANCY` leads over it (a corrected УПД for a discrepancy belongs to that claim); attaches to an open delivery topic of the same shipment; base `CONTRACT_COMPLIANCE_DECLARATION` stays off for IN4COM — this code covers wine documents
Deal effect: none', NULL, NULL),
  ('PAYMENT_TERMS_REQUEST', 'distribution', 'DS6', 'invoice', 'Просьба об отсрочке / лимите / без предоплаты', 'Клиент просит изменить условия оплаты в свою пользу: отсрочку или её увеличение, кредитный лимит или его увеличение, работу без предоплаты, рассрочку долга.', 'Просьба о скидке или цене → SALES_RENEGOTIATION / COMPLAINT_PRICE. Обещание оплатить существующий счёт к дате → PAYMENT_PROMISE. Вопрос «какие у вас условия оплаты?» без просьбы их изменить → SALES_PRICE_REQUEST. Бонус за объём → PROMO_SUPPORT_REQUESTED.', ARRAY['отсрочка', 'увеличить лимит', 'без предоплаты', 'рассрочка', 'отсрочку 45 дней', 'кредитный лимит', 'оплата по факту реализации', 'постоплата']::text[], '{"business":["просим предоставить отсрочку платежа 45 календарных дней","просим увеличить кредитный лимит до 1,5 млн ₽","рассмотрите работу без предоплаты","просим перейти на оплату по факту реализации","просим рассрочку погашения задолженности на три месяца","в сети стандартная отсрочка 60 дней","условие ввода — отсрочка не менее 45 дней"],"chat":["можно отсрочку побольше?","лимит упёрся, поднимете?","давайте без предоплаты","оплатим по реализации","дайте дней 30 на оплату","разбейте долг на пару платежей"],"terms":["отсрочка","ДЗ","кредитный лимит","лимит","предоплата","постоплата","оплата по реализации","рассрочка","«к. д.» (календарные дни)","«б. д.» (банковские дни)","график платежей"],"patterns":["«просим / нужна + отсрочка / лимит / рассрочка» + срок или сумма","без + предоплаты"]}'::jsonb, '[{"text":"«снизьте цену на 5 %»","code":"SALES_RENEGOTIATION"},{"text":"«оплатим счёт в пятницу»","code":"PAYMENT_PROMISE"},{"text":"«какие у вас условия работы?»","code":"SALES_PRICE_REQUEST"},{"text":"«нужен ретро-бонус»","code":"PROMO_SUPPORT_REQUESTED"}]'::jsonb, '«Для открытия второго ресторана просим увеличить кредитный лимит до 1,5 млн ₽ и отсрочку до 30 календарных дней.»', '«Напомните, какая у нас сейчас отсрочка?» → просьбы изменить нет; нет сигнала.', 'Пишите «Финансы и ответственный менеджер — рассмотреть запрос клиента на отсрочку или лимит и ответить»; укажите запрошенный срок или сумму.', 6, 'fixed', 'risk', false, 'event', 'medium', true, true, true, 'parser', 'active', NULL, 'finance', '{}'::text[], NULL, NULL, NULL, 'Closed by: our reply with agreed terms (Open point 11)
Relations: `both` with base `SALES_RENEGOTIATION` (price and payment terms in one message = two codes; payment terms only = this code only); `both` with `NEW_VENUE_OPENING` (terms for a new venue)
Deal effect: stage move: enter «Согласование условий» (S5) on an open `new_venue` / `chain_listing` / `supply_agreement` / `renewal` deal; risk trigger «Жёсткие условия оплаты» (`PAYMENT_TERMS_ABOVE_POLICY`)', NULL, NULL),
  ('PAYMENT_PROMISE', 'distribution', 'DS6', 'invoice', 'Клиент обещал оплатить к дате', 'Клиент обещает оплатить счёт или долг к определённой дате или сообщает, что платёж запланирован.', 'Факт оплаты («оплатили», «платёжка во вложении») → base INVOICE_PAID. Просьба об отсрочке или рассрочке → PAYMENT_TERMS_REQUEST. Общие слова без срока и без намерения («разберёмся с оплатой») → нет сигнала.', ARRAY['оплатим до пятницы', 'платёж запланирован', 'оплата будет в среду', 'поставили в реестр платежей', 'оплатим на этой неделе', 'деньги будут до конца месяца', 'бухгалтерия оплатит завтра', 'закроем долг до 20-го']::text[], '{"business":["оплату гарантируем до 15.11","счёт поставлен в реестр платежей на четверг","платёж запланирован на 20.11","задолженность будет погашена до конца месяца","оплата пройдёт в течение 3 банковских дней","бухгалтерия проведёт оплату завтра"],"chat":["в пятницу оплатим","завтра закинем деньги","на неделе закроем","бух обещал сегодня","после 15-го оплатим, ок?","до конца месяца всё погасим"],"terms":["реестр платежей","платёжный календарь","б. д.","гарантийное письмо об оплате"],"patterns":["оплатим / погасим / закроем + до / к / в + дата","платёж + запланирован / в реестре"]}'::jsonb, '[{"text":"«оплатили, платёжка во вложении»","code":"INVOICE_PAID"},{"text":"«дайте отсрочку до конца месяца»","code":"PAYMENT_TERMS_REQUEST"},{"text":"«по оплате вернёмся позже»","code":null}]'::jsonb, '«Счёт 2281 поставили в реестр, оплата пройдёт в пятницу, 14.11.»', '«Оплатили счёт 2281, платёжка во вложении» → это факт оплаты, INVOICE_PAID.', 'Обновите тему счёта: «Клиент обещал оплату к <дата>»; финансам — проверить поступление после этой даты.', 3, 'fixed', 'fyi', false, 'event', NULL, true, false, true, 'parser', 'active', NULL, 'finance', '{}'::text[], NULL, NULL, NULL, 'Closed by: base `INVOICE_PAID` (same topic; the pack seed adds `PAYMENT_PROMISE` to `INVOICE_PAID.closes_codes`)
Relevance window: until the promised date + 3 working days
Relations: **attaches to the open invoice topic** (`INVOICE_OVERDUE`) of the same client: hard key by invoice / УПД number, else the matcher with family `invoice`; the deadline from `facts.deadlines` has owner = them; relation `dampens` on `INVOICE_OVERDUE`: the invoice topic goes one list level down until the promised date + 1 working day (06 §5.2 H4); it is not hidden; a broken promise starts a new cycle
Deal effect: none; does not clear «Долг клиента» — only `INVOICE_PAID` does (a promise is not a payment)', NULL, NULL),
  ('RECONCILIATION_REQUESTED', 'distribution', 'DS6', 'invoice', 'Запрошен акт сверки', 'Клиент просит акт сверки взаиморасчётов за период, или присылает свой акт сверки на подпись, или сообщает о расхождении в сальдо.', 'Наша просьба клиенту подписать акт сверки — не сигнал клиента. Просьба прислать УПД или счёт-фактуры → DOCUMENTS_REQUESTED. Напоминание о долге → INVOICE_OVERDUE.', ARRAY['акт сверки', 'сверка взаиморасчётов', 'пришлите сверку', 'расхождение в сальдо', 'сверимся', 'подпишите акт сверки', 'за 3 квартал', 'сальдо на 01.10']::text[], '{"business":["просим направить акт сверки взаиморасчётов за 9 месяцев","во вложении наш акт сверки, просим подписать","по нашим данным сальдо отличается на 48 000 ₽","для закрытия года просим сверку на 31.12","просим сверку по договору ДП-45"],"chat":["скиньте сверку","давайте сверимся","у нас по сверке не бьётся","бух просит акт сверки","сверку за квартал можно?"],"terms":["акт сверки","сверка","сальдо","взаиморасчёты","закрытие квартала","закрытие года","ЭДО"],"patterns":["«пришлите / подпишите / нужна + сверка / акт сверки» + период или дата"]}'::jsonb, '[{"text":"«пришлите УПД за октябрь»","code":"DOCUMENTS_REQUESTED"},{"text":"«напоминаем о задолженности» (наше письмо)","code":null},{"text":"«долг 120 000 ₽ просрочен»","code":"INVOICE_OVERDUE"}]'::jsonb, '«Бухгалтерия просит акт сверки за 3 квартал, у нас сальдо отличается на 48 000 ₽.»', '«Подписанный акт сверки во вложении, расхождений нет» → просьбы нет; нет сигнала.', 'Пишите «Финансы — подготовить и отправить клиенту акт сверки»; укажите период и сумму расхождения, если она названа.', 4, 'fixed', 'fyi', false, 'event', 'quick', true, true, true, 'parser', 'active', NULL, 'finance', '{}'::text[], NULL, NULL, NULL, 'Closed by: our reply with the signed act (Open point 11)
Relations: own topic (family `invoice`); attaches to an open invoice topic only when the client disputes the same invoice in the same message; `both` with base `INVOICE_OVERDUE` when the client names a disputed debt
Deal effect: none', NULL, NULL),
  ('LISTING_CONFIRMED', 'distribution', 'DS7', 'account', 'Клиент подтвердил ввод позиций / выбор нас поставщиком', 'Клиент подтверждает решение в нашу пользу: наши позиции утверждены в винную карту или ассортиментную матрицу, нас выбрали поставщиком (в том числе по итогам тендера), договор поставки подписан, позиции остаются после пересмотра.', '«Рассматриваем», «нам интересно», «скорее всего возьмём» → не подтверждение (spec §2.1 rule 7: устная заинтересованность — не результат). Первый заказ без слов об утверждении → ORDER_REQUESTED (заказы не двигают сделки, Q26). Подписание доп. соглашения о продлении → этот код только если клиент подтверждает выбор; намерение продлить → base CONTRACT_RENEWAL_INTENT.', ARRAY['утвердили в карту', 'ввели в ассортимент', 'прошли комитет', 'вы выбраны поставщиком', 'договор подписан', 'позиции остаются', 'признаны победителем', 'включили в матрицу']::text[], '{"business":["по итогам закупочного комитета позиции утверждены к вводу","ваши вина включены в новую карту с 1 декабря","сообщаем, что вы выбраны поставщиком по категории игристых","по итогам закупки ваша заявка признана победителем","договор поставки подписан, оригинал направим почтой","после пересмотра матрицы ваши позиции сохраняются","согласовали ввод трёх SKU в 40 магазинов"],"chat":["комитет прошли","берём в карту все три","утвердили, с понедельника в карте","вы в матрице","договор подписали","оставляем ваше просекко","победили, поздравляю"],"terms":["ввод","утверждено","комитет","АМ","SKU","протокол подведения итогов","победитель закупки","договор подписан"],"patterns":["«утвердили / ввели / включили / выбрали / подписали» + позиции / поставщика / договор","позиции + остаются / сохраняются"]}'::jsonb, '[{"text":"«рассматриваем ваши позиции»","code":"LISTING_OPPORTUNITY"},{"text":"«скорее всего возьмём, решим после нового года»","code":"DECISION_POSTPONED"},{"text":"«продлим договор на следующий год»","code":"CONTRACT_RENEWAL_INTENT"},{"text":"«пришлите 6 кор. для старта»","code":"ORDER_REQUESTED"}]'::jsonb, '«По итогам комитета три ваши позиции утверждены в матрицу, ввод в 40 магазинов с 1 декабря.»', '«Позиции понравились, на комитет выйдем в январе» → решения ещё нет; это контекст LISTING_OPPORTUNITY или DECISION_POSTPONED.', 'Обновите карточку сделки: «Клиент утвердил позиции / выбрал нас поставщиком»; следующий шаг — стартовая поставка и документы для ввода.', 0, 'state', NULL, false, 'state', NULL, true, false, true, 'parser', 'onHold', 'S1', 'account', ARRAY['LISTING_OPPORTUNITY', 'NEW_VENUE_OPENING', 'DELISTING_RISK', 'EXCLUSIVITY_REQUESTED']::text[], NULL, NULL, NULL, 'Статус: proposed (new) · target block after approval: DS3
Display profile: S1 — updates the linked card and the deal; no own card (if nothing is linked → W1 info)
Closes: `LISTING_OPPORTUNITY`, `NEW_VENUE_OPENING`, `DELISTING_RISK`, `EXCLUSIVITY_REQUESTED` on the same topic
Relations: attaches to the listing / venue / tender / contract topic of the same client; never creates a topic by itself (spec §2.1 rule 6)
Deal effect: outcome `won` for `wine_card_listing`, `chain_listing`, `new_venue`, `tender`, `supply_agreement`, `renewal`; clears risks `DELISTING`, `COMPETITOR_PRICE`, `CONTRACT_EXPIRING_NO_RENEWAL`', NULL, NULL),
  ('DECISION_POSTPONED', 'distribution', 'DS7', 'account', 'Клиент откладывает решение', 'Клиент переносит решение по вводу позиций, выбору поставщика, договору или открытию точки на более поздний срок, часто без новой даты и без следующего шага.', 'Перенос даты одной поставки → ORDER_CHANGE_REQUESTED. Перенос встречи с новой датой → нет сигнала (контекст); отмена встречи без новой даты → base MEETING_CANCEL. Отказ → SALES_OFFER_DECLINED. Перенос с конкретной датой и следующим шагом («решим на комитете 20.11») — это контекст, а не риск; код ставится, но риск его не считает (условие риска).', ARRAY['решим после праздников', 'вернёмся к вопросу позже', 'пока не готовы', 'отложим до весны', 'комитет перенесли', 'вопрос с картой пока на паузе', 'руководство ещё не решило', 'давайте в следующем квартале']::text[], '{"business":["решение по поставщику перенесено на после праздников","обновление карты откладываем до весны","закупочный комитет перенесён, дату сообщим дополнительно","к вопросу вернёмся в следующем квартале","пока не готовы принять решение","рассмотрение договора приостановлено до утверждения бюджета","открытие сдвигается, вопрос поставок пока не актуален"],"chat":["давайте после нового года","пока на паузе","шеф ещё думает","не до этого сейчас","вернёмся позже","комитет опять перенесли","пока не решили"],"terms":["перенос комитета","пауза","на согласовании у руководства","после утверждения бюджета"],"patterns":["решим / вернёмся / рассмотрим + позже / после + событие","пока не + готовы / решили","отложим / перенесли + решение / комитет / ввод"]}'::jsonb, '[{"text":"«перенесите отгрузку на понедельник»","code":"ORDER_CHANGE_REQUESTED"},{"text":"«встречу переносим на 20.11»","code":null},{"text":"«ваше предложение нам не подходит»","code":"SALES_OFFER_DECLINED"}]'::jsonb, '«Обновление карты пока откладываем, вернёмся к вопросу после праздников.»', '«Комитет перенесли на 20.11, позиции туда выносим» → есть дата и следующий шаг; риск не активируется.', 'Пишите «Ответственный менеджер — согласовать с клиентом новую дату решения и следующий шаг»; не придумывайте причину переноса.', 5, 'fixed', 'risk', false, 'event', NULL, false, false, true, 'parser', 'onHold', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Статус: proposed (new) · target block after approval: DS3
Closed by: — (the risk clears when a date and a next step are agreed; spec §9.4)
Relations: attaches to the deal topic (listing, venue, tender, contract); repeated mentions of the same postponement are one instance (spec §5.4 5a)
Deal effect: in-stage context; risk trigger «Решение откладывается» (`DECISION_DELAYED`, min_occurrences 2)', NULL, NULL),
  ('ALLOCATION_REQUESTED', 'distribution', 'DS7', 'offer', 'Запрос аллокации дефицитной позиции', 'Клиент просит выделить ему квоту дефицитного вина, которое распределяется по аллокации (культовые хозяйства, лимитированные кюве, малые партии): сколько бутылок ему достанется и на каких условиях.', 'Простой вопрос о наличии → STOCK_AVAILABILITY_REQUEST. Заказ доступного товара → ORDER_REQUESTED. Бронь будущей поставки без дефицита (новый урожай обычной позиции) → PREORDER_REQUESTED.', ARRAY['аллокация', 'квота', 'сколько нам выделите', 'лимитированная партия', 'распределение по клиентам', 'по аллокации', 'сколько бутылок достанется', 'включите нас в распределение']::text[], '{"business":["просим выделить аллокацию на новый релиз","какой объём квоты предусмотрен для нашего ресторана","просим включить нас в распределение лимитированной партии","интересует аллокация на 2026 год","готовы взять полную квоту","просим увеличить нашу квоту по сравнению с прошлым годом"],"chat":["сколько нам в этом году дадите?","аллокацию на ДРК можно?","нам бы пару ящиков из лимитки","впишите нас на квоту","на нас что-то осталось?"],"terms":["аллокация","квота","лимитка","релиз","кюве","en primeur","примёр","культовое хозяйство"],"patterns":["выделите / дайте / включите + квоту / аллокацию / в распределение"]}'::jsonb, '[{"text":"«шабли есть в наличии?»","code":"STOCK_AVAILABILITY_REQUEST"},{"text":"«забронируйте 60 бут. нового урожая» (обычная позиция)","code":"PREORDER_REQUESTED"}]'::jsonb, '«Подскажите, какая у нас будет аллокация на новый релиз Бароло? В прошлом году было 12 бутылок, хотели бы 24.»', '«Бароло 2019 есть на складе?» → вопрос о наличии.', 'Пишите «Ответственный менеджер — согласовать квоту клиента по дефицитной позиции и ответить»; укажите позицию и запрошенный объём.', 5, 'fixed', 'chance', false, 'event', 'medium', false, true, true, 'parser', 'onHold', NULL, 'account', '{}'::text[], NULL, NULL, NULL, 'Статус: proposed (new) · target block after approval: DS2
