  ('COMPLAINT_ERROR', 'base', 'E', 'complaint', 'COMPLAINT_ERROR (выведен)', '', '', '{}'::text[], '{}'::jsonb, '[]'::jsonb, '', '', '', 0, 'fixed', NULL, false, 'event', NULL, false, false, false, 'parser', 'parked', NULL, NULL, '{}'::text[], NULL, NULL, NULL, 'Retired: Retired 2026-09-25 (v204): E · mapped (merged into quality)', '2026-09-25'::timestamp, 'COMPLAINT_QUALITY'),
