  ('ATTR_EMOTION_ANGRY', 'base', 'emotion', 'message', 'Гнев', '', 2, 'active', false, '{}'::text[], ARRAY['возмутительно', 'неприемлемо', 'это безобразие', 'досудебная претензия', 'будем вынуждены', 'обратимся в суд', 'расторгнем договор', 'сколько это будет продолжаться', 'вопиющий случай', 'это уже за гранью']::text[], ARRAY['Деловое требование без эмоции («просим заменить бутылку») — не гнев', 'простая констатация проблемы («пришёл бой, 2 бут.») — ATTR_EMOTION_NEUTRAL', 'разочарование без угроз → ATTR_EMOTION_FRUSTRATED']::text[], NULL, 0),
  ('ATTR_EMOTION_FRUSTRATED', 'base', 'emotion', 'message', 'Разочарование', '', 2, 'active', false, '{}'::text[], ARRAY['к сожалению, опять', 'разочарованы', 'ожидали большего', 'уже не первый раз', 'жаль, что так вышло', 'не этого мы ждали', 'очень неприятно', 'расстроены']::text[], ARRAY['Вежливое «к сожалению» без упрёка («к сожалению, не сможем встретиться в четверг») — нет атрибута', 'угрозы и претензия → ATTR_EMOTION_ANGRY']::text[], NULL, 1),
  ('ATTR_EMOTION_IMPATIENT', 'base', 'emotion', 'message', 'Нетерпение', '', 1, 'active', false, '{}'::text[], ARRAY['срочно', 'сколько можно', 'жду ответа', 'ASAP', 'нужно сегодня', 'до конца дня', 'горит', 'когда уже', 'третий раз пишу', 'ответьте наконец']::text[], ARRAY['Обычный срок без нажима («ответьте, пожалуйста, до пятницы») — не нетерпение', '«срочно» в подписи или шаблоне темы — нет атрибута']::text[], NULL, 2),
  ('ATTR_EMOTION_NEUTRAL', 'base', 'emotion', 'message', 'Нейтральная эмоция', '', 0, 'active', false, '{}'::text[], ARRAY['просим выставить счёт', 'подтвердите отгрузку на 14.11']::text[], ARRAY['Любой явный маркер гнева, разочарования, нетерпения или радости → соответствующий атрибут']::text[], NULL, 3),
  ('ATTR_EMOTION_POSITIVE', 'base', 'emotion', 'message', 'Позитивная эмоция', '', -1, 'active', false, '{}'::text[], ARRAY['очень довольны', 'гостям очень понравилось', 'спасибо огромное', 'вы нас выручили', 'рады сотрудничеству', 'отлично', 'супер', 'восторг']::text[], ARRAY['Дежурная вежливость («спасибо», «хорошего дня», «с уважением») — нет атрибута', 'сарказм («спасибо, конечно, за очередную задержку») → ATTR_TONE_NEGATIVE']::text[], NULL, 4),
  ('ATTR_SALUTATION_SIE', 'base', 'salutation', 'message', 'Формальное обращение', '', 0, 'active', true, '{}'::text[], ARRAY['Вы', 'вы', 'Уважаемый / Уважаемая', 'Добрый день, Ирина Сергеевна', 'Вам', 'Ваш', 'просим Вас']::text[], ARRAY['Отдельное приветствие «Добрый день» без формы глагола ничего не решает', 'корпоративная рассылка — нет атрибута']::text[], 'Stage: active; по умолчанию выключено для русского (§10.3)', 5),
  ('ATTR_SALUTATION_DU', 'base', 'salutation', 'message', 'Неформальное обращение', '', -1, 'active', true, '{}'::text[], ARRAY['ты', 'тебе', 'тебя', 'твой', 'скинь', 'посмотри', 'привет, Саш', 'Лен, глянь']::text[], ARRAY['Если в тексте есть имя-отчество, «Уважаемый» или «Вы / Вам» — это ATTR_SALUTATION_SIE (коррекция в одну сторону)', '«вы» во множественном числе к команде («коллеги, вы получили?») — не ты-форма']::text[], 'Stage: active; по умолчанию выключено для русского (§10.3)', 6),
  ('ATTR_TONE_BRIEF', 'base', 'brevity', 'message', 'Краткий ответ', '', 1, 'active', false, '{}'::text[], ARRAY['Нет.', 'Не актуально.', 'Получили.', 'Ок', 'Посмотрим.']::text[], ARRAY['Короткий ответ на короткий вопрос («Да, подходит» на «Подходит пятница?») — нет атрибута', 'без видимой цитаты — нет атрибута']::text[], NULL, 7),
  ('ATTR_TONE_NEGATIVE', 'base', 'tone', 'message', 'Негативный тон', '', 1, 'active', false, '{}'::text[], ARRAY['опять ничего не прислали', 'уже вторая задержка подряд', 'как всегда, всё в последний момент', 'снова те же ошибки', 'мы вам не первый раз пишем', 'ну спасибо за сервис']::text[], ARRAY['Констатация факта без оценки: «пока не получили», «заказ ещё не пришёл», «в накладной другая цена» — нет атрибута']::text[], NULL, 8),
  ('ATTR_TONE_POSITIVE', 'base', 'tone', 'message', 'Позитивный тон', '', -1, 'active', false, '{}'::text[], ARRAY['с удовольствием', 'давайте', 'отлично, договорились', 'звучит хорошо', 'будем рады', 'конечно, сделаем', 'поддерживаем', 'хорошая идея']::text[], ARRAY['Формальное согласие без окраски («согласовано», «принято») — нет атрибута', 'радость как эмоция → ATTR_EMOTION_POSITIVE (другая группа, могут быть оба)']::text[], NULL, 9),
  ('ATTR_CLIENT_HIGH_VALUE', 'base', 'client_value', 'account', 'Высокая ценность клиента', 'Выводится на сервере: выручка клиента за последние 12 месяцев (оплаченные и подтверждённые заказы, finalized + confirmed) в верхних 20 % клиентов организации', 2, 'onHold', false, '{}'::text[], '{}'::text[], ARRAY['Не из текста письма', 'слова «мы крупный клиент» не дают атрибут']::text[], NULL, 10),
  ('ATTR_CLIENT_MID_VALUE', 'base', 'client_value', 'account', 'Средняя ценность клиента', 'Выводится на сервере: выручка за 12 месяцев в диапазоне от 50-го до 80-го перцентиля клиентов организации', 1, 'onHold', false, '{}'::text[], '{}'::text[], ARRAY['Не из текста письма']::text[], NULL, 11),
  ('ATTR_CLIENT_LOW_VALUE', 'base', 'client_value', 'account', 'Низкая ценность клиента', 'Выводится на сервере: выручка за 12 месяцев ниже 50-го перцентиля или менее 3 заказов за 12 месяцев', 0, 'onHold', false, '{}'::text[], '{}'::text[], ARRAY['Не из текста письма', 'новый клиент без истории → ATTR_REL_DURATION_NEW, не низкая ценность']::text[], NULL, 12),
  ('ATTR_CLIENT_HIGH_POTENTIAL', 'base', 'client_value', 'account', 'Высокий потенциал', 'Выводится на сервере: отметка «высокий потенциал» в карточке клиента или открытая сделка (листинг, тендер, годовой договор) с суммой выше порога организации', 2, 'onHold', false, '{}'::text[], '{}'::text[], ARRAY['Не из текста письма', 'единичный крупный заказ без сделки не даёт атрибут']::text[], NULL, 13),
  ('ATTR_REL_DURATION_NEW', 'base', 'relationship_duration', 'account', 'Новые отношения', 'Выводится на сервере: первый заказ клиента менее 6 месяцев назад (или клиент без заказов, созданный менее 6 месяцев назад)', 1, 'onHold', false, '{}'::text[], '{}'::text[], ARRAY['Не из текста письма']::text[], NULL, 14),
  ('ATTR_REL_DURATION_ESTABLISHED', 'base', 'relationship_duration', 'account', 'Установившиеся отношения', 'Выводится на сервере: первый заказ от 6 месяцев до 2 лет назад', 0, 'onHold', false, '{}'::text[], '{}'::text[], ARRAY['Не из текста письма']::text[], NULL, 15),
  ('ATTR_REL_DURATION_LONGTERM', 'base', 'relationship_duration', 'account', 'Длительные отношения', 'Выводится на сервере: первый заказ более 2 лет назад и хотя бы один заказ за последние 12 месяцев', -1, 'onHold', false, '{}'::text[], '{}'::text[], ARRAY['Не из текста письма', 'давний клиент без заказов за 12 месяцев — не длительные отношения, а кандидат в ACCOUNT_DORMANT']::text[], NULL, 16),
  ('ATTR_COMM_SHORTER_COOLER', 'base', 'communication_pattern', 'contact', 'Письма короче и холоднее', 'Выводится на сервере: средняя длина писем контакта за 30 дней короче базовой (90 дней) на 40 % и более, меньше приветствий и благодарностей', 2, 'parked', false, '{}'::text[], '{}'::text[], ARRAY['Не из одного письма', 'мало писем (менее 5 за период) — нет атрибута']::text[], NULL, 17),
  ('ATTR_COMM_SLOWER_RESPONSE', 'base', 'communication_pattern', 'contact', 'Ответы медленнее', 'Выводится на сервере: медианное время ответа контакта за 30 дней выше базовой медианы (90 дней) в 2 раза и более', 2, 'parked', false, '{}'::text[], '{}'::text[], ARRAY['Не из одного письма', 'отпуск контакта (CONTACT_OOO) исключает период']::text[], NULL, 18),
  ('ATTR_COMM_LONGER_WARMER', 'base', 'communication_pattern', 'contact', 'Письма длиннее и теплее', 'Выводится на сервере: письма контакта за 30 дней длиннее базовых на 40 % и более, больше благодарностей и личных фраз', -1, 'parked', false, '{}'::text[], '{}'::text[], ARRAY['Не из одного письма', 'длинная претензия — не «теплее»']::text[], NULL, 19),
  ('ATTR_REL_QUALITY_GOOD', 'base', 'relationship_quality', 'contact', 'Хорошие отношения', 'Выводится на сервере: за 90 дней преобладают позитивные эмоция и тон, нет жалоб', -1, 'parked', false, '{}'::text[], '{}'::text[], ARRAY['Не из одного письма']::text[], NULL, 20),
  ('ATTR_REL_QUALITY_NEUTRAL', 'base', 'relationship_quality', 'contact', 'Нейтральные отношения', 'Выводится на сервере: за 90 дней нет явного перевеса позитивных или негативных атрибутов', 0, 'parked', false, '{}'::text[], '{}'::text[], ARRAY['Не из одного письма']::text[], NULL, 21),
  ('ATTR_REL_QUALITY_BAD', 'base', 'relationship_quality', 'contact', 'Плохие отношения', 'Выводится на сервере: за 90 дней 2 и более жалобы или преобладают негативные эмоция и тон', 2, 'parked', false, '{}'::text[], '{}'::text[], ARRAY['Не из одного письма', 'одна жалоба — не плохие отношения']::text[], NULL, 22),
  ('ATTR_REL_TREND_RISING', 'base', 'relationship_trend', 'contact', 'Отношения улучшаются', 'Выводится на сервере: доля позитивных атрибутов за последние 30 дней выше, чем за предыдущие 60', -1, 'parked', false, '{}'::text[], '{}'::text[], ARRAY['Не из одного письма']::text[], NULL, 23),
  ('ATTR_REL_TREND_STABLE', 'base', 'relationship_trend', 'contact', 'Стабильные отношения', 'Выводится на сервере: доля позитивных и негативных атрибутов за 30 дней в пределах базовой (90 дней)', 0, 'parked', false, '{}'::text[], '{}'::text[], ARRAY['Не из одного письма']::text[], NULL, 24)
