INSERT INTO "signal_relation" ("id", "pack_code", "kind", "code_a", "code_b", "setting_key", "fact", "note_ru") VALUES
  ('rel:leads_over:SIGNAL_AGENCY_CHANGE:SIGNAL_AD_ACTIVITY', 'base', 'leads_over', 'SIGNAL_AGENCY_CHANGE', 'SIGNAL_AD_ACTIVITY', NULL, NULL, 'Решение о смене агентства важнее кампании, которую оно сделало'),
  ('rel:outranks:SIGNAL_MERGER:SIGNAL_INSOLVENCY', 'base', 'outranks', 'SIGNAL_MERGER', 'SIGNAL_INSOLVENCY', NULL, NULL, 'Если вместе с банкротством сообщают о покупке (спасение, продажа бизнеса из процедуры), новость — покупка; банкротство только контекст и не даёт оценку'),
  ('rel:leads_over:SIGNAL_MERGER:SIGNAL_PARTNERSHIP', 'base', 'leads_over', 'SIGNAL_MERGER', 'SIGNAL_PARTNERSHIP', NULL, NULL, 'Когда меняется контроль, сделка важнее партнёрства'),
  ('rel:leads_over:SALES_BOOKING_CANCELLED:ACCOUNT_REVENUE_DECLINE_YOY', 'base', 'leads_over', 'SALES_BOOKING_CANCELLED', 'ACCOUNT_REVENUE_DECLINE_YOY', NULL, NULL, 'Одна карточка отмены заказа; падение выручки — контекст и подтверждение тенденции, а не отдельная карточка'),
  ('rel:both:SIGNAL_ACCOUNT_WIN:SIGNAL_AGENCY_CHANGE', 'base', 'both', 'SIGNAL_ACCOUNT_WIN', 'SIGNAL_AGENCY_CHANGE', NULL, NULL, 'Один тендер с двух сторон: агентство выиграло, рекламодатель сменил агентство; писать для той стороны, которая наш клиент, и называть другую'),
  ('rel:leads_over:SIGNAL_INSOLVENCY:SIGNAL_NEGATIVE_PRESS', 'base', 'leads_over', 'SIGNAL_INSOLVENCY', 'SIGNAL_NEGATIVE_PRESS', NULL, NULL, 'Угроза существованию важнее репутационной'),
  ('rel:leads_over:SIGNAL_NEW_MARKETING_LEAD:SIGNAL_C_LEVEL_CHANGE', 'base', 'leads_over', 'SIGNAL_NEW_MARKETING_LEAD', 'SIGNAL_C_LEVEL_CHANGE', NULL, NULL, 'При смене директора по маркетингу ведёт маркетинговый код'),
  ('rel:leads_over:COMPLAINT_QUANTITY:COMPLAINT_QUALITY', 'base', 'leads_over', 'COMPLAINT_QUANTITY', 'COMPLAINT_QUALITY', NULL, NULL, 'Если привезли меньше, чем заказано, это жалоба на количество, даже если клиент называет это браком'),
  ('rel:leads_over:SIGNAL_MERGER:SIGNAL_FUNDING', 'base', 'leads_over', 'SIGNAL_MERGER', 'SIGNAL_FUNDING', NULL, NULL, 'Когда меняется контроль, покупка важнее инвестиции'),
  ('rel:leads_over:SALES_OFFER_DECLINED:SALES_OFFER_NO_RESPONSE', 'base', 'leads_over', 'SALES_OFFER_DECLINED', 'SALES_OFFER_NO_RESPONSE', NULL, NULL, 'Явный отказ закрывает вопрос; «нет ответа» уже не актуально'),
  ('rel:leads_over:CONTRACT_TERMINATED:CONTRACT_NOT_RENEWED', 'base', 'leads_over', 'CONTRACT_TERMINATED', 'CONTRACT_NOT_RENEWED', NULL, NULL, 'Действие клиента (расторжение) важнее простого истечения срока'),
  ('rel:leads_over:CONTRACT_RENEWAL_INTENT:CONTRACT_FRAME_EXPIRY', 'base', 'leads_over', 'CONTRACT_RENEWAL_INTENT', 'CONTRACT_FRAME_EXPIRY', NULL, NULL, 'Возможность продления важнее предупреждения об окончании договора'),
  ('rel:leads_over:SALES_BOOKING_CANCELLED:SALES_BUDGET_CUT', 'base', 'leads_over', 'SALES_BOOKING_CANCELLED', 'SALES_BUDGET_CUT', NULL, NULL, 'Конкретная потеря заказа важнее общего сокращения бюджета'),
  ('rel:leads_over:SIGNAL_CHANNEL_SHIFT:SIGNAL_SPEND_DOWN', 'base', 'leads_over', 'SIGNAL_CHANNEL_SHIFT', 'SIGNAL_SPEND_DOWN', NULL, NULL, 'Если общий бюджет почти не меняется, это перераспределение между каналами, а не сокращение'),
  ('rel:leads_over:SIGNAL_REBRANDING:SIGNAL_PRODUCT_NEWS', 'base', 'leads_over', 'SIGNAL_REBRANDING', 'SIGNAL_PRODUCT_NEWS', NULL, NULL, 'Если изменился сам бренд, ребрендинг важнее новости о продукте'),
  ('rel:leads_over:ACCOUNT_REVENUE_DECLINE_YOY:ACCOUNT_REVENUE_STAGNATION', 'base', 'leads_over', 'ACCOUNT_REVENUE_DECLINE_YOY', 'ACCOUNT_REVENUE_STAGNATION', NULL, NULL, 'Конкретное текущее падение выручки ведёт; стагнация — контекст'),
  ('rel:both:COMPLAINT_ESCALATED:COMPLAINT_PRICE', 'base', 'both', 'COMPLAINT_ESCALATED', 'COMPLAINT_PRICE', NULL, NULL, 'Эскалация и жалоба на цену под ней — обе в одной карточке'),
  ('rel:both:COMPLAINT_ESCALATED:COMPLAINT_TIMING', 'base', 'both', 'COMPLAINT_ESCALATED', 'COMPLAINT_TIMING', NULL, NULL, 'Эскалация и жалоба на сроки под ней — обе в одной карточке'),
  ('rel:both:COMPLAINT_COMM:COMPLAINT_ESCALATED', 'base', 'both', 'COMPLAINT_COMM', 'COMPLAINT_ESCALATED', NULL, NULL, 'Эскалация и жалоба на коммуникацию под ней — обе в одной карточке'),
  ('rel:both:COMPLAINT_ESCALATED:COMPLAINT_QUANTITY', 'base', 'both', 'COMPLAINT_ESCALATED', 'COMPLAINT_QUANTITY', NULL, NULL, 'Эскалация и жалоба на количество под ней — обе в одной карточке'),
  ('rel:both:COMPLAINT_ESCALATED:COMPLAINT_QUALITY', 'base', 'both', 'COMPLAINT_ESCALATED', 'COMPLAINT_QUALITY', NULL, NULL, 'Эскалация и жалоба на качество под ней — обе в одной карточке'),
  ('rel:both:SALES_NEW_DEMAND:SALES_OFFER_REQUESTED', 'base', 'both', 'SALES_NEW_DEMAND', 'SALES_OFFER_REQUESTED', NULL, NULL, 'Новая потребность — возможность, запрос КП — задача; обе в одной карточке'),
  ('rel:outranks:ORDER_REQUESTED:STOCK_AVAILABILITY_REQUEST', 'distribution', 'outranks', 'ORDER_REQUESTED', 'STOCK_AVAILABILITY_REQUEST', NULL, NULL, 'outranks STOCK_AVAILABILITY_REQUEST and SALES_PRICE_REQUEST on the same subject'),
  ('rel:outranks:ORDER_REQUESTED:SALES_PRICE_REQUEST', 'distribution', 'outranks', 'ORDER_REQUESTED', 'SALES_PRICE_REQUEST', NULL, NULL, 'outranks STOCK_AVAILABILITY_REQUEST and SALES_PRICE_REQUEST on the same subject'),
  ('rel:outranks:ORDER_CANCELLED:ORDER_REQUESTED', 'distribution', 'outranks', 'ORDER_CANCELLED', 'ORDER_REQUESTED', NULL, NULL, 'ORDER_CANCELLED outranks it')
ON CONFLICT DO NOTHING;
