INSERT INTO "signal_relation" ("id", "pack_code", "kind", "code_a", "code_b", "setting_key", "fact", "note_ru") VALUES
  ('rel:outranks:ORDER_CANCELLED:ORDER_CHANGE_REQUESTED', 'distribution', 'outranks', 'ORDER_CANCELLED', 'ORDER_CHANGE_REQUESTED', NULL, NULL, 'ORDER_CANCELLED outranks it'),
  ('rel:both:SALES_PRICE_REQUEST:STOCK_AVAILABILITY_REQUEST', 'distribution', 'both', 'SALES_PRICE_REQUEST', 'STOCK_AVAILABILITY_REQUEST', NULL, NULL, 'both with SALES_PRICE_REQUEST (price and stock in one question = two codes, one topic)'),
  ('rel:both:LISTING_OPPORTUNITY:SAMPLES_REQUESTED', 'distribution', 'both', 'LISTING_OPPORTUNITY', 'SAMPLES_REQUESTED', NULL, NULL, 'both with LISTING_OPPORTUNITY (samples for a card review = one topic, two codes)'),
  ('rel:both:SAMPLES_REQUESTED:TASTING_REQUESTED', 'distribution', 'both', 'SAMPLES_REQUESTED', 'TASTING_REQUESTED', NULL, NULL, 'both with TASTING_REQUESTED'),
