  ('rel:both:PROMO_SUPPORT_REQUESTED:TASTING_REQUESTED', 'distribution', 'both', 'PROMO_SUPPORT_REQUESTED', 'TASTING_REQUESTED', NULL, NULL, 'both with PROMO_SUPPORT_REQUESTED (a wine dinner as promo)'),
  ('rel:both:LISTING_OPPORTUNITY:PROMO_SUPPORT_REQUESTED', 'distribution', 'both', 'LISTING_OPPORTUNITY', 'PROMO_SUPPORT_REQUESTED', NULL, NULL, 'both with LISTING_OPPORTUNITY (входной бонус for a listing)'),
  ('rel:both:LISTING_OPPORTUNITY:NEW_VENUE_OPENING', 'distribution', 'both', 'LISTING_OPPORTUNITY', 'NEW_VENUE_OPENING', NULL, NULL, 'both with NEW_VENUE_OPENING (one topic; the deal type then is new_venue)'),
  ('rel:both:LISTING_OPPORTUNITY:SALES_OFFER_REQUESTED', 'distribution', 'both', 'LISTING_OPPORTUNITY', 'SALES_OFFER_REQUESTED', NULL, NULL, 'both with SALES_OFFER_REQUESTED'),
  ('rel:outranks:NEW_VENUE_OPENING:SIGNAL_EXPANSION', 'distribution', 'outranks', 'NEW_VENUE_OPENING', 'SIGNAL_EXPANSION', NULL, NULL, 'outranks base SIGNAL_EXPANSION on the same subject (the client tells us directly)'),
  ('rel:leads_over:DELISTING_RISK:ORDER_CANCELLED', 'distribution', 'leads_over', 'DELISTING_RISK', 'ORDER_CANCELLED', NULL, NULL, 'leads over ORDER_CANCELLED on the same subject (the delisting is the matter; the cancelled order is context)'),
  ('rel:both:COMPLAINT_PRICE:DELISTING_RISK', 'distribution', 'both', 'COMPLAINT_PRICE', 'DELISTING_RISK', NULL, NULL, 'both with COMPLAINT_PRICE (delisting because of price)'),
  ('rel:outranks:COMPLAINT_TIMING:DELIVERY_SCHEDULE_REQUEST', 'distribution', 'outranks', 'COMPLAINT_TIMING', 'DELIVERY_SCHEDULE_REQUEST', NULL, NULL, 'COMPLAINT_TIMING outranks it when the client already complains about the delay'),
  ('rel:outranks:DELIVERY_DISCREPANCY:COMPLAINT_QUANTITY', 'distribution', 'outranks', 'DELIVERY_DISCREPANCY', 'COMPLAINT_QUANTITY', NULL, NULL, 'outranks base COMPLAINT_QUANTITY on the same subject (недовложение at acceptance is this code for IN4COM)'),
  ('rel:leads_over:DELIVERY_DISCREPANCY:RETURN_REQUESTED', 'distribution', 'leads_over', 'DELIVERY_DISCREPANCY', 'RETURN_REQUESTED', NULL, NULL, 'leads over RETURN_REQUESTED (returning a wrong item is part of the same claim)'),
  ('rel:leads_over:DELIVERY_DISCREPANCY:EGAIS_ISSUE', 'distribution', 'leads_over', 'DELIVERY_DISCREPANCY', 'EGAIS_ISSUE', NULL, NULL, 'leads over EGAIS_ISSUE when the ЕГАИС act only documents a physical discrepancy'),
  ('rel:both:COMPLAINT_ESCALATED:DELIVERY_DISCREPANCY', 'distribution', 'both', 'COMPLAINT_ESCALATED', 'DELIVERY_DISCREPANCY', NULL, NULL, 'both with COMPLAINT_ESCALATED'),
  ('rel:both:COMPLAINT_QUALITY:RETURN_REQUESTED', 'distribution', 'both', 'COMPLAINT_QUALITY', 'RETURN_REQUESTED', NULL, NULL, 'both with base COMPLAINT_QUALITY (return of faulty wine = complaint + task)'),
  ('rel:both:DELISTING_RISK:RETURN_REQUESTED', 'distribution', 'both', 'DELISTING_RISK', 'RETURN_REQUESTED', NULL, NULL, 'both with DELISTING_RISK (return of delisted stock)'),
  ('rel:leads_over:EGAIS_ISSUE:DOCUMENTS_REQUESTED', 'distribution', 'leads_over', 'EGAIS_ISSUE', 'DOCUMENTS_REQUESTED', NULL, NULL, 'leads over DOCUMENTS_REQUESTED («пришлите корректную ТТН» is part of the ЕГАИС issue)'),
  ('rel:leads_over:MARKING_ISSUE:EGAIS_ISSUE', 'distribution', 'leads_over', 'MARKING_ISSUE', 'EGAIS_ISSUE', NULL, NULL, 'MARKING_ISSUE leads over it when the cause is a mark'),
  ('rel:both:MARKING_ISSUE:RETURN_REQUESTED', 'distribution', 'both', 'MARKING_ISSUE', 'RETURN_REQUESTED', NULL, NULL, 'both with RETURN_REQUESTED (bottles with bad marks to be taken back)'),
  ('rel:both:DOCUMENTS_REQUESTED:LICENSE_EXPIRING', 'distribution', 'both', 'DOCUMENTS_REQUESTED', 'LICENSE_EXPIRING', NULL, NULL, 'both with DOCUMENTS_REQUESTED when we ask for the new licence in the same thread (our ask is not a client code)'),
  ('rel:leads_over:DELIVERY_DISCREPANCY:DOCUMENTS_REQUESTED', 'distribution', 'leads_over', 'DELIVERY_DISCREPANCY', 'DOCUMENTS_REQUESTED', NULL, NULL, 'DELIVERY_DISCREPANCY leads over it (a corrected УПД for a discrepancy belongs to that claim)'),
  ('rel:both:PAYMENT_TERMS_REQUEST:SALES_RENEGOTIATION', 'distribution', 'both', 'PAYMENT_TERMS_REQUEST', 'SALES_RENEGOTIATION', NULL, NULL, 'both with base SALES_RENEGOTIATION (price and payment terms in one message = two codes; payment terms only = this code only)')
