  ('rel:both:EXCISE_PRICE_QUERY:ORDER_REQUESTED', 'distribution', 'both', 'EXCISE_PRICE_QUERY', 'ORDER_REQUESTED', NULL, NULL, 'both with ORDER_REQUESTED («закупимся до повышения» = question + order)'),
  ('rel:outranks:COMPLAINT_PRICE:EXCISE_PRICE_QUERY', 'distribution', 'outranks', 'COMPLAINT_PRICE', 'EXCISE_PRICE_QUERY', NULL, NULL, 'base COMPLAINT_PRICE outranks it when the client rejects the new price'),
  ('rel:both:EXCLUSIVITY_REQUESTED:LISTING_OPPORTUNITY', 'distribution', 'both', 'EXCLUSIVITY_REQUESTED', 'LISTING_OPPORTUNITY', NULL, NULL, 'both with LISTING_OPPORTUNITY (exclusivity as a condition of listing)')
