INSERT INTO "deal_risk_type" ("code", "pack_code", "label_ru", "description_ru", "explanation_ru", "trigger_codes", "clear_codes", "severity", "min_occurrences", "condition", "scope", "reaction_role", "stage_guard_template", "note_ru", "enabled") VALUES
  ('DELISTING', 'distribution', 'Клиент выводит позиции', 'Клиент сообщил, что убирает наши позиции из винной карты, ассортимента или матрицы. Объём поставок по сделке может упасть или исчезнуть.', '', ARRAY['DELISTING_RISK']::text[], ARRAY['LISTING_CONFIRMED']::text[], 8, 1, 'deal_type_listing_or_supply', 'client', 'account', 'S1–S5', 'Condition: `deal_type_listing_or_supply` — true when the deal type is `wine_card_listing`, `chain_listing`, `supply_agreement` or `renewal`. A delisting does not matter for a `tender` or `new_venue` deal of another venue.
Stage guard: S1–S5 (all open stages)
Clear codes: `LISTING_CONFIRMED` (proposed: the client confirms that the positions stay or a new listing is agreed)', true),
  ('COMPETITOR_PRICE', 'distribution', 'Конкурент предлагает дешевле', 'Клиент давит на цену: ссылается на более дешёвое предложение другого поставщика или просит пересмотреть цену и скидку. Есть риск проиграть сделку по цене.', '', ARRAY['COMPLAINT_PRICE', 'SALES_RENEGOTIATION']::text[], ARRAY['LISTING_CONFIRMED', 'CONTRACT_RENEWAL_INTENT', 'FEEDBACK_PRICE_PRAISE']::text[], 7, 1, NULL, 'deal', 'account', 'S2–S5', 'Condition: — (payment-only requests are `PAYMENT_TERMS_REQUEST`, not `SALES_RENEGOTIATION`, by the code boundary, so no extra check is needed)
Stage guard: S2–S5 (draft: not at the first contact stage)
Clear codes: `LISTING_CONFIRMED` (proposed), `CONTRACT_RENEWAL_INTENT`, `FEEDBACK_PRICE_PRAISE` (base «условия справедливые»; must be switched on for IN4COM, Open point 14)', true),
  ('DECISION_MAKER_CHANGE', 'distribution', 'Смена закупщика / сомелье', 'Человек, который вёл сделку со стороны клиента (закупщик, сомелье, шеф, категорийный менеджер), уходит или его сменили, а с новым человеком текущие условия ещё не подтверждены.', '', ARRAY['CONTACT_LEAVING', 'CONTACT_NEW_DECISION_MAKER']::text[], ARRAY['LISTING_CONFIRMED', 'CONTRACT_RENEWAL_INTENT']::text[], 6, 1, 'deal_contact_lost_without_handover', 'client', 'relationship', 'S1–S5', 'Condition: `deal_contact_lost_without_handover` — for `CONTACT_LEAVING`: the leaving person is linked to this deal in `deal_contact`, and no other contact of the client has written on a topic of this deal after the trigger item. For `CONTACT_NEW_DECISION_MAKER`: the evidence says the new person replaces someone in the same role, and the deal has no item authored by the new person yet. A job move alone does not trigger it (spec §9.4, Q24-2).
Clear codes: `LISTING_CONFIRMED` (proposed), `CONTRACT_RENEWAL_INTENT` — counted only when the item author is the new person', true),
  ('DECISION_DELAYED', 'distribution', 'Решение откладывается', 'Клиент второй раз откладывает решение по вводу, выбору поставщика или договору и не называет новую дату и следующий шаг.', '', ARRAY['DECISION_POSTPONED', 'MEETING_CANCEL', 'MEETING_DELAYED']::text[], ARRAY['LISTING_CONFIRMED']::text[], 6, 2, 'distinct_postponements_without_new_date', 'deal', 'account', 'S1–S5', 'Triggers: `DECISION_POSTPONED` (proposed), `MEETING_CANCEL`, `MEETING_DELAYED`
Condition: `distinct_postponements_without_new_date` — counts distinct postponements of the **same decision** in the current cycle on topics of this deal; repeated mentions of one postponement count once; a postponement that names a new date and a next step does not count (same rule as Q24-3). Clearing check `date_and_next_step_agreed`: a later item on a deal topic carries `facts.proposedMeetingDate` or a deadline with a next step (cited by `dealState`).
Clear codes: `LISTING_CONFIRMED` (proposed); plus the check `date_and_next_step_agreed`', true),
  ('CLIENT_DEBT', 'distribution', 'Долг клиента', 'У клиента есть просроченная оплата по нашим счетам. Новые договорённости по сделке под риском, пока долг не погашен.', '', ARRAY['INVOICE_OVERDUE']::text[], ARRAY['INVOICE_PAID']::text[], 7, 1, 'no_other_overdue_open', 'client', 'finance', 'S1–S5', 'Condition: `no_other_overdue_open` — used for clearing: the risk clears only when no other `INVOICE_OVERDUE` topic of the same client stays open. Activation needs only an open deal of this client (scope `client`).
Clear codes: `INVOICE_PAID` (a kept `PAYMENT_PROMISE` ends in `INVOICE_PAID`; the promise itself does not clear the risk)', true),
  ('PAYMENT_TERMS_ABOVE_POLICY', 'distribution', 'Жёсткие условия оплаты', 'Клиент просит отсрочку, лимит или работу без предоплаты сверх политики организации. Сделка может состояться только на условиях, которые финансы не согласуют.', '', ARRAY['PAYMENT_TERMS_REQUEST']::text[], ARRAY['LISTING_CONFIRMED']::text[], 5, 1, 'terms_above_policy', 'client', 'finance', 'S1–S5', 'Condition: `terms_above_policy` — true when `facts.paymentTermsDays` > org setting `distribution.maxDeferralDays`, or `facts.creditLimitRequested` > `distribution.maxCreditLimitRub`, or the client asks for no prepayment and has no finalized order in the last 6 months. Missing fact or missing setting → false (insufficient data never produces a warning, spec §5.6).
Clear codes: `LISTING_CONFIRMED` (proposed: the signed agreement fixes the terms); otherwise user «Риск снят» or a cited item via `dealState`', true),
  ('REPEATED_COMPLAINTS', 'distribution', 'Повторные жалобы', 'Клиент жалуется повторно (качество вина, сроки, расхождения при приёмке) или эскалировал жалобу на руководство. Отношения и сделка под угрозой.', '', ARRAY['COMPLAINT_QUALITY', 'COMPLAINT_TIMING', 'COMPLAINT_ESCALATED', 'DELIVERY_DISCREPANCY']::text[], ARRAY['DELIVERY_DISCREPANCY_RESOLVED']::text[], 7, 2, 'complaints_2_in_30d_or_escalated', 'client', 'account', 'S1–S5', 'Min occurrences: 2 (1 for `COMPLAINT_ESCALATED`)
Condition: `complaints_2_in_30d_or_escalated` — at least 2 trigger instances on **distinct** topics of the client within 30 days, or 1 `COMPLAINT_ESCALATED`. Clearing check `trigger_topics_resolved`: all trigger topics are `resolved` (not only `done` or expired, spec §2.1 rule 8).', true),
  ('CONTRACT_EXPIRING_NO_RENEWAL', 'distribution', 'Договор заканчивается без продления', 'Срок договора поставки скоро заканчивается, а клиент не подтвердил продление. Поставки после даты окончания не обеспечены договором.', '', ARRAY['CONTRACT_FRAME_EXPIRY']::text[], ARRAY['CONTRACT_RENEWAL_INTENT', 'LISTING_CONFIRMED']::text[], 8, 1, 'no_renewal_intent_in_window', 'client', 'account', 'S1–S5', 'Condition: `no_renewal_intent_in_window` — no `CONTRACT_RENEWAL_INTENT` of this client between `contractEndDate` − 56 days and now; the deal type is `supply_agreement` or `renewal`.
Clear codes: `CONTRACT_RENEWAL_INTENT`, `LISTING_CONFIRMED` (proposed: renewal signed)', true),
  ('NO_STOCK_FOR_DEAL', 'distribution', 'Нет товара для поставки', 'Позиции, о которых идёт речь в сделке (ввод в карту, тендер), нет на складе, или наш поставщик задерживает их поставку. Мы можем не выполнить обещанное.', '', ARRAY['SUPPLIER_DELIVERY_DELAY', 'STOCK_AVAILABILITY_REQUEST', 'SUBSTITUTION_REQUESTED']::text[], '{}'::text[], 5, 1, 'deal_sku_out_of_stock', 'deal', 'account', 'S2–S5', 'Triggers: `SUPPLIER_DELIVERY_DELAY`, `STOCK_AVAILABILITY_REQUEST`; proposed: `SUBSTITUTION_REQUESTED`
Condition: `deal_sku_out_of_stock` — a product in the trigger subject (`products[]`) matches a product named on the deal''s topics, AND: for `SUPPLIER_DELIVERY_DELAY` the supplier says the product is late; for `STOCK_AVAILABILITY_REQUEST` / `SUBSTITUTION_REQUESTED` our reply on the topic, or the catalog stock when it exists, says «нет в наличии». Without product match or stock evidence → false.
Trigger scope: org + SKU
Stage guard: S2–S5 (positions are known from stage S2)
Clear codes: — (no code confirms stock; user «Риск снят» or a cited item via `dealState`)', true)
ON CONFLICT DO NOTHING;
--> statement-breakpoint
